export type WeaponId =
  | 'pulse'
  | 'katana'
  | 'scatter'
  | 'voidblade'
  | 'nova'
  | 'rail'
  | 'warhammer'
  | 'spear'
  | 'dualblades'
  | 'pickaxe'
  | 'minigun'
  | 'bfg';

export type VehicleId = 'buggy' | 'interceptor' | 'titan';

export interface WeaponSpec {
  id: WeaponId;
  key: string;
  name: string;
  kind: 'ranged' | 'melee';
  cooldown: number;
  damage: number;
  pellets: number;
  spread: number;
  explosive: boolean;
  waveProjectile: boolean;
  speed: number;
  cost: number;
  color: string;
  comboHits?: number;
  knockback?: number;
}

export interface VehicleSpec {
  id: VehicleId;
  name: string;
  desc: string;
  cost: number;
  maxSpeed: number;
  boostSpeed: number;
  accel: number;
  maxHp: number;
  primaryColor: string;
  accentColor: string;
}

