export class ProgressionManager {
  public shards = 120;
  public score = 0;
  public killStreak = 0;
  public killStreakTimer = 0;
  public highScore = 0;
  public totalKills = 0;
  public weapon: WeaponId = 'pulse';
  public vehicle: VehicleId = 'buggy';
  public unlockedWeapons = new Set<WeaponId>(['pulse', 'katana']);
  public unlockedVehicles = new Set<VehicleId>(['buggy']);

  // Infinite Market Upgrades (ZERO CAP!)
  public weaponLv = 1;
  public engineLv = 1;
  public armorLv = 1;
  public dashLv = 1;
  public regenLv = 1;
  public greedLv = 1; // increases shard + score drops infinitely

  // 3+ Charge Blink Dash System
  public dashCharges = 3;
  public maxDashCharges = 3;
  public dashRechargeTimer = 0;
  public dashRechargeDuration = 1.6;
  public blinkIFrameTimer = 0;

  // Dodge Roll w/ Elden Ring i-frames
  public dodgeRollCd = 0;
  public dodgeRollDuration = 0.42;
  public dodgeRolling = false;
  public dodgeRollTimer = 0;
  public iFrames = false;

  // Powers
  public novaCd = 0;
  public shieldCd = 0;
  public shieldActiveTimer = 0;

  // Endless mode tracking
  public endlessWave = 0;
  public endlessActive = false;

  public getWeaponDamageMult(): number {
    return 1 + (this.weaponLv - 1) * 0.24;
  }

  public getEngineSpeedMult(): number {
    return 1 + (this.engineLv - 1) * 0.11;
  }

  public getArmorMaxBonus(): number {
    return (this.armorLv - 1) * 30;
  }

  public getRegenRate(): number {
    return 4.0 + (this.regenLv - 1) * 2.2;
  }

  public getGreedMult(): number {
    return Math.pow(1.22, this.greedLv - 1);
  }

  /** Enemy scaling: enemies dynamically grow tougher as you upgrade & survive higher waves */
  public getEnemyHpMult(): number {
    const upgradePower = (this.weaponLv - 1) + (this.armorLv - 1) * 0.5;
    return 1 + upgradePower * 0.14 + this.endlessWave * 0.15;
  }

  public getEnemyDamageMult(): number {
    return 1 + this.endlessWave * 0.08 + (this.armorLv - 1) * 0.05;
  }

  public getEnemySpeedMult(): number {
    return 1 + Math.min(0.85, this.endlessWave * 0.025);
  }

  public getScoreMultiplier(): number {
    return 1 + Math.min(this.killStreak, 50) * 0.15;
  }

  public addKill(baseScore: number): number {
    this.killStreak++;
    this.killStreakTimer = 5.0;
    this.totalKills++;
    const pts = Math.round(baseScore * this.getScoreMultiplier() * this.getGreedMult());
    this.score += pts;
    this.highScore = Math.max(this.highScore, this.score);
    return pts;
  }

  public addShards(baseAmount: number): number {
    const gain = Math.max(1, Math.round(baseAmount * this.getGreedMult()));
    this.shards += gain;
    return gain;
  }

  public getUpgradeCost(currentLv: number): number {
    return Math.round(25 * Math.pow(1.24, currentLv - 1));
  }

  public unlockOrEquipWeapon(id: WeaponId): boolean {
    if (this.unlockedWeapons.has(id)) {
      this.weapon = id;
      return true;
    }
    const cost = WEAPONS[id].cost;
    if (this.shards < cost) return false;
    this.shards -= cost;
    this.unlockedWeapons.add(id);
    this.weapon = id;
    return true;
  }

  public unlockOrEquipVehicle(id: VehicleId): boolean {
    if (this.unlockedVehicles.has(id)) {
      this.vehicle = id;
      return true;
    }
    const cost = VEHICLES[id].cost;
    if (this.shards < cost) return false;
    this.shards -= cost;
    this.unlockedVehicles.add(id);
    this.vehicle = id;
    return true;
  }

  public upgradeWeapon(): boolean {
    const cost = this.getUpgradeCost(this.weaponLv);
    if (this.shards < cost) return false;
    this.shards -= cost;
    this.weaponLv++;
    return true;
  }

  public upgradeEngine(): boolean {
    const cost = this.getUpgradeCost(this.engineLv);
    if (this.shards < cost) return false;
    this.shards -= cost;
    this.engineLv++;
    return true;
  }

  public upgradeArmor(): boolean {
    const cost = this.getUpgradeCost(this.armorLv);
    if (this.shards < cost) return false;
    this.shards -= cost;
    this.armorLv++;
    return true;
  }

  public upgradeDash(): boolean {
    const cost = this.getUpgradeCost(this.dashLv);
    if (this.shards < cost) return false;
    this.shards -= cost;
    this.dashLv++;
    this.dashRechargeDuration = Math.max(0.32, 1.6 * Math.pow(0.88, this.dashLv - 1));
    this.maxDashCharges = 3 + Math.floor((this.dashLv - 1) / 3);
    this.dashCharges = this.maxDashCharges;
    return true;
  }

  public upgradeRegen(): boolean {
    const cost = this.getUpgradeCost(this.regenLv);
    if (this.shards < cost) return false;
    this.shards -= cost;
    this.regenLv++;
    return true;
  }

  public upgradeGreed(): boolean {
    const cost = this.getUpgradeCost(this.greedLv);
    if (this.shards < cost) return false;
    this.shards -= cost;
    this.greedLv++;
    return true;
  }

  public consumeDash(): boolean {
    if (this.dashCharges <= 0) return false;
    this.dashCharges--;
    this.blinkIFrameTimer = 0.30;
    this.iFrames = true;
    return true;
  }

  public startDodgeRoll(): boolean {
    if (this.dodgeRollCd > 0 || this.dodgeRolling) return false;
    this.dodgeRolling = true;
    this.dodgeRollTimer = this.dodgeRollDuration;
    this.dodgeRollCd = 0.6;
    this.iFrames = true;
    return true;
  }

  public updateCooldowns(dt: number): void {
    this.novaCd = Math.max(0, this.novaCd - dt);
    this.shieldCd = Math.max(0, this.shieldCd - dt);
    this.shieldActiveTimer = Math.max(0, this.shieldActiveTimer - dt);
    this.dodgeRollCd = Math.max(0, this.dodgeRollCd - dt);

    if (this.dashCharges < this.maxDashCharges) {
      this.dashRechargeTimer += dt;
      if (this.dashRechargeTimer >= this.dashRechargeDuration) {
        this.dashRechargeTimer -= this.dashRechargeDuration;
        this.dashCharges = Math.min(this.maxDashCharges, this.dashCharges + 1);
      }
    } else {
      this.dashRechargeTimer = 0;
    }

    if (this.killStreakTimer > 0) {
      this.killStreakTimer -= dt;
      if (this.killStreakTimer <= 0) this.killStreak = 0;
    }

    if (this.blinkIFrameTimer > 0) {
      this.blinkIFrameTimer = Math.max(0, this.blinkIFrameTimer - dt);
    }
    if (this.dodgeRolling) {
      this.dodgeRollTimer -= dt;
      this.iFrames = this.dodgeRollTimer > 0.06 || this.blinkIFrameTimer > 0;
      if (this.dodgeRollTimer <= 0) {
        this.dodgeRolling = false;
        this.iFrames = this.blinkIFrameTimer > 0;
      }
    } else {
      this.iFrames = this.blinkIFrameTimer > 0;
    }
  }
}
