interface DustParticle {
  mesh: THREE.Mesh;
  vel: THREE.Vector3;
  life: number;
}
const dustList: DustParticle[] = [];
const dustGeo = new THREE.SphereGeometry(0.28, 6, 6);
const dustMat = new THREE.MeshBasicMaterial({ color: '#d8c5a0', transparent: true, opacity: 0.45 });

function emitWheelDust(pos: THREE.Vector3, up: THREE.Vector3): void {
  if (dustList.length > 60) return;
  const m = new THREE.Mesh(dustGeo, dustMat);
  m.position.copy(pos).addScaledVector(up, 0.25);
  scene.add(m);
  dustList.push({
    mesh: m,
    vel: up.clone().multiplyScalar(2.4).add(new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5)),
    life: 0.45,
  });
}

