const keys = new Set<string>();
let mouseDown = false;
let rightMouseDown = false;
let isDragging = false;
let lastPointerX = 0;
let lastPointerY = 0;
let mouseIdleTimer = 2.0;

const camAnchor = rover.getCameraAnchor();
let camPrevUp = camAnchor.clone().normalize();
let camTangFwd = rover.getForwardVector();
let aimPitch = 0.04;
let spaceFlightDir = new THREE.Vector3(0, 0.4, -0.9).normalize();
let camHorizonUp = new THREE.Vector3(0, 1, 0);

function handleLookDelta(dx: number, dy: number): void {
  const sPos = getSubjectPosition();
  const near = getNearestPlanet(sPos);
  if (controlMode === 'jet' && near.altitude > 75) {
    // Horizon-stabilized 3D free-space mouse steering (zero gimbal flip!)
    const upAxis = camHorizonUp.clone().normalize();
    const rightAxis = new THREE.Vector3().crossVectors(spaceFlightDir, upAxis);
    if (rightAxis.lengthSq() > 0.001) {
      rightAxis.normalize();
      spaceFlightDir.applyAxisAngle(upAxis, -dx * 0.0022);
      spaceFlightDir.applyAxisAngle(rightAxis, -dy * 0.0022).normalize();
      camHorizonUp.applyAxisAngle(rightAxis, -dy * 0.0022).normalize();
    }
    const pUp = sPos.clone().sub(near.planet.center).normalize();
    aimPitch = Math.asin(THREE.MathUtils.clamp(spaceFlightDir.dot(pUp), -0.92, 0.92));
    const tang = spaceFlightDir.clone().addScaledVector(pUp, -spaceFlightDir.dot(pUp));
    if (tang.lengthSq() > 0.001) camTangFwd.copy(tang.normalize());
  } else {
    const up = near.planet ? camAnchor.clone().sub(near.planet.center).normalize() : new THREE.Vector3(0, 1, 0);
    const yawQuat = new THREE.Quaternion().setFromAxisAngle(up, -dx * 0.0024);
    camTangFwd.applyQuaternion(yawQuat);
    projectOntoTangent(camTangFwd, up, camTangFwd).normalize();
    aimPitch = THREE.MathUtils.clamp(aimPitch - dy * 0.0022, -0.82, 1.15);
    spaceFlightDir.copy(camTangFwd).multiplyScalar(Math.cos(aimPitch)).addScaledVector(up, Math.sin(aimPitch)).normalize();
    camHorizonUp.copy(up);
  }
  mouseIdleTimer = 0;
}

function tryEquipWeaponKey(id: WeaponId): void {
  if (!prog.unlockedWeapons.has(id)) {
    hud.showToast(`${WEAPONS[id].name} Locked — Find in Treasure Chest or Buy in [TAB] Market!`, 2.2);
    return;
  }
  prog.weapon = id;
  syncLoadout();
  hud.showToast(`Equipped: ${WEAPONS[id].name}`, 1.4);
}

function getSubjectPosition(): THREE.Vector3 {
  return controlMode === 'jet' ? jet.position : controlMode === 'rover' ? rover.position : player.position;
}

function openChestIfNear(pos: THREE.Vector3): boolean {
  const nearA = props.chests.find((ch) => !ch.opened && ch.pos.distanceTo(pos) < 6.0);
  if (nearA) {
    nearA.opened = true;
    nearA.lidPivot.rotation.x = -1.35;
    nearA.light.intensity = 2;
    const gain = prog.addShards(nearA.shards);
    if (nearA.rewardWeapon) {
      prog.unlockedWeapons.add(nearA.rewardWeapon);
      prog.weapon = nearA.rewardWeapon;
      syncLoadout();
    }
    sound.playCollect();
    hud.showToast(`CHEST LOOTED (+${gain} Shards): ${nearA.label}`, 3.2);
    return true;
  }
  const nearO = offworld.chests.find((ch) => !ch.opened && ch.pos.distanceTo(pos) < 6.5);
  if (nearO) {
    nearO.opened = true;
    nearO.lidPivot.rotation.x = -1.35;
    nearO.light.intensity = 2;
    const gain = prog.addShards(nearO.shards);
    if (nearO.rewardWeapon) {
      prog.unlockedWeapons.add(nearO.rewardWeapon);
      prog.weapon = nearO.rewardWeapon;
      syncLoadout();
    }
    sound.playCollect();
    hud.showToast(`OFF-WORLD VAULT LOOTED (+${gain} Shards): ${nearO.label}`, 3.5);
    return true;
  }
  return false;
}

window.addEventListener('keydown', (e) => {
  if (e.code === 'Tab') {
    e.preventDefault();
    if (gameStarted) hud.toggleArmory();
    return;
  }

  keys.add(e.code);
  if (!gameStarted || hud.armoryOpen) return;

  if (e.code === 'Digit1') tryEquipWeaponKey('pulse');
  else if (e.code === 'Digit2') tryEquipWeaponKey('katana');
  else if (e.code === 'Digit3') tryEquipWeaponKey('scatter');
  else if (e.code === 'Digit4') tryEquipWeaponKey('voidblade');
  else if (e.code === 'Digit5') tryEquipWeaponKey('nova');
  else if (e.code === 'Digit6') tryEquipWeaponKey('rail');
  else if (e.code === 'Digit7') tryEquipWeaponKey('warhammer');
  else if (e.code === 'Digit8') tryEquipWeaponKey('spear');
  else if (e.code === 'Digit9') tryEquipWeaponKey('dualblades');
  else if (e.code === 'Digit0') tryEquipWeaponKey('pickaxe');
  else if (e.code === 'Minus') tryEquipWeaponKey('minigun');
  else if (e.code === 'Equal') tryEquipWeaponKey('bfg');
  else if (e.code === 'KeyZ' || e.code === 'AltLeft' || e.code === 'ControlLeft' || e.code === 'ControlRight') {
    e.preventDefault();
    if (controlMode === 'foot' && prog.startDodgeRoll()) {
      const camDir = new THREE.Vector3();
      camera.getWorldDirection(camDir);
      player.triggerDodgeRoll(camDir);
      hud.showToast('Elden Dodge Roll! (Invulnerable)', 0.9);
      sound.playLaser(false);
    }
  } else if (e.code === 'KeyQ') {
    if (prog.consumeDash()) {
      const camDir = new THREE.Vector3();
      camera.getWorldDirection(camDir);
      if (controlMode === 'jet') {
        jet.velocity.copy(camDir).multiplyScalar(145);
        hud.showToast(`Jet Warp Dash! (${prog.dashCharges}/${prog.maxDashCharges})`, 1.0);
      } else if (controlMode === 'rover') {
        const fwd = rover.getForwardVector();
        rover.velocity.copy(fwd).multiplyScalar(62);
        hud.showToast(`Turbo Blink Surge! (${prog.dashCharges}/${prog.maxDashCharges})`, 1.0);
      } else {
        player.triggerDash(camDir, physics);
        hud.showToast(`Blink Teleport! (${prog.dashCharges}/${prog.maxDashCharges})`, 1.0);
      }
      sound.playLaser(true);
    } else {
      hud.showToast('Dash Recharging...', 0.8);
    }
  } else if (e.code === 'KeyC' && prog.novaCd <= 0) {
    prog.novaCd = 7.0;
    const center = getSubjectPosition();
    const dmg = 115 * prog.getWeaponDamageMult();
    const kills = combat.triggerNovaBlast(center, 24, dmg);
    const wRes = wildlife.damageAtPoint(center, 24, dmg, center);
    // Also fell all trees inside Shockwave Nova blast radius!
    let felledTrees = 0;
    for (const col of physics.colliders) {
      if (!col.broken && col.kind === 'tree' && col.pos.distanceTo(center) <= 22) {
        if (props.knockDownTree(col, col.pos.clone().sub(center), 22)) felledTrees++;
      }
    }
    if (felledTrees > 0) {
      prog.addShards(felledTrees * 5);
      prog.addKill(felledTrees * 25);
    }
    if (kills + wRes.kills > 0) {
      prog.addShards((kills + wRes.kills) * 18);
      for (let i = 0; i < kills + wRes.kills; i++) prog.addKill(150);
    }
    cameraShake = 0.55;
    sound.playExplosion();
    hud.showToast('Shockwave Nova Unleashed!', 1.5);
  } else if (e.code === 'KeyV' && prog.shieldCd <= 0) {
    prog.shieldCd = 12.0;
    prog.shieldActiveTimer = 6.0;
    sound.playCollect();
    hud.showToast('Aegis Shield Dome Active (6s)', 1.8);
  } else if (e.code === 'KeyE') {
    openChestIfNear(getSubjectPosition());
  } else if (e.code === 'KeyF') {
    if (controlMode === 'rover') {
      controlMode = 'foot';
      player.activePlanet = rover.activePlanet;
      player.position.copy(rover.getDriverExitPosition(physics));
      player.prevUp.copy(player.getUpVector());
      player.orientation.setFromUnitVectors(new THREE.Vector3(0, 1, 0), player.prevUp);
      player.radialVel = 0;
      player.grounded = true;
      player.velocity.set(0, 0, 0);
      player.setVisible(true);
      hud.showToast('Exited Rover — On Foot ([Ctrl] Roll, [Q] Blink, [G] Jet)', 2.2);
    } else if (controlMode === 'foot') {
      if (rover.isNear(player.position, 6.5)) {
        controlMode = 'rover';
        player.setVisible(false);
        hud.showToast('Boarded Rover', 1.6);
      } else {
        hud.showToast('Too far from Rover — Press [R] to Recall or [G] for Air Force Jet!', 2.0);
      }
    } else if (controlMode === 'jet') {
      const nearest = getNearestPlanet(jet.position);
      const localDir = jet.position.clone().sub(nearest.planet.center).normalize();
      if (nearest.altitude < 75) {
        controlMode = 'foot';
        player.activePlanet = nearest.planet;
        player.position.copy(getPlanetSurfacePosition(nearest.planet, localDir, 1.5));
        player.prevUp.copy(localDir);
        player.orientation.setFromUnitVectors(new THREE.Vector3(0, 1, 0), localDir);
        player.velocity.set(0, 0, 0);
        player.radialVel = 0;
        player.setVisible(true);
        sound.playCollect();
        hud.showToast(`Ejected onto ${nearest.planet.name}! ([R] Call Rover here!)`, 2.5);
      } else {
        // Emergency Auto-Descent onto nearest planet — NEVER soft-lock in Deep Space!
        const surfPos = getPlanetSurfacePosition(nearest.planet, localDir, 18);
        jet.placeAt(surfPos, nearest.planet);
        spaceFlightDir.copy(jet.getForwardVector());
        camTangFwd.copy(jet.getForwardVector());
        hud.showToast(`Autopilot Descended to ${nearest.planet.name}! Press [F]/[G] to Land!`, 2.4);
      }
    }
  } else if (e.code === 'KeyG') {
    if (controlMode === 'jet') {
      const nearest = getNearestPlanet(jet.position);
      const localDir = jet.position.clone().sub(nearest.planet.center).normalize();
      if (nearest.altitude < 75) {
        controlMode = 'foot';
        player.activePlanet = nearest.planet;
        player.position.copy(getPlanetSurfacePosition(nearest.planet, localDir, 1.5));
        player.prevUp.copy(localDir);
        player.orientation.setFromUnitVectors(new THREE.Vector3(0, 1, 0), localDir);
        player.velocity.set(0, 0, 0);
        player.radialVel = 0;
        player.setVisible(true);
        hud.showToast(`Disembarked Jet on ${nearest.planet.name}`, 2.0);
      } else {
        const surfPos = getPlanetSurfacePosition(nearest.planet, localDir, 18);
        jet.placeAt(surfPos, nearest.planet);
        spaceFlightDir.copy(jet.getForwardVector());
        camTangFwd.copy(jet.getForwardVector());
        hud.showToast(`Autopilot Descended to ${nearest.planet.name}! Press [G] again to Disembark!`, 2.4);
      }
    } else {
      const sPos = getSubjectPosition();
      const nearest = getNearestPlanet(sPos);
      if (!jet.isNear(sPos, 24)) {
        const up = sPos.clone().sub(nearest.planet.center).normalize();
        const ref = Math.abs(up.x) < 0.85 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 0, 1);
        const right = new THREE.Vector3().crossVectors(ref, up).normalize();
        const callDir = sPos.clone().sub(nearest.planet.center).addScaledVector(right, 14).normalize();
        jet.placeAt(getPlanetSurfacePosition(nearest.planet, callDir, 1.2), nearest.planet);
      }
      controlMode = 'jet';
      player.setVisible(false);
      const jFwd = jet.getForwardVector();
      spaceFlightDir.copy(jFwd);
      camTangFwd.copy(jFwd);
      camHorizonUp.copy(jet.getUpVector());
      sound.playLaser(true);
      hud.showToast('AIR FORCE JET ACTIVE! [Space]/[↑] Climb · [X]/[↓] Dive · [Shift]+[W] Warp!', 3.2);
    }
  } else if (e.code === 'KeyR') {
    if (roverRecallCd > 0) {
      hud.showToast(`Rover Recall Recharging (${roverRecallCd.toFixed(0)}s)`, 1.2);
      return;
    }
    roverRecallCd = 10.0;
    const sPos = getSubjectPosition();
    const nearest = getNearestPlanet(sPos);
    const localDir = sPos.clone().sub(nearest.planet.center).normalize();
    rover.respawn(nearest.planet, localDir);
    if (controlMode === 'foot') {
      controlMode = 'rover';
      player.setVisible(false);
      camAnchor.copy(rover.getCameraAnchor());
      camPrevUp.copy(rover.getUpVector());
      camTangFwd.copy(rover.getForwardVector());
    }
    hud.showToast(`Rover Deployed to ${nearest.planet.name}!`, 2.0);
  }
});

window.addEventListener('keyup', (e) => keys.delete(e.code));
canvas.addEventListener('contextmenu', (e) => e.preventDefault());

canvas.addEventListener('mousedown', (e) => {
  if (!gameStarted || hud.armoryOpen) return;
  sound.unlock();
  if (e.button === 0) {
    mouseDown = true;
    isDragging = true;
    lastPointerX = e.clientX;
    lastPointerY = e.clientY;
    if (document.pointerLockElement !== canvas) safePointerLock();
  } else if (e.button === 2) {
    rightMouseDown = true;
  }
});

window.addEventListener('mouseup', (e) => {
  if (e.button === 0) {
    mouseDown = false;
    isDragging = false;
  } else if (e.button === 2) {
    rightMouseDown = false;
  }
});

window.addEventListener('mousemove', (e) => {
  if (!gameStarted || hud.armoryOpen) return;
  if (document.pointerLockElement === canvas) {
    handleLookDelta(e.movementX, e.movementY);
  } else if (isDragging) {
    const dx = e.clientX - lastPointerX;
    const dy = e.clientY - lastPointerY;
    lastPointerX = e.clientX;
    lastPointerY = e.clientY;
    handleLookDelta(dx, dy);
  }
});

window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  postfx.resize(w, h);
});

const clock = new THREE.Clock();
const _camWorldDir = new THREE.Vector3();
const _aimPoint = new THREE.Vector3();
const _desiredCamPos = new THREE.Vector3();
const _aimRayDir = new THREE.Vector3();

function computeAccurateAimPoint(camPos: THREE.Vector3, rayDir: THREE.Vector3, minDist: number): THREE.Vector3 {
  let bestT = 260;

  const allEnemies = [...combat.dynamicEnemies, ...combat.camps.flatMap((c) => c.enemies)];
  for (const enemy of allEnemies) {
    if (!enemy.alive) continue;
    const eUp = enemy.position.clone().sub(enemy.planet.center).normalize();
    const eCenter = enemy.position.clone().addScaledVector(eUp, 1.3);
    const toE = eCenter.sub(camPos);
    const proj = toE.dot(rayDir);
    if (proj > minDist && proj < bestT) {
      const r = enemy.kind === 'boss' ? 3.2 : 2.1;
      if (toE.lengthSq() - proj * proj <= r * r) bestT = proj;
    }
  }

  for (const c of wildlife.creatures) {
    if (!c.alive) continue;
    const cCenter = c.position.clone().addScaledVector(c.position.clone().normalize(), c.kind === 'manta' ? 0.2 : 1.1);
    const toC = cCenter.sub(camPos);
    const proj = toC.dot(rayDir);
    if (proj > minDist && proj < bestT && toC.lengthSq() - proj * proj <= 2.2 * 2.2) bestT = proj;
  }

  for (const camp of combat.camps) {
    if (camp.cleared) continue;
    const corePos = camp.center.clone().addScaledVector(camp.center.clone().normalize(), 3.5);
    const toC = corePos.sub(camPos);
    const proj = toC.dot(rayDir);
    if (proj > minDist && proj < bestT && toC.lengthSq() - proj * proj <= 2.8 * 2.8) bestT = proj;
  }

  for (const cit of offworld.citadels) {
    if (cit.cleared) continue;
    const cUp = cit.center.clone().sub(cit.planet.center).normalize();
    const corePos = cit.center.clone().addScaledVector(cUp, 4.6);
    const toC = corePos.sub(camPos);
    const proj = toC.dot(rayDir);
    if (proj > minDist && proj < bestT && toC.lengthSq() - proj * proj <= 3.5 * 3.5) bestT = proj;
  }

  const terrainHit = raycastTerrain(camPos, rayDir, minDist, bestT, currentPlanet);
  if (terrainHit !== null && terrainHit < bestT) bestT = terrainHit;

  return camPos.clone().addScaledVector(rayDir, bestT);
}

function animate(): void {
  requestAnimationFrame(animate);
  const dt = Math.min(0.05, clock.getDelta());
  const time = clock.elapsedTime;
  mouseIdleTimer += dt;

  const activeLoop = gameStarted && !hud.armoryOpen;
  if (activeLoop) {
    prog.updateCooldowns(dt);
    if (roverRecallCd > 0) roverRecallCd = Math.max(0, roverRecallCd - dt);
  }

  // Keyboard Air Force Jet Pitch / Dive / Turn so flying works 100% smoothly with OR without Pointer Lock!
  if (activeLoop && controlMode === 'jet') {
    const pitchCmd = (keys.has('ArrowUp') || keys.has('Space') ? 1 : 0) - (keys.has('ArrowDown') || keys.has('KeyX') ? 1 : 0);
    const yawCmd = (keys.has('KeyA') ? 1 : 0) - (keys.has('KeyD') ? 1 : 0);
    if (pitchCmd !== 0 || yawCmd !== 0) {
      const nearJ = getNearestPlanet(jet.position);
      if (nearJ.altitude > 75) {
        const upAx = camHorizonUp.clone().normalize();
        const rAx = new THREE.Vector3().crossVectors(spaceFlightDir, upAx).normalize();
        if (yawCmd !== 0) spaceFlightDir.applyAxisAngle(upAx, yawCmd * 1.35 * dt).normalize();
        if (pitchCmd !== 0) {
          spaceFlightDir.applyAxisAngle(rAx, pitchCmd * 1.15 * dt).normalize();
          camHorizonUp.applyAxisAngle(rAx, pitchCmd * 1.15 * dt).normalize();
        }
      } else {
        const pUp = jet.position.clone().sub(nearJ.planet.center).normalize();
        if (yawCmd !== 0) {
          camTangFwd.applyAxisAngle(pUp, yawCmd * 1.45 * dt);
          projectOntoTangent(camTangFwd, pUp, camTangFwd).normalize();
        }
        if (pitchCmd !== 0) {
          aimPitch = THREE.MathUtils.clamp(aimPitch + pitchCmd * 1.15 * dt, -1.25, 1.32);
        }
        spaceFlightDir.copy(camTangFwd).multiplyScalar(Math.cos(aimPitch)).addScaledVector(pUp, Math.sin(aimPitch)).normalize();
      }
    }
  }

  const w = keys.has('KeyW') || keys.has('ArrowUp') ? 1 : 0;
  const s = keys.has('KeyS') || keys.has('ArrowDown') ? 1 : 0;
  const a = keys.has('KeyA') || keys.has('ArrowLeft') ? 1 : 0;
  const dKey = keys.has('KeyD') || keys.has('ArrowRight') ? 1 : 0;

  const throttle = w - s;
  const steer = a - dKey;
  const rightInput = dKey - a;
  const boostOrSprint = keys.has('ShiftLeft') || keys.has('ShiftRight');
  const space = keys.has('Space');

  const shieldActive = prog.shieldActiveTimer > 0;

  const subjectPos = getSubjectPosition();
  const nearestInfo = getNearestPlanet(subjectPos);
  currentPlanet = nearestInfo.planet;
  const spaceBlend = controlMode === 'jet' ? THREE.MathUtils.clamp((nearestInfo.altitude - 55) / 50, 0, 1) : 0;
  const inDeepSpace = spaceBlend > 0.5;

  const targetAnchor =
    controlMode === 'jet' ? jet.getCameraAnchor() : controlMode === 'rover' ? rover.getCameraAnchor() : player.getCameraAnchor();
  camAnchor.lerp(targetAnchor, Math.min(1, dt * 16));

  const planetUp = camAnchor.clone().sub(currentPlanet.center).normalize();
  if (!inDeepSpace) {
    const dQuat = new THREE.Quaternion().setFromUnitVectors(camPrevUp, planetUp);
    camTangFwd.applyQuaternion(dQuat);
    projectOntoTangent(camTangFwd, planetUp, camTangFwd);
    if (camTangFwd.lengthSq() > 0.0001) camTangFwd.normalize();
    else projectOntoTangent(rover.getForwardVector(), planetUp, camTangFwd).normalize();

    if (controlMode === 'rover' && mouseIdleTimer > 1.3 && Math.abs(rover.forwardSpeed) > 3) {
      const roverFwd = rover.getForwardVector();
      projectOntoTangent(roverFwd, planetUp, roverFwd).normalize();
      camTangFwd.lerp(roverFwd, Math.min(1, dt * 3.0)).normalize();
    }
    camHorizonUp.lerp(planetUp, Math.min(1, dt * 4.5)).normalize();
  } else {
    // Keep camTangFwd + aimPitch synced smoothly to spaceFlightDir so re-entering any planet's gravity well NEVER snaps!
    aimPitch = Math.asin(THREE.MathUtils.clamp(spaceFlightDir.dot(planetUp), -0.9, 0.9));
    const tangSync = spaceFlightDir.clone().addScaledVector(planetUp, -spaceFlightDir.dot(planetUp));
    if (tangSync.lengthSq() > 0.001) camTangFwd.copy(tangSync.normalize());
  }
  camPrevUp.copy(planetUp);
  const up = planetUp.clone().lerp(camHorizonUp, spaceBlend).normalize();

  const camRight = new THREE.Vector3().crossVectors(inDeepSpace ? spaceFlightDir : camTangFwd, up).normalize();
  const curCave = currentPlanet.id === 'aetheria' ? evaluateCaveAtDir(subjectPos.clone().normalize()) : null;
  const inCaveNow = curCave !== null && curCave.inCorridor && curCave.localZ < -1.5 && subjectPos.length() < curCave.ceilingR;

  scene.environmentIntensity = THREE.MathUtils.lerp(scene.environmentIntensity, inCaveNow ? 0.16 : 0.85, Math.min(1, dt * 6));
  hemiLight.color.set(currentPlanet.ambientTint);

  let camDist =
    controlMode === 'jet'
      ? 14.5
      : controlMode === 'rover'
      ? inCaveNow
        ? 7.2
        : 9.4
      : inCaveNow
      ? 4.4
      : 5.2;
  if (controlMode === 'foot' && rightMouseDown) camDist = 3.2;
  const shoulderOffset = controlMode === 'foot' ? 0.78 : 0.0;

  if (inDeepSpace) {
    _aimRayDir.copy(spaceFlightDir).normalize();
  } else {
    _aimRayDir
      .copy(camTangFwd)
      .multiplyScalar(Math.cos(aimPitch))
      .addScaledVector(up, Math.sin(aimPitch))
      .normalize();
  }

  _desiredCamPos
    .copy(camAnchor)
    .addScaledVector(_aimRayDir, -camDist)
    .addScaledVector(camRight, shoulderOffset)
    .addScaledVector(up, controlMode === 'jet' ? 2.4 : 0.55);

  camera.position.lerp(_desiredCamPos, Math.min(1, dt * 18));

  let radialLift = 0;
  if (!inDeepSpace) {
    for (let sStep = 1; sStep <= 3; sStep++) {
      const samplePt = camAnchor.clone().lerp(camera.position, sStep / 3);
      const sLocal = samplePt.clone().sub(currentPlanet.center);
      const sDir = sLocal.clone().normalize();
      const minR = Math.max(currentPlanet.seaLevel, getPlanetTerrainHeight(sDir, currentPlanet.id)) + 1.05;
      if (sLocal.length() < minR) radialLift = Math.max(radialLift, minR - sLocal.length());
    }
    const camLocal = camera.position.clone().sub(currentPlanet.center);
    const camDirNorm = camLocal.clone().normalize();
    if (radialLift > 0) camera.position.addScaledVector(camDirNorm, radialLift);
    if (currentPlanet.id === 'aetheria') {
      const cCamInfo = evaluateCaveAtDir(camDirNorm);
      if (cCamInfo && cCamInfo.inCorridor && cCamInfo.localZ < -1.5 && camLocal.length() < cCamInfo.ceilingR + 2.0) {
        const maxR = cCamInfo.ceilingR - 1.5;
        if (camLocal.length() > maxR) camera.position.copy(camDirNorm).multiplyScalar(maxR);
      }
    }
    physics.resolveCollisions(camera.position, _desiredCamPos.set(0, 0, 0), 0.72, currentPlanet);
  }

  if (cameraShake > 0) {
    cameraShake = Math.max(0, cameraShake - dt * 2.5);
    camera.position.addScaledVector(camRight, (Math.random() - 0.5) * cameraShake * 0.5);
    camera.position.addScaledVector(up, (Math.random() - 0.5) * cameraShake * 0.5);
  }

  const speedRatio =
    controlMode === 'jet'
      ? Math.min(1, jet.speed / 120)
      : controlMode === 'rover'
      ? Math.min(1, Math.abs(rover.forwardSpeed) / 50)
      : 0;
  const targetFov = rightMouseDown && controlMode === 'foot' ? 46 : 64 + speedRatio * 18;
  camera.fov = THREE.MathUtils.lerp(camera.fov, targetFov, Math.min(1, dt * 8));
  camera.updateProjectionMatrix();

  camera.up.copy(up);
  const lookTarget = camAnchor
    .clone()
    .addScaledVector(_aimRayDir, 50)
    .addScaledVector(camRight, shoulderOffset)
    .addScaledVector(up, (controlMode === 'jet' ? 1.8 : 0.55) + radialLift);
  camera.lookAt(lookTarget);

  camera.getWorldDirection(_camWorldDir);
  const dynamicMinDist = camera.position.distanceTo(subjectPos) + (controlMode === 'foot' ? 0.65 : 2.2);
  _aimPoint.copy(computeAccurateAimPoint(camera.position, _camWorldDir, dynamicMinDist));

  if (activeLoop) {
    rover.update(
      dt,
      { throttle, steer, brake: space, boost: boostOrSprint },
      controlMode === 'rover',
      physics,
      prog.getEngineSpeedMult(),
      shieldActive,
      _aimPoint,
      (col, impDir, spd) => {
        const felled = props.knockDownTree(col, impDir, spd);
        if (felled) {
          prog.addShards(5);
          prog.addKill(25);
          cameraShake = Math.max(cameraShake, 0.28);
          sound.playExplosion();
          hud.showToast('TIMBER! Tree Torn Down (+5 Shards)', 1.2);
        }
        return felled;
      }
    );

    if (rover.lastImpactSpeed > 12) cameraShake = Math.max(cameraShake, 0.3);

    if (controlMode === 'rover' && rover.grounded && (Math.abs(rover.forwardSpeed) > 18 || rover.isDrifting)) {
      if (Math.random() < 0.65) {
        emitWheelDust(rover.position.clone().addScaledVector(rover.getForwardVector(), -1.6), up);
      }
    }

    if (controlMode === 'rover' && rover.grounded && currentPlanet.id === 'aetheria') {
      for (const pad of props.boostPads) {
        if (rover.position.distanceTo(pad.pos) < 3.8) {
          rover.launchJumpPad();
          sound.playLaser(true);
          cameraShake = 0.35;
          hud.showToast('MEGA BOOST LAUNCH!', 1.5);
        }
      }
    }

    jet.update(
      dt,
      {
        throttle,
        bank: steer,
        hoverUp: space,
        afterburner: boostOrSprint,
        firing: mouseDown,
      },
      controlMode === 'jet',
      _aimRayDir,
      prog.getEngineSpeedMult()
    );

    if (controlMode === 'foot') {
      player.update(
        dt,
        time,
        {
          forward: throttle,
          right: rightInput,
          jump: space,
          sprint: boostOrSprint,
          firing: mouseDown,
        },
        _camWorldDir,
        physics,
        shieldActive
      );
    }

    // Combat: Air Force Jet Cannons/Missiles OR Rover Turret OR On-Foot Weapons & Melee!
    fireCooldown -= dt;
    if (controlMode === 'jet' && (mouseDown || rightMouseDown) && fireCooldown <= 0) {
      const isMissile = rightMouseDown;
      fireCooldown = isMissile ? 0.52 : 0.08;
      const [mL, mR] = jet.getMuzzlesWorldPos();
      const dL = _aimPoint.clone().sub(mL).normalize();
      const dR = _aimPoint.clone().sub(mR).normalize();
      const dmg = (isMissile ? 145 : 44) * prog.getWeaponDamageMult();
      if (isMissile) {
        combat.firePlayerBolt(mL, dL, dmg, '#ff5277', true, 200, false, currentPlanet);
        sound.playExplosion();
        hud.showToast('Plasma Missile Launched!', 0.8);
      } else {
        combat.firePlayerBolt(mL, dL, dmg, '#4de8ff', false, 240, false, currentPlanet);
        combat.firePlayerBolt(mR, dR, dmg, '#4de8ff', false, 240, false, currentPlanet);
        sound.playLaser(true);
      }
    } else if (mouseDown && fireCooldown <= 0) {
      const spec = WEAPONS[prog.weapon];
      if (controlMode === 'foot' && spec.kind === 'melee') {
        fireCooldown = spec.cooldown;
        player.triggerKatanaSlash(_camWorldDir, spec.comboHits ?? 3);
        const dmg = spec.damage * prog.getWeaponDamageMult();
        const reach = prog.weapon === 'spear' ? 7.8 : prog.weapon === 'warhammer' ? 7.2 : 6.4;
        const slashCenter = player.position.clone().addScaledVector(projectOntoTangent(_camWorldDir, up).normalize(), 1.8);
        const res = combat.performMeleeSlash(
          player.position,
          projectOntoTangent(_camWorldDir, up).normalize(),
          reach,
          dmg,
          spec.color,
          spec.waveProjectile,
          currentPlanet,
          prog.weapon === 'warhammer',
          spec.knockback ?? 6
        );

        const wRes = wildlife.damageAtPoint(slashCenter, reach, dmg, player.position);
        if (wRes.kills > 0) {
          const gain = prog.addShards(wRes.shards);
          for (let i = 0; i < wRes.kills; i++) prog.addKill(90);
          hud.showToast(`Wildlife Hunted (+${gain} Shards)!`, 1.4);
        }

        const hitTree = physics.findHitTree(slashCenter, reach);
        if (hitTree && props.damageTree(hitTree, dmg * (prog.weapon === 'pickaxe' ? 2.5 : 1.0), _camWorldDir)) {
          const g = prog.addShards(prog.weapon === 'pickaxe' ? 12 : 5);
          prog.addKill(25);
          hud.showToast(`Tree Felled (+${g} Shards)!`, 1.2);
        }

        // Damage Crystal Nodes (Home + Offworld)
        for (const node of props.crystalNodes) {
          if (!node.destroyed && node.pos.distanceTo(player.position) < 6.5) {
            node.hp -= dmg * (prog.weapon === 'pickaxe' ? 2.0 : 1.0);
            if (node.hp <= 0) {
              node.destroyed = true;
              node.mesh.visible = false;
              const g = prog.addShards(prog.weapon === 'pickaxe' ? 40 : 25);
              sound.playCollect();
              hud.showToast(`Crystal Shattered (+${g} Shards)!`, 1.8);
            }
          }
        }
        for (const cr of offworld.crystals) {
          if (!cr.destroyed && cr.pos.distanceTo(player.position) < 6.5) {
            cr.hp -= dmg;
            if (cr.hp <= 0) {
              cr.destroyed = true;
              cr.mesh.visible = false;
              const g = prog.addShards(35);
              sound.playCollect();
              hud.showToast(`Off-World Crystal (+${g} Shards)!`, 1.8);
            }
          }
        }
        // Damage Off-World Citadels with Melee!
        for (const cit of offworld.citadels) {
          if (!cit.cleared && cit.center.distanceTo(player.position) < 8.5) {
            cit.hp -= dmg;
            if (cit.hp <= 0) {
              cit.cleared = true;
              cit.coreMesh.visible = false;
              cit.coreRing.visible = false;
              const g = prog.addShards(150);
              prog.addKill(800);
              sound.playExplosion();
              hud.showToast(`${cit.planet.name.toUpperCase()} LIBERATED! (+${g} Shards)`, 4.0);
            }
          }
        }

        if (res.kills > 0) {
          prog.addShards(res.kills * 18);
          for (let i = 0; i < res.kills; i++) prog.addKill(150);
        }
        if (res.campCleared) {
          const g = prog.addShards(75);
          prog.addKill(500);
          hud.showToast(`OUTPOST CONQUERED (+${g} Shards): ${res.campCleared}`, 3.5);
        }
        if (res.deflected > 0) hud.showToast('KATANA PARRY DEFLECT!', 1.4);
        sound.playLaser(false);
      } else {
        const rSpec = spec.kind === 'melee' ? WEAPONS.pulse : spec;
        fireCooldown = rSpec.cooldown;
        const muzzle = controlMode === 'rover' ? rover.getBarrelWorldPos() : player.getMuzzleWorldPos();
        const baseDir = _aimPoint.clone().sub(muzzle).normalize();
        if (baseDir.dot(_camWorldDir) < 0.25) baseDir.copy(_camWorldDir);
        const dmg = rSpec.damage * prog.getWeaponDamageMult();

        for (let p = 0; p < rSpec.pellets; p++) {
          const dir = baseDir.clone();
          if (rSpec.spread > 0) {
            dir.x += (Math.random() - 0.5) * rSpec.spread;
            dir.y += (Math.random() - 0.5) * rSpec.spread;
            dir.z += (Math.random() - 0.5) * rSpec.spread;
            dir.normalize();
          }
          combat.firePlayerBolt(muzzle, dir, dmg, rSpec.color, rSpec.explosive, rSpec.speed, false, currentPlanet);
        }
        sound.playLaser(controlMode === 'rover');
      }
    }
  } else {
    rover.update(dt, { throttle: 0, steer: 0, brake: false, boost: false }, false, physics);
  }

  motePoints.position.copy(subjectPos);
  for (let i = dustList.length - 1; i >= 0; i--) {
    const dp = dustList[i];
    dp.life -= dt;
    dp.mesh.position.addScaledVector(dp.vel, dt);
    dp.mesh.scale.setScalar(1 + (0.45 - dp.life) * 3.0);
    if (dp.life <= 0) {
      scene.remove(dp.mesh);
      dustList.splice(i, 1);
    }
  }

  if (props.trialActive) {
    props.trialTimer -= dt;
    if (props.trialTimer <= 0) {
      props.trialActive = false;
      props.trialRings.forEach((r) => (r.passed = false));
      hud.showToast('Speed Trial Expired — Try Again!', 2.2);
    }
  }
  const nextRing = props.trialRings.find((r) => !r.passed);
  if (nextRing && subjectPos.distanceTo(nextRing.pos) < 6.0) {
    nextRing.passed = true;
    (nextRing.mesh.material as THREE.MeshBasicMaterial).color.set('#5effa8');
    sound.playCollect();
    if (!props.trialActive) {
      props.trialActive = true;
      props.trialTimer = 42.0;
      hud.showToast('SPEED TRIAL STARTED! Race through all 6 Rings!', 2.8);
    } else if (props.trialRings.every((r) => r.passed)) {
      props.trialActive = false;
      const g = prog.addShards(150);
      prog.addKill(600);
      hud.showToast(`SPEED TRIAL COMPLETE! +${g} Aether Shards!`, 3.8);
    }
  }

  sunLight.position.copy(subjectPos).addScaledVector(sunDir, 130);
  sunLight.target.position.copy(subjectPos);
  sunLight.target.updateMatrixWorld();

  planet.update(time, sunDir);
  surroundings.update(time, sunDir);
  offworld.update(time, sunDir);

  // Off-World Citadel Defender Waves when Jet/Player approaches!
  for (const cit of offworld.citadels) {
    if (!cit.cleared && !cit.waveSpawned && subjectPos.distanceTo(cit.center) < 65) {
      cit.waveSpawned = true;
      hud.showToast(`${cit.planet.name.toUpperCase()}: Syndicate Garrison Deploying!`, 3.2);
      const hpM = prog.getEnemyHpMult();
      const dmM = prog.getEnemyDamageMult();
      combat.spawnEnemy('scout', cit.center, 0.5, 11, undefined, hpM, dmM, 1.0, cit.planet);
      combat.spawnEnemy('berserker', cit.center, 2.2, 10, undefined, hpM, dmM, 1.0, cit.planet);
      combat.spawnEnemy('sniper', cit.center, 4.0, 14, undefined, hpM, dmM, 1.0, cit.planet);
      combat.spawnEnemy('boss', cit.center, 5.5, 9, undefined, hpM * 1.4, dmM * 1.2, 1.0, cit.planet, `${cit.planet.name} Warden`);
    }
  }

  // Update interactive wildlife (only tick simulation while unpaused!)
  const wildVel = controlMode === 'rover' ? rover.velocity : controlMode === 'foot' ? player.velocity : jet.velocity;
  const wildlifeEvents = activeLoop
    ? wildlife.update(
        dt,
        time,
        subjectPos,
        camera,
        wildVel,
        controlMode === 'jet' ? 3.0 : controlMode === 'rover' ? 1.8 : 0.75,
        controlMode === 'rover' || controlMode === 'jet'
      )
    : { stalkerHit: 0, creatureKills: 0, shardsGained: 0 };
  if (wildlifeEvents.creatureKills > 0) {
    const g = prog.addShards(wildlifeEvents.shardsGained);
    for (let i = 0; i < wildlifeEvents.creatureKills; i++) prog.addKill(90);
    sound.playCollect();
    hud.showToast(`Wildlife Hunted (+${g} Shards)!`, 1.4);
  }

  const handleBoltHit = (hitPos: THREE.Vector3, prevPos: THREE.Vector3, dmg: number, _piercing: boolean): boolean => {
    let hitSomething = false;

    const wHit = wildlife.damageAtPoint(hitPos, 1.5, dmg, subjectPos, prevPos);
    if (wHit.hits > 0) hitSomething = true;
    if (wHit.kills > 0) {
      const g = prog.addShards(wHit.shards);
      for (let i = 0; i < wHit.kills; i++) prog.addKill(90);
      sound.playCollect();
      hud.showToast(`Creature Down (+${g} Shards)!`, 1.3);
    }

    const hitTree = physics.findHitTree(hitPos, 0.9, prevPos);
    if (hitTree) {
      hitSomething = true;
      if (props.damageTree(hitTree, dmg, hitPos.clone().sub(subjectPos))) {
        prog.addShards(5);
        prog.addKill(25);
        hud.showToast('Tree Felled (+5 Shards)!', 1.1);
      }
    }

    for (const cave of props.caves) {
      if (cave.completed) continue;
      for (const py of cave.pylons) {
        if (!py.ignited && hitPos.distanceTo(py.worldPos) < 2.8) {
          hitSomething = true;
          py.ignited = true;
          const mat = py.mesh.material as THREE.MeshStandardMaterial;
          mat.color.set('#5effd8');
          mat.emissive.set('#14ffb8');
          mat.emissiveIntensity = 2.8;
          sound.playCollect();
          hud.showToast(`Pylon Ignited! (${cave.name})`, 1.8);
        }
      }
    }

    for (const node of props.crystalNodes) {
      if (!node.destroyed && hitPos.distanceTo(node.pos) < 2.6) {
        hitSomething = true;
        node.hp -= dmg;
        if (node.hp <= 0) {
          node.destroyed = true;
          node.mesh.visible = false;
          const g = prog.addShards(25);
          sound.playCollect();
          hud.showToast(`Crystal Shattered (+${g} Shards)!`, 1.8);
        }
      }
    }
    for (const cr of offworld.crystals) {
      if (!cr.destroyed && hitPos.distanceTo(cr.pos) < 2.6) {
        hitSomething = true;
        cr.hp -= dmg;
        if (cr.hp <= 0) {
          cr.destroyed = true;
          cr.mesh.visible = false;
          const g = prog.addShards(35);
          sound.playCollect();
          hud.showToast(`Off-World Crystal (+${g} Shards)!`, 1.8);
        }
      }
    }

    for (const cit of offworld.citadels) {
      if (!cit.cleared) {
        const cUp = cit.center.clone().sub(cit.planet.center).normalize();
        const coreWorld = cit.center.clone().addScaledVector(cUp, 4.6);
        if (hitPos.distanceTo(coreWorld) < 3.6) {
          hitSomething = true;
          cit.hp -= dmg;
          if (cit.hp <= 0) {
            cit.cleared = true;
            cit.coreMesh.visible = false;
            cit.coreRing.visible = false;
            const g = prog.addShards(150);
            prog.addKill(800);
            sound.playExplosion();
            hud.showToast(`${cit.planet.name.toUpperCase()} CITADEL LIBERATED! (+${g} Shards)`, 4.2);
          }
        }
      }
    }

    return hitSomething;
  };

  const combatEvents = activeLoop
    ? combat.update(
        dt,
        time,
        camera,
        subjectPos,
        rover.position,
        rover.forwardSpeed,
        controlMode === 'rover',
        handleBoltHit,
        prog.iFrames || controlMode === 'jet'
      )
    : { playerHit: 0, enemyKilled: false, shardsCollected: 0, campCleared: null, waveBanner: null, explosion: false, killCount: 0, defeatedHiddenBossIds: [] };

  for (const bossId of combatEvents.defeatedHiddenBossIds) {
    const hb = missions.hiddenBosses.find((b) => b.id === bossId);
    if (hb && !hb.defeated) {
      hb.defeated = true;
      const g = prog.addShards(300);
      prog.addKill(2500);
      hud.showToast(`★ HIDDEN BOSS SLAIN: ${hb.name} (+${g} Shards)! ★`, 4.5);
    }
  }

  // Pyros Molten Lava Damage Hazard!
  let lavaDmg = 0;
  if (activeLoop && currentPlanet.id === 'pyros') {
    const pLoc = subjectPos.clone().sub(currentPlanet.center);
    const pDir = pLoc.clone().normalize();
    if (getPlanetTerrainHeight(pDir, 'pyros') < currentPlanet.seaLevel && pLoc.length() <= currentPlanet.seaLevel + 0.65) {
      if (controlMode === 'rover' || controlMode === 'foot') lavaDmg = 26 * dt;
    }
  }

  const totalHit = activeLoop ? (combatEvents.playerHit + wildlifeEvents.stalkerHit + lavaDmg) * (shieldActive || prog.iFrames ? 0 : 1) : 0;
  if (totalHit > 0) {
    hud.triggerDamageFlash();
    cameraShake = Math.max(cameraShake, 0.3);
    if (controlMode === 'rover') {
      rover.hp = Math.max(0, rover.hp - totalHit);
      if (rover.hp <= 0) {
        rover.respawn(currentPlanet);
        hud.showToast('Rover Hull Critical — Emergency Respawn!', 3.0);
      }
    } else if (controlMode === 'foot') {
      player.hp = Math.max(0, player.hp - totalHit);
      if (player.hp <= 0) {
        player.hp = player.maxHp;
        player.activePlanet = currentPlanet;
        const safeDir = player.position.clone().sub(currentPlanet.center).normalize();
        player.position.copy(getPlanetSurfacePosition(currentPlanet, safeDir, 2.5));
        player.velocity.set(0, 0, 0);
        hud.showToast(`Suit Critical — Emergency Med-Evac on ${currentPlanet.name}!`, 3.0);
      }
    }
  } else if (activeLoop) {
    const regen = shieldActive ? 16 : prog.getRegenRate();
    if (controlMode === 'rover') rover.hp = Math.min(rover.maxHp, rover.hp + regen * dt);
    else if (controlMode === 'foot') player.hp = Math.min(player.maxHp, player.hp + regen * dt);
    else jet.hp = Math.min(jet.maxHp, jet.hp + regen * dt);
  }

  if (combatEvents.shardsCollected > 0) {
    prog.addShards(combatEvents.shardsCollected);
    sound.playCollect();
  }
  if (combatEvents.killCount > 0) {
    prog.addShards(combatEvents.killCount * 16);
    for (let i = 0; i < combatEvents.killCount; i++) prog.addKill(150);
  }
  if (combatEvents.explosion) sound.playExplosion();
  if (combatEvents.waveBanner) hud.showToast(combatEvents.waveBanner, 3.2);
  if (combatEvents.campCleared) {
    const g = prog.addShards(75);
    prog.addKill(500);
    hud.showToast(`OUTPOST CONQUERED (+${g} Shards): ${combatEvents.campCleared}`, 3.5);
  }

  // Caves update
  for (const cave of props.caves) {
    if (cave.completed) continue;
    const distChamber = subjectPos.distanceTo(cave.chamberPos);
    if (!cave.waveTriggered && distChamber < 26) {
      cave.waveTriggered = true;
      hud.showToast(`${cave.name}: Guardian Wave Emerging!`, 3.0);
      for (let i = 0; i < 3; i++) combat.spawnEnemy('mech', cave.chamberPos, i * 2.1, 6.2);
    }

    let ignitedCount = 0;
    for (const py of cave.pylons) {
      if (!py.ignited && py.worldPos.distanceTo(subjectPos) < 4.5) {
        py.ignited = true;
        const mat = py.mesh.material as THREE.MeshStandardMaterial;
        mat.color.set('#5effd8');
        mat.emissive.set('#14ffb8');
        mat.emissiveIntensity = 2.8;
        sound.playCollect();
        hud.showToast(`Cavern Pylon Ignited! (${cave.name})`, 2.0);
      }
      if (py.ignited) ignitedCount++;
    }

    if (!cave.bossSpawned && ignitedCount >= 2) {
      cave.bossSpawned = true;
      hud.showToast(`${cave.name}: COLOSSUS OVERLORD AWAKENED!`, 3.2);
      combat.spawnEnemy('boss', cave.chamberPos, 0, 6.0);
    }

    if (ignitedCount === cave.pylons.length) {
      cave.completed = true;
      const g = prog.addShards(90);
      prog.addKill(650);
      sound.playCollect();
      hud.showToast(`CAVE CONQUERED (+${g} Shards): ${cave.name}!`, 4.0);
    }
  }

  const colStats = collectibles.update(time, subjectPos);
  if (colStats.newlyCollected) {
    sound.playCollect();
    const isCore = colStats.newlyCollected.kind === 'core';
    const g = prog.addShards(isCore ? 35 : 50);
    prog.addKill(120);
    hud.showToast(`Collected ${isCore ? 'Aether Core' : 'Ancient Relic'} (+${g} Shards)!`, 2.4);
  }

  const polarPos = getSurfacePosition(POLAR_SPIRE_DIR, 2);
  if (missions.stage === 4) {
    const alivePolar = polarWaveUnits.filter((u) => u.alive).length;
    if (missions.polarWave === 0 && subjectPos.distanceTo(polarPos) < 26) {
      missions.polarWave = 1;
      hud.showToast('POLAR SIEGE WAVE 1/3 — Defend the Citadel!', 3.2);
      for (let i = 0; i < 4; i++) polarWaveUnits.push(combat.spawnEnemy('scout', polarPos, i * 1.5, 11));
    } else if (missions.polarWave === 1 && alivePolar === 0) {
      missions.polarWave = 2;
      hud.showToast('POLAR SIEGE WAVE 2/3 — Berserkers & Mechs Inbound!', 3.2);
      for (let i = 0; i < 2; i++) polarWaveUnits.push(combat.spawnEnemy('mech', polarPos, i * 2.0, 12));
      polarWaveUnits.push(combat.spawnEnemy('berserker', polarPos, 4.0, 10));
    } else if (missions.polarWave === 2 && alivePolar === 0) {
      missions.polarWave = 3;
      hud.showToast('FINAL BOSS WAVE 3/3 — Syndicate Colossus!', 3.5);
      polarWaveUnits.push(combat.spawnEnemy('boss', polarPos, 0, 10));
      polarWaveUnits.push(combat.spawnEnemy('sniper', polarPos, 2.5, 13));
    } else if (missions.polarWave === 3 && alivePolar === 0) {
      missions.polarWave = 4;
    }
  }

  // Endless Wave Spawner (scoped per active planet so skipped caves/other planets never stall waves!)
  if (missions.endlessActive && activeLoop) {
    const aliveCount = combat.getAliveEnemyCount(currentPlanet.id);
    if (aliveCount <= 2) {
      endlessWaveTimer -= dt;
      if (endlessWaveTimer <= 0) {
        endlessWaveTimer = 5.0;
        const banner = missions.advanceEndlessWave();
        prog.endlessWave = missions.endlessWave;
        prog.endlessActive = true;
        const mix = missions.getEndlessEnemyMix();
        const spawnCenter = getPlanetSurfacePosition(currentPlanet, subjectPos.clone().sub(currentPlanet.center).normalize(), 0);
        combat.spawnEndlessWave(spawnCenter, mix, prog.getEnemyHpMult(), prog.getEnemyDamageMult(), prog.getEnemySpeedMult(), currentPlanet);
        hud.showToast(banner, 3.8);
      }
    }
  }

  const campsCleared = combat.camps.filter((c) => c.cleared).length;
  const cavesCleared = props.caves.filter((c) => c.completed).length;
  const chestsOpened = props.chests.filter((ch) => ch.opened).length + offworld.chests.filter((ch) => ch.opened).length;
  const offworldCleared = offworld.citadels.filter((c) => c.cleared).length;

  const { state: missionState, justAdvanced, spawnBoss } = missions.update(
    colStats.cores,
    chestsOpened,
    campsCleared,
    combat.camps.length,
    cavesCleared,
    props.caves.length,
    offworldCleared,
    offworld.citadels.length,
    prog.score
  );

  if (spawnBoss) {
    const bp = PLANETS.find((p) => p.id === spawnBoss.planetId) ?? currentPlanet;
    const randAng = Math.random() * Math.PI * 2;
    const randDir = new THREE.Vector3(Math.cos(randAng), 0.35 + Math.random() * 0.4, Math.sin(randAng)).normalize();
    const spawnPos = getPlanetSurfacePosition(bp, randDir, 0);
    combat.spawnHiddenBoss(spawnPos, prog.getEnemyHpMult(), prog.getEnemyDamageMult(), bp, spawnBoss.name, spawnBoss.id);
    hud.showToast(`⚠ HIDDEN BOSS AWAKENED ON ${bp.name.toUpperCase()}: ${spawnBoss.name}!`, 4.8);
  }

  if (justAdvanced) {
    sound.playCollect();
    hud.showToast(justAdvanced, 4.5);
  }
  if (missionState.spireActivated && !victoryShown) {
    victoryShown = true;
    document.exitPointerLock?.();
    hud.showVictory();
  }

  props.update(time, dt, missionState.spireActivated);
  sound.updateEngine(
    controlMode === 'jet' ? jet.speed : rover.forwardSpeed,
    controlMode !== 'foot',
    boostOrSprint && (controlMode === 'jet' || rover.boostEnergy > 1)
  );

  // World Markers & Planet Lock-on Beacons!
  const markers: WorldMarker[] = [];
  for (const hb of combat.getHiddenBossUnits()) {
    markers.push({
      id: hb.id,
      label: `☠ ${hb.customName ?? 'HIDDEN BOSS'}`,
      color: '#ff2477',
      worldPos: hb.position.clone().addScaledVector(hb.position.clone().sub(hb.planet.center).normalize(), 6),
      priority: true,
    });
  }
  if (controlMode === 'jet' || missionState.stage >= 3) {
    for (const pl of PLANETS) {
      if (pl.id !== currentPlanet.id || controlMode === 'jet') {
        markers.push({
          id: `planet-${pl.id}`,
          label: `★ ${pl.name}`,
          color: pl.accentColor,
          worldPos: pl.center.clone(),
          priority: true,
        });
      }
    }
  }
  if (currentPlanet.id === 'aetheria') {
    for (const camp of combat.camps) {
      if (!camp.cleared) {
        markers.push({
          id: camp.id,
          label: camp.name,
          color: '#ff5c72',
          worldPos: camp.center.clone().addScaledVector(camp.center.clone().normalize(), 5),
          priority: missionState.stage === 1,
        });
      }
    }
    for (const cave of props.caves) {
      if (!cave.completed) {
        markers.push({
          id: cave.id,
          label: `${cave.name} (Cave)`,
          color: '#b87dff',
          worldPos: cave.mouthPos.clone().addScaledVector(cave.mouthPos.clone().normalize(), 5),
          priority: missionState.stage === 0 || missionState.stage === 2,
        });
      }
    }
    for (const ch of props.chests) {
      if (!ch.opened) {
        markers.push({
          id: ch.id,
          label: 'Treasure Chest',
          color: '#ffd666',
          worldPos: ch.pos.clone().addScaledVector(ch.pos.clone().normalize(), 2.5),
        });
      }
    }
    for (const item of collectibles.items) {
      if (!item.collected && item.kind === 'core') {
        markers.push({
          id: item.id,
          label: 'Aether Core',
          color: '#63e8ff',
          worldPos: item.position.clone().addScaledVector(item.position.clone().normalize(), 3),
          priority: missionState.stage === 0 || missionState.stage === 2,
        });
      }
    }
  } else {
    const cit = offworld.citadels.find((c) => c.planet.id === currentPlanet.id && !c.cleared);
    if (cit) {
      markers.push({
        id: `cit-${cit.planet.id}`,
        label: `${cit.planet.name} Citadel`,
        color: cit.planet.accentColor,
        worldPos: cit.center.clone(),
        priority: true,
      });
    }
    for (const ch of offworld.chests) {
      if (!ch.opened && ch.planetId === currentPlanet.id) {
        markers.push({
          id: ch.id,
          label: 'Vault Chest',
          color: '#ffd666',
          worldPos: ch.pos.clone(),
          priority: true,
        });
      }
    }
  }

  if (missionState.stage >= 4 && !missionState.spireActivated) {
    markers.push({
      id: 'polar-spire',
      label: 'North Polar Citadel',
      color: '#ffe066',
      worldPos: polarPos.clone().addScaledVector(POLAR_SPIRE_DIR, 10),
      priority: true,
    });
  }
  if (controlMode !== 'jet' && jet.isNear(subjectPos, 85)) {
    markers.push({
      id: 'jet-pad',
      label: 'Air Force Jet [G]',
      color: '#5effea',
      worldPos: jet.position.clone().addScaledVector(jet.getUpVector(), 3),
    });
  }
  if (controlMode === 'foot') {
    markers.push({
      id: 'rover',
      label: 'Rover [F]',
      color: '#9bff8f',
      worldPos: rover.position.clone().addScaledVector(rover.getUpVector(), 1.4),
    });
  }

  const nearChest =
    props.chests.find((ch) => !ch.opened && ch.pos.distanceTo(subjectPos) < 6.0) ??
    offworld.chests.find((ch) => !ch.opened && ch.pos.distanceTo(subjectPos) < 6.5);

  const interactText = nearChest
    ? `Press [E] to Loot ${nearChest.label}`
    : controlMode !== 'jet' && jet.isNear(subjectPos, 8.5)
    ? 'Press [G] to Board Valkyrie Air Force Jet'
    : controlMode === 'foot' && rover.isNear(player.position, 6.5)
    ? 'Press [F] to Enter Rover'
    : null;

  const curLocal = subjectPos.clone().sub(currentPlanet.center);
  const curDir = curLocal.clone().normalize();
  const biome = inDeepSpace
    ? 'Deep Space Corridor'
    : getBiomeName(curDir, getPlanetTerrainHeight(curDir, currentPlanet.id), curLocal.length(), currentPlanet);

  const activeBoss = combat.getActiveBoss();
  const bossHud =
    activeBoss && activeBoss.position.distanceTo(subjectPos) < 110
      ? { name: activeBoss.customName ?? 'COLOSSUS OVERLORD', hp: activeBoss.hp, maxHp: activeBoss.maxHp }
      : null;

  hud.update(
    dt,
    missionState,
    controlMode === 'jet' ? jet.hp : controlMode === 'rover' ? rover.hp : player.hp,
    controlMode === 'jet' ? jet.maxHp : controlMode === 'rover' ? rover.maxHp : player.maxHp,
    controlMode === 'jet' ? (boostOrSprint ? 100 : 75) : controlMode === 'rover' ? rover.boostEnergy : player.jetpackFuel,
    controlMode === 'jet' ? jet.speed : controlMode === 'rover' ? rover.forwardSpeed : player.speed,
    controlMode,
    currentPlanet.name.toUpperCase(),
    biome,
    interactText,
    camera,
    subjectPos,
    up,
    markers,
    bossHud
  );

  postfx.render(camera, sunWorldPos);
}

animate();
