import * as THREE from 'three';
import {
  CAVE_BASES,
  PLANET_RADIUS,
  SEA_LEVEL,
  SPAWN_DIR,
  getSurfacePosition,
  getTerrainHeight,
} from '../math/spherical';

export interface CollectibleItem {
  id: string;
  kind: 'core' | 'relic';
  position: THREE.Vector3;
  collected: boolean;
  mesh: THREE.Group;
}

export class CollectiblesSystem {
  public readonly group = new THREE.Group();
  public readonly items: CollectibleItem[] = [];

  constructor() {
    this.spawnCollectibles();
  }

  private spawnCollectibles(): void {
    const upRef = new THREE.Vector3(0, 1, 0);

    // First Aether Core right along the scenic valley 20m in front of Spawn!
    const firstDir = SPAWN_DIR.clone().add(new THREE.Vector3(0.14, 0.04, -0.02)).normalize();
    this.addItem('core-0', 'core', firstDir, upRef);

    // 11 more Aether Cores across the planet
    const goldenAngle = Math.PI * (3 - Math.sqrt(5));
    let coreIdx = 1;
    for (let i = 0; i < 40 && coreIdx < 12; i++) {
      const y = 1 - ((i + 0.5) / 40) * 1.85;
      const r = Math.sqrt(Math.max(0, 1 - y * y));
      const theta = goldenAngle * i + 0.7;
      const dir = new THREE.Vector3(Math.cos(theta) * r, y, Math.sin(theta) * r).normalize();
      if (getTerrainHeight(dir) < SEA_LEVEL + 0.5) continue;
      if (dir.distanceTo(SPAWN_DIR) * PLANET_RADIUS < 18) continue;
      this.addItem(`core-${coreIdx}`, 'core', dir, upRef);
      coreIdx++;
    }

    // 3 Ancient Relics hidden DEEP INSIDE the 3 Underground Cave Chambers!
    CAVE_BASES.forEach((cb, i) => {
      const chamberZ = -cb.site.length + cb.site.chamberRadius * 0.45;
      const dir = cb.up
        .clone()
        .addScaledVector(cb.fwd, -(chamberZ - 5) / PLANET_RADIUS)
        .normalize();
      this.addItem(`relic-cave-${i}`, 'relic', dir, upRef);
    });

    // 3 Overworld Relics on dramatic mountain summits
    for (let i = 0; i < 3; i++) {
      const ang = (i / 3) * Math.PI * 2 + 0.6;
      const dir = new THREE.Vector3(Math.cos(ang) * 0.75, 0.52, Math.sin(ang) * 0.75).normalize();
      this.addItem(`relic-peak-${i}`, 'relic', dir, upRef);
    }
  }

  private addItem(id: string, kind: 'core' | 'relic', dir: THREE.Vector3, upRef: THREE.Vector3): void {
    const pos = getSurfacePosition(dir, 1.8);
    const holder = new THREE.Group();
    holder.position.copy(pos);
    holder.quaternion.setFromUnitVectors(upRef, dir);

    if (kind === 'core') {
      const crystal = new THREE.Mesh(
        new THREE.OctahedronGeometry(0.9, 0),
        new THREE.MeshStandardMaterial({
          color: '#6ff2ff',
          emissive: '#18c8ff',
          emissiveIntensity: 2.3,
          roughness: 0.15,
          metalness: 0.5,
        })
      );
      holder.add(crystal);

      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(1.3, 0.08, 8, 24),
        new THREE.MeshBasicMaterial({ color: '#a8f7ff' })
      );
      ring.rotation.x = Math.PI / 2;
      holder.add(ring);

      const beacon = new THREE.Mesh(
        new THREE.CylinderGeometry(0.12, 0.45, 22, 8, 1, true),
        new THREE.MeshBasicMaterial({
          color: '#3ce0ff',
          transparent: true,
          opacity: 0.24,
          side: THREE.DoubleSide,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
        })
      );
      beacon.position.y = 10;
      holder.add(beacon);
    } else {
      const relic = new THREE.Mesh(
        new THREE.DodecahedronGeometry(0.8, 0),
        new THREE.MeshStandardMaterial({
          color: '#ffd666',
          emissive: '#e0911b',
          emissiveIntensity: 2.0,
          roughness: 0.2,
          metalness: 0.75,
        })
      );
      holder.add(relic);
    }

    this.group.add(holder);
    this.items.push({ id, kind, position: pos, collected: false, mesh: holder });
  }

  public update(
    time: number,
    collectorPos: THREE.Vector3
  ): { cores: number; relics: number; newlyCollected: CollectibleItem | null } {
    let cores = 0;
    let relics = 0;
    let newlyCollected: CollectibleItem | null = null;

    for (const item of this.items) {
      if (item.collected) {
        if (item.kind === 'core') cores++;
        else relics++;
        continue;
      }

      item.mesh.children[0].rotation.y = time * 2.4;
      item.mesh.children[0].position.y = Math.sin(time * 3.0 + item.position.x) * 0.28;

      if (item.position.distanceTo(collectorPos) < 3.8) {
        item.collected = true;
        item.mesh.visible = false;
        newlyCollected = item;
        if (item.kind === 'core') cores++;
        else relics++;
      }
    }

    return { cores, relics, newlyCollected };
  }
}
