import * as THREE from 'three';
import {
  PLANET_RADIUS,
  SEA_LEVEL,
  evaluateCaveAtDir,
  getMoistureAtDir,
  getTerrainHeight,
  getTerrainNormal,
} from '../math/spherical';
import { getProceduralTextures } from '../rendering/textures';

export interface PlanetSystem {
  group: THREE.Group;
  terrainMesh: THREE.Mesh;
  oceanMesh: THREE.Mesh;
  atmosphereMesh: THREE.Mesh;
  sunDirUniform: { value: THREE.Vector3 };
  update(time: number, sunDir: THREE.Vector3): void;
}

export function createPlanet(sunDir: THREE.Vector3): PlanetSystem {
  const group = new THREE.Group();
  const tex = getProceduralTextures();

  // High-resolution icosahedral planet (~208k vertices) for crisp cliffs, caves & lakeshores
  const geo = new THREE.IcosahedronGeometry(1, 102);
  const posAttr = geo.attributes.position as THREE.BufferAttribute;
  const count = posAttr.count;

  const colors = new Float32Array(count * 3);
  const aoAttr = new Float32Array(count);
  const biomeAttr = new Float32Array(count * 4); // x=moisture, y=caveFactor, z=elevationRel, w=polar

  const dir = new THREE.Vector3();
  const normal = new THREE.Vector3();
  const color = new THREE.Color();

  const cSand = new THREE.Color('#cfa36b');
  const cGrass = new THREE.Color('#2f8c49');
  const cLush = new THREE.Color('#41ad5c');
  const cRock = new THREE.Color('#4a5363');
  const cCave = new THREE.Color('#262b38');
  const cSnow = new THREE.Color('#ecf4ff');

  for (let i = 0; i < count; i++) {
    dir.fromBufferAttribute(posAttr, i).normalize();
    const h = getTerrainHeight(dir);
    posAttr.setXYZ(i, dir.x * h, dir.y * h, dir.z * h);

    getTerrainNormal(dir, normal);
    const slope = 1 - Math.max(0, normal.dot(dir));
    const lat = Math.abs(dir.y);
    const moisture = getMoistureAtDir(dir);
    const caveInfo = evaluateCaveAtDir(dir);
    const inCave = caveInfo && caveInfo.localZ < -1.0 ? 1.0 : 0.0;

    if (inCave > 0.5) {
      color.copy(cCave);
    } else if (h < SEA_LEVEL + 0.8) {
      color.copy(cSand);
    } else if (lat > 0.78 || h > PLANET_RADIUS + 11.5) {
      color.copy(cSnow);
    } else if (moisture > 0.0) {
      color.copy(cGrass).lerp(cLush, Math.min(1, moisture * 2.5));
    } else {
      color.copy(cSand).lerp(cGrass, Math.max(0, (moisture + 0.25) * 4.0));
    }

    const rockMix = Math.min(1, Math.max(0, (slope - 0.14) * 4.2));
    color.lerp(cRock, rockMix);

    const heightRel = (h - (PLANET_RADIUS - 6)) / 20;
    const bakedAO = inCave > 0.5
      ? 0.35
      : Math.max(0.42, Math.min(1.0, 0.62 + heightRel * 0.42 - slope * 0.32));
    aoAttr[i] = bakedAO;

    biomeAttr[i * 4] = moisture * 0.5 + 0.5;
    biomeAttr[i * 4 + 1] = inCave;
    biomeAttr[i * 4 + 2] = h - SEA_LEVEL;
    biomeAttr[i * 4 + 3] = lat;

    colors[i * 3] = color.r;
    colors[i * 3 + 1] = color.g;
    colors[i * 3 + 2] = color.b;
  }

  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.setAttribute('aBakedAO', new THREE.BufferAttribute(aoAttr, 1));
  geo.setAttribute('aBiome', new THREE.BufferAttribute(biomeAttr, 4));
  geo.computeVertexNormals();

  const sunDirUniform = { value: sunDir.clone().normalize() };
  const timeUniform = { value: 0 };

  const terrainMat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.78,
    metalness: 0.04,
  });

  terrainMat.onBeforeCompile = (shader) => {
    shader.uniforms.uSunDir = sunDirUniform;
    shader.uniforms.uGrassTex = { value: tex.grassAlbedo };
    shader.uniforms.uRockTex = { value: tex.rockAlbedo };
    shader.uniforms.uSandTex = { value: tex.sandAlbedo };
    shader.uniforms.uGrassNorm = { value: tex.grassNormal };
    shader.uniforms.uRockNorm = { value: tex.rockNormal };

    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>
        attribute float aBakedAO;
        attribute vec4 aBiome;
        varying float vBakedAO;
        varying vec4 vBiome;
        varying vec3 vWorldPos;
        varying vec3 vSphereUp;
        varying vec3 vWorldNorm;`
      )
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        vBakedAO = aBakedAO;
        vBiome = aBiome;
        vWorldPos = (modelMatrix * vec4(transformed, 1.0)).xyz;
        vSphereUp = normalize(vWorldPos);
        vWorldNorm = normalize(mat3(modelMatrix) * objectNormal);`
      );

    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
        varying float vBakedAO;
        varying vec4 vBiome;
        varying vec3 vWorldPos;
        varying vec3 vSphereUp;
        varying vec3 vWorldNorm;
        uniform vec3 uSunDir;
        uniform sampler2D uGrassTex;
        uniform sampler2D uRockTex;
        uniform sampler2D uSandTex;
        uniform sampler2D uGrassNorm;
        uniform sampler2D uRockNorm;

        vec3 triSample(sampler2D t, vec3 p, vec3 bw, float scale) {
          return texture2D(t, p.xy * scale).rgb * bw.z
               + texture2D(t, p.yz * scale).rgb * bw.x
               + texture2D(t, p.xz * scale).rgb * bw.y;
        }`
      )
      .replace(
        '#include <color_fragment>',
        `#include <color_fragment>
        vec3 bw = abs(vSphereUp);
        bw = bw / (bw.x + bw.y + bw.z + 0.0001);
        float slope = 1.0 - max(0.0, dot(normalize(vWorldNorm), vSphereUp));
        float rockMask = smoothstep(0.14, 0.34, slope);
        float shoreMask = 1.0 - smoothstep(0.0, 1.1, vBiome.z);
        float caveMask = vBiome.y;

        vec3 gTex = triSample(uGrassTex, vWorldPos, bw, 0.085);
        vec3 rTex = triSample(uRockTex, vWorldPos, bw, 0.075);
        vec3 sTex = triSample(uSandTex, vWorldPos, bw, 0.095);

        vec3 groundTex = mix(sTex, gTex, smoothstep(0.28, 0.56, vBiome.x));
        groundTex = mix(groundTex, sTex, shoreMask * 0.85);
        groundTex = mix(groundTex, rTex, max(rockMask, caveMask));

        // Wet shoreline darkening
        float wet = 1.0 - smoothstep(-0.2, 0.45, vBiome.z);
        diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * 0.55 + groundTex * 0.45, 0.72);
        diffuseColor.rgb *= (1.0 - wet * 0.25);`
      )
      .replace(
        '#include <normal_fragment_maps>',
        `#include <normal_fragment_maps>
        vec3 bwN = abs(vSphereUp);
        bwN = bwN / (bwN.x + bwN.y + bwN.z + 0.0001);
        float slopeN = 1.0 - max(0.0, dot(normalize(vWorldNorm), vSphereUp));
        vec3 nG = triSample(uGrassNorm, vWorldPos, bwN, 0.085) * 2.0 - 1.0;
        vec3 nR = triSample(uRockNorm, vWorldPos, bwN, 0.075) * 2.0 - 1.0;
        vec3 nMix = mix(nG, nR, max(smoothstep(0.14, 0.34, slopeN), vBiome.y));
        vec3 viewPerturb = (viewMatrix * vec4(nMix.x * 0.25, nMix.y * 0.25, nMix.z * 0.15, 0.0)).xyz;
        normal = normalize(normal + viewPerturb);`
      )
      .replace(
        '#include <aomap_fragment>',
        `#include <aomap_fragment>
        reflectedLight.indirectDiffuse *= vBakedAO;
        reflectedLight.indirectSpecular *= vBakedAO;`
      )
      .replace(
        '#include <fog_fragment>',
        `#include <fog_fragment>
        float distCam = length(cameraPosition - vWorldPos);
        float aerial = 1.0 - exp(-max(0.0, distCam - 38.0) * 0.0024);
        float sunWrap = smoothstep(-0.25, 0.85, dot(vSphereUp, uSunDir));
        vec3 scatterCol = mix(vec3(0.24, 0.14, 0.16), vec3(0.32, 0.62, 0.94), sunWrap);
        gl_FragColor.rgb = mix(gl_FragColor.rgb, scatterCol, clamp(aerial * 0.48 * (1.0 - vBiome.y), 0.0, 0.48));`
      );
  };

  const terrainMesh = new THREE.Mesh(geo, terrainMat);
  terrainMesh.receiveShadow = true;
  terrainMesh.castShadow = true;
  group.add(terrainMesh);

  // Shimmering Crystal Lakes & Coastal Water with Animated Waves
  const oceanGeo = new THREE.IcosahedronGeometry(SEA_LEVEL, 56);
  const oceanMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#0c6899'),
    emissive: new THREE.Color('#042840'),
    roughness: 0.1,
    metalness: 0.45,
    transparent: true,
    opacity: 0.85,
  });
  oceanMat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = timeUniform;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>\nvarying vec3 vOceanPos;`)
      .replace('#include <begin_vertex>', `#include <begin_vertex>\nvOceanPos = (modelMatrix * vec4(transformed, 1.0)).xyz;`);
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
        uniform float uTime;
        varying vec3 vOceanPos;`
      )
      .replace(
        '#include <normal_fragment_maps>',
        `#include <normal_fragment_maps>
        float w1 = sin(vOceanPos.x * 1.1 + uTime * 1.6) * cos(vOceanPos.z * 1.1 - uTime * 1.2);
        float w2 = sin(vOceanPos.y * 1.8 - uTime * 1.9) * cos(vOceanPos.x * 1.5 + uTime * 1.1);
        vec3 wavePerturb = (viewMatrix * vec4(w1 * 0.11, w2 * 0.11, (w1 - w2) * 0.08, 0.0)).xyz;
        normal = normalize(normal + wavePerturb);`
      );
  };
  const oceanMesh = new THREE.Mesh(oceanGeo, oceanMat);
  oceanMesh.receiveShadow = true;
  group.add(oceanMesh);

  // Limb-Accurate Atmospheric Scattering Halo
  const atmosGeo = new THREE.IcosahedronGeometry(PLANET_RADIUS + 26, 40);
  const atmosMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: {
      uSunDir: sunDirUniform,
      uPlanetR: { value: PLANET_RADIUS },
      uAtmosR: { value: PLANET_RADIUS + 26 },
    },
    vertexShader: `
      varying vec3 vWorldPos;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorldPos = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      varying vec3 vWorldPos;
      uniform vec3 uSunDir;
      uniform float uPlanetR;
      uniform float uAtmosR;
      void main() {
        vec3 rayDir = normalize(vWorldPos - cameraPosition);
        float tClosest = -dot(cameraPosition, rayDir);
        vec3 closestPt = cameraPosition + rayDir * max(0.0, tClosest);
        float b = length(closestPt);
        float limb = 1.0 - clamp((b - uPlanetR) / (uAtmosR - uPlanetR), 0.0, 1.0);
        float halo = pow(limb, 2.2);
        float sunWrap = smoothstep(-0.3, 0.85, dot(normalize(vWorldPos), uSunDir));
        vec3 dayColor = vec3(0.28, 0.72, 1.0);
        vec3 twilightColor = vec3(1.0, 0.48, 0.24);
        vec3 col = mix(twilightColor, dayColor, sunWrap);
        float alpha = halo * (0.2 + 0.62 * sunWrap);
        gl_FragColor = vec4(col, alpha);
      }
    `,
  });
  const atmosphereMesh = new THREE.Mesh(atmosGeo, atmosMat);
  group.add(atmosphereMesh);

  return {
    group,
    terrainMesh,
    oceanMesh,
    atmosphereMesh,
    sunDirUniform,
    update(time: number, curSunDir: THREE.Vector3) {
      sunDirUniform.value.copy(curSunDir).normalize();
      timeUniform.value = time;
    },
  };
}
