export interface PropsSystem {
  group: THREE.Group;
  caves: CaveInstance[];
  chests: TreasureChest[];
  crystalNodes: CrystalNode[];
  boostPads: BoostPad[];
  trialRings: TrialRing[];
  trialActive: boolean;
  trialTimer: number;
  polarBeaconRing: THREE.Mesh;
  polarBeaconCore: THREE.Mesh;
  airPadPos: THREE.Vector3;
  knockDownTree(col: StaticCollider, impactDir: THREE.Vector3, impactSpeed?: number): boolean;
  damageTree(col: StaticCollider, damage: number, impactDir: THREE.Vector3): boolean;
  update(time: number, dt: number, spireActivated: boolean): void;
}

function isNearProtectedZone(dir: THREE.Vector3): boolean {
  if (dir.distanceTo(SPAWN_DIR) * PLANET_RADIUS < 16) return true;
  if (dir.distanceTo(POLAR_SPIRE_DIR) * PLANET_RADIUS < 15) return true;
  for (const camp of CAMP_SITES) {
    if (dir.distanceTo(camp.dir) * PLANET_RADIUS < camp.plateauRadius + 3) return true;
  }
  const cInfo = evaluateCaveAtDir(dir);
  if (cInfo) return true;
  return false;
}

function caveLocalToWorld(cb: CaveBasis, lx: number, yOff: number, lz: number): THREE.Vector3 {
  const arcDist = Math.hypot(lx, lz);
  const dir = cb.up.clone();
  if (arcDist > 0.0001) {
    const theta = arcDist / PLANET_RADIUS;
    const tang = new THREE.Vector3()
      .addScaledVector(cb.right, lx / arcDist)
      .addScaledVector(cb.fwd, -lz / arcDist);
    dir.multiplyScalar(Math.cos(theta)).addScaledVector(tang, Math.sin(theta)).normalize();
  }
  const floorH = getTerrainHeight(dir);
  return dir.multiplyScalar(floorH + yOff);
}

function setUpwardNormals(geo: THREE.BufferGeometry): THREE.BufferGeometry {
  const norm = geo.attributes.normal as THREE.BufferAttribute;
  for (let i = 0; i < norm.count; i++) {
    norm.setXYZ(i, 0, 1, 0);
  }
  return geo;
}

function createCrossedGrassGeometry(width = 1.6, height = 1.35): THREE.BufferGeometry {
  const p1 = new THREE.PlaneGeometry(width, height);
  p1.translate(0, height * 0.45, 0);
  const p2 = p1.clone().rotateY(Math.PI / 3);
  const p3 = p1.clone().rotateY((2 * Math.PI) / 3);
  return setUpwardNormals(mergeGeometries([p1, p2, p3])!);
}

function createCanopyCardsGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const offsets: [number, number, number, number, number, number][] = [
    [0, 4.4, 0, 0.28, 0, 3.8],
    [0, 4.7, 0, -0.28, Math.PI / 2, 3.6],
    [0.85, 3.9, 0.5, 0.35, 0.6, 3.0],
    [-0.85, 4.1, -0.45, -0.35, -0.7, 3.0],
    [0, 5.2, 0, Math.PI / 2 - 0.14, 0.4, 3.9],
  ];
  for (const [x, y, z, rx, ry, s] of offsets) {
    const p = new THREE.PlaneGeometry(s, s);
    p.rotateX(rx);
    p.rotateY(ry);
    p.translate(x, y, z);
    parts.push(p);
  }
  const merged = mergeGeometries(parts)!;
  const pos = merged.attributes.position as THREE.BufferAttribute;
  const norm = merged.attributes.normal as THREE.BufferAttribute;
  const v = new THREE.Vector3();
  const center = new THREE.Vector3(0, 4.3, 0);
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i).sub(center).normalize();
    norm.setXYZ(i, v.x * 0.6, Math.max(0.35, v.y), v.z * 0.6);
  }
  return merged;
}

function createBranchingTrunkGeometry(): THREE.BufferGeometry {
  const main = new THREE.CylinderGeometry(0.18, 0.44, 5.0, 8);
  main.translate(0, 1.6, 0);
  const b1 = new THREE.CylinderGeometry(0.08, 0.18, 2.0, 6);
  b1.rotateZ(-0.65);
  b1.translate(0.52, 3.25, 0.12);
  const b2 = new THREE.CylinderGeometry(0.08, 0.16, 1.8, 6);
  b2.rotateZ(0.62);
  b2.rotateY(1.2);
  b2.translate(-0.32, 3.35, -0.18);
  return mergeGeometries([main, b1, b2])!;
}

export function createWorldProps(physics: PhysicsWorld): PropsSystem {
  const group = new THREE.Group();
  const tex = getProceduralTextures();
  const upRef = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3();
  const normal = new THREE.Vector3();
  const dummy = new THREE.Object3D();
  const tint = new THREE.Color();
  const windUniform = { value: 0 };

  let seed = 424242;
  const rand = () => {
    seed = (seed * 1664525 + 1013904223) >>> 0;
    return seed / 4294967295;
  };

  // 1. Destructible Organic Branching Trees (850 trees!)
  const maxTrees = 850;
  const trunkGeo = createBranchingTrunkGeometry();
  const trunkMat = new THREE.MeshStandardMaterial({
    map: tex.barkAlbedo,
    normalMap: tex.barkNormal,
    roughness: 0.92,
  });
  const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, maxTrees);
  trunks.castShadow = true;
  trunks.receiveShadow = true;

  const canopyGeo = createCanopyCardsGeometry();
  const canopyMat = new THREE.MeshStandardMaterial({
    map: tex.leafCard,
    alphaTest: 0.35,
    side: THREE.DoubleSide,
    roughness: 0.78,
  });
  canopyMat.onBeforeCompile = (shader) => {
    shader.uniforms.uWind = windUniform;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>\nuniform float uWind;`)
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        #ifdef USE_INSTANCING
          vec3 instP = (instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0)).xyz;
        #else
          vec3 instP = (modelMatrix * vec4(0.0, 0.0, 0.0, 1.0)).xyz;
        #endif
        float sway = sin(uWind * 1.8 + instP.x * 0.25 + instP.z * 0.25) * 0.16;
        transformed.x += sway * clamp((position.y - 2.5) / 3.0, 0.0, 1.0);`
      );
  };
  const dynCanopyMat = new THREE.MeshStandardMaterial({
    map: tex.leafCard,
    alphaTest: 0.35,
    side: THREE.DoubleSide,
    roughness: 0.78,
  });
  const canopies = new THREE.InstancedMesh(canopyGeo, canopyMat, maxTrees);
  canopies.castShadow = true;
  canopies.receiveShadow = true;

  const treeMetas: TreeMeta[] = [];
  const fallingTrees: FallingTree[] = [];
  const splinters: WoodSplinter[] = [];
  const splinterGeo = new THREE.BoxGeometry(0.18, 0.65, 0.18);
  const splinterMat = new THREE.MeshStandardMaterial({ color: '#6b472a', roughness: 0.9 });
  const leafChunkMat = new THREE.MeshStandardMaterial({ color: '#469e52', roughness: 0.8 });
  const stumpGeo = new THREE.CylinderGeometry(0.28, 0.44, 0.6, 7);

  let treeIdx = 0;
  for (let i = 0; i < 4200 && treeIdx < maxTrees; i++) {
    if (i < 110) {
      const ang = rand() * Math.PI * 2;
      const dist = 16 + rand() * 38;
      dir.copy(SPAWN_DIR).add(new THREE.Vector3(Math.cos(ang) * dist / PLANET_RADIUS, Math.sin(ang) * dist / PLANET_RADIUS, 0)).normalize();
    } else {
      const u = rand();
      const v = rand();
      const theta = 2 * Math.PI * u;
      const phi = Math.acos(2 * v - 1);
      dir.set(Math.sin(phi) * Math.cos(theta), Math.cos(phi), Math.sin(phi) * Math.sin(theta));
    }

    if (dir.z > 0.88 && dir.x > -0.22 && dir.x < 0.28 && dir.y > 0.17 && dir.y < 0.34) continue;
    if (Math.abs(dir.y) > 0.76 || isNearProtectedZone(dir)) continue;
    const h = getTerrainHeight(dir);
    if (h < SEA_LEVEL + 0.6 || h > PLANET_RADIUS + 10.5) continue;
    getTerrainNormal(dir, normal);
    if (normal.dot(dir) < 0.85) continue;

    const moisture = getMoistureAtDir(dir);
    if (i >= 110 && moisture < -0.05) continue;

    const pos = dir.clone().multiplyScalar(h - 0.3);
    const rotY = rand() * Math.PI * 2;
    const s = 0.85 + rand() * 0.9;
    const sy = s * (0.9 + rand() * 0.35);

    dummy.position.copy(pos);
    dummy.quaternion.setFromUnitVectors(upRef, dir);
    dummy.rotateY(rotY);
    dummy.scale.set(s, sy, s);
    dummy.updateMatrix();
    trunks.setMatrixAt(treeIdx, dummy.matrix);
    canopies.setMatrixAt(treeIdx, dummy.matrix);

    tint.setHSL(0.32 + (rand() - 0.5) * 0.07, 0.25 + rand() * 0.2, 0.58 + rand() * 0.16);
    canopies.setColorAt(treeIdx, tint);
    const col = physics.addCollider(pos, 0.52 * s, 'tree', 5.0 * s, treeIdx, s);
    treeMetas.push({
      pos: pos.clone(),
      dir: dir.clone(),
      scale: s,
      scaleY: sy,
      rotY,
      hp: 40,
      felled: false,
      collider: col,
    });
    treeIdx++;
  }
  trunks.count = treeIdx;
  canopies.count = treeIdx;
  if (canopies.instanceColor) canopies.instanceColor.needsUpdate = true;
  group.add(trunks, canopies);

  const knockDownTree = (col: StaticCollider, impactDir: THREE.Vector3, impactSpeed = 12): boolean => {
    if (col.metaIdx === undefined) return false;
    const meta = treeMetas[col.metaIdx];
    if (!meta || meta.felled) return false;
    meta.felled = true;
    col.broken = true;

    // Hide static instanced trunk & canopy
    dummy.scale.set(0, 0, 0);
    dummy.updateMatrix();
    trunks.setMatrixAt(col.metaIdx, dummy.matrix);
    canopies.setMatrixAt(col.metaIdx, dummy.matrix);
    trunks.instanceMatrix.needsUpdate = true;
    canopies.instanceMatrix.needsUpdate = true;

    // Leave jagged broken tree stump!
    const stump = new THREE.Mesh(stumpGeo, trunkMat);
    stump.position.copy(meta.pos).addScaledVector(meta.dir, 0.3);
    stump.quaternion.setFromUnitVectors(upRef, meta.dir);
    stump.rotateY(meta.rotY);
    stump.scale.set(meta.scale, meta.scale, meta.scale);
    stump.castShadow = true;
    group.add(stump);

    // Build dynamic physical falling tree mesh (dedicated non-instanced canopy mat -> guaranteed visible!)
    const dynTree = new THREE.Group();
    const dynTrunk = new THREE.Mesh(trunkGeo, trunkMat);
    dynTrunk.castShadow = true;
    dynTree.add(dynTrunk);
    const dynCanopy = new THREE.Mesh(canopyGeo, dynCanopyMat);
    dynCanopy.castShadow = true;
    dynTree.add(dynCanopy);

    const treePos = meta.pos.clone().addScaledVector(meta.dir, 0.55);
    dynTree.position.copy(treePos);
    dynTree.quaternion.setFromUnitVectors(upRef, meta.dir);
    dynTree.rotateY(meta.rotY);
    dynTree.scale.set(meta.scale, meta.scaleY, meta.scale);
    group.add(dynTree);

    // Safe perpendicular axis even if meta.dir == (1,0,0)
    const tangImpact = impactDir.clone().addScaledVector(meta.dir, -impactDir.dot(meta.dir));
    if (tangImpact.lengthSq() < 0.001) {
      const ref = Math.abs(meta.dir.x) < 0.85 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
      tangImpact.crossVectors(ref, meta.dir);
    }
    tangImpact.normalize();
    const fallAxis = new THREE.Vector3().crossVectors(meta.dir, tangImpact).normalize();

    const launchVel = tangImpact.clone().multiplyScalar(Math.min(18, impactSpeed * 0.45)).addScaledVector(meta.dir, 4.5);

    fallingTrees.push({
      mesh: dynTree,
      pos: treePos,
      vel: launchVel,
      fallAxis,
      fallAngle: 0.05,
      angVel: 2.2 + Math.min(2.8, impactSpeed * 0.1),
      up: meta.dir.clone(),
      rotY: meta.rotY,
      scale: meta.scale,
      scaleY: meta.scaleY,
      life: 6.0,
      settled: false,
    });

    // Flying wood splinters & leaves
    for (let s = 0; s < 10; s++) {
      const sp = new THREE.Mesh(splinterGeo, s % 2 === 0 ? splinterMat : leafChunkMat);
      sp.position.copy(meta.pos).addScaledVector(meta.dir, 2.2);
      group.add(sp);
      const sv = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5)
        .normalize()
        .multiplyScalar(7 + Math.random() * 10)
        .addScaledVector(meta.dir, 7)
        .addScaledVector(tangImpact, 4);
      splinters.push({ mesh: sp, vel: sv, life: 1.2 + Math.random() * 0.6 });
    }

    return true;
  };

  const damageTree = (col: StaticCollider, damage: number, impactDir: THREE.Vector3): boolean => {
    if (col.metaIdx === undefined) return false;
    const meta = treeMetas[col.metaIdx];
    if (!meta || meta.felled) return false;
    meta.hp -= damage;
    if (meta.hp <= 0) {
      return knockDownTree(col, impactDir, 10);
    }
    return false;
  };

  // 2. Wind-Swaying Crossed Grass Blade Tufts
  const maxGrass = 2800;
  const grassGeo = createCrossedGrassGeometry(1.75, 1.35);
  const grassMat = new THREE.MeshStandardMaterial({
    map: tex.grassCard,
    alphaTest: 0.38,
    side: THREE.DoubleSide,
    roughness: 0.82,
  });
  grassMat.onBeforeCompile = (shader) => {
    shader.uniforms.uWind = windUniform;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>\nuniform float uWind;`)
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        vec3 instG = (instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0)).xyz;
        float tip = clamp(position.y / 1.35, 0.0, 1.0);
        transformed.x += sin(uWind * 2.5 + instG.x * 0.35 + instG.z * 0.35) * 0.16 * tip;`
      );
  };
  const grass = new THREE.InstancedMesh(grassGeo, grassMat, maxGrass);
  let grassIdx = 0;
  for (let i = 0; i < 6200 && grassIdx < maxGrass; i++) {
    if (i < 450) {
      const ang = rand() * Math.PI * 2;
      const dist = 5 + rand() * 45;
      dir.copy(SPAWN_DIR).add(new THREE.Vector3(Math.cos(ang) * dist / PLANET_RADIUS, Math.sin(ang) * dist / PLANET_RADIUS, 0)).normalize();
    } else {
      const u = rand();
      const v = rand();
      const theta = 2 * Math.PI * u;
      const phi = Math.acos(2 * v - 1);
      dir.set(Math.sin(phi) * Math.cos(theta), Math.cos(phi), Math.sin(phi) * Math.sin(theta));
    }
    if (Math.abs(dir.y) > 0.78 || isNearProtectedZone(dir)) continue;
    const h = getTerrainHeight(dir);
    if (h < SEA_LEVEL + 0.3 || h > PLANET_RADIUS + 9.5) continue;
    getTerrainNormal(dir, normal);
    if (normal.dot(dir) < 0.82) continue;

    dummy.position.copy(dir).multiplyScalar(h - 0.08);
    dummy.quaternion.setFromUnitVectors(upRef, dir);
    dummy.rotateY(rand() * Math.PI * 2);
    const s = 0.7 + rand() * 0.75;
    dummy.scale.set(s, s * (0.7 + rand() * 0.5), s);
    dummy.updateMatrix();
    grass.setMatrixAt(grassIdx, dummy.matrix);
    tint.setHSL(0.32 + (rand() - 0.5) * 0.06, 0.25, 0.58 + rand() * 0.16);
    grass.setColorAt(grassIdx, tint);
    grassIdx++;
  }
  grass.count = grassIdx;
  if (grass.instanceColor) grass.instanceColor.needsUpdate = true;
  group.add(grass);

  // 3. Sculpted Craggy Boulders (skip overly steep slopes so cars climb hills smoothly!)
  const maxRocks = 360;
  const rockGeo = new THREE.IcosahedronGeometry(1.0, 2);
  const rPos = rockGeo.attributes.position as THREE.BufferAttribute;
  for (let i = 0; i < rPos.count; i++) {
    const vx = rPos.getX(i);
    const vy = rPos.getY(i);
    const vz = rPos.getZ(i);
    const n = 1 + Math.sin(vx * 3.1) * Math.cos(vy * 3.7) * 0.18;
    rPos.setXYZ(i, vx * n, vy * n * 0.78, vz * n);
  }
  rockGeo.computeVertexNormals();
  const rockMat = new THREE.MeshStandardMaterial({
    color: '#ffffff',
    map: tex.rockAlbedo,
    normalMap: tex.rockNormal,
    roughness: 0.86,
  });
  const rocks = new THREE.InstancedMesh(rockGeo, rockMat, maxRocks);
  rocks.castShadow = true;
  rocks.receiveShadow = true;

  let rockIdx = 0;
  for (let i = 0; i < 1800 && rockIdx < maxRocks; i++) {
    const u = rand();
    const v = rand();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);
    dir.set(Math.sin(phi) * Math.cos(theta), Math.cos(phi), Math.sin(phi) * Math.sin(theta));
    if (dir.z > 0.88 && dir.x > -0.22 && dir.x < 0.28 && dir.y > 0.17 && dir.y < 0.34) continue;
    if (isNearProtectedZone(dir)) continue;
    const h = getTerrainHeight(dir);
    if (h < SEA_LEVEL + 0.4) continue;
    getTerrainNormal(dir, normal);
    if (normal.dot(dir) < 0.84) continue;

    const pos = dir.clone().multiplyScalar(h - 0.35);
    dummy.position.copy(pos);
    dummy.quaternion.setFromUnitVectors(upRef, dir);
    dummy.rotateY(rand() * Math.PI * 2);
    const s = 0.7 + rand() * 1.4;
    dummy.scale.set(s * 1.15, s * 0.8, s);
    dummy.updateMatrix();
    rocks.setMatrixAt(rockIdx, dummy.matrix);
    const gVal = 0.65 + rand() * 0.28;
    tint.setRGB(gVal, gVal * 1.02, gVal * 1.06);
    rocks.setColorAt(rockIdx, tint);
    physics.addCollider(pos, 1.3 * s, 'rock', 1.7 * s);
    rockIdx++;
  }
  rocks.count = rockIdx;
  if (rocks.instanceColor) rocks.instanceColor.needsUpdate = true;
  group.add(rocks);

  // 4. Interactive Destructible Aether Crystal Nodes (24 Clusters)
  const crystalNodes: CrystalNode[] = [];
  const nodeMat = new THREE.MeshPhysicalMaterial({
    color: '#52ebff',
    emissive: '#0c8ec8',
    emissiveIntensity: 1.5,
    roughness: 0.12,
    metalness: 0.35,
    clearcoat: 1.0,
  });
  for (let i = 0; i < 24; i++) {
    const ang = (i / 24) * Math.PI * 2 + 0.25;
    const lat = ((i % 4) - 1.5) * 0.25;
    const cDir = i < 3
      ? SPAWN_DIR.clone().add(new THREE.Vector3((i - 1) * 0.12, 0.08, -0.05)).normalize()
      : new THREE.Vector3(Math.cos(ang) * Math.cos(lat), Math.sin(lat), Math.sin(ang) * Math.cos(lat)).normalize();
    if (i >= 3 && (isNearProtectedZone(cDir) || getTerrainHeight(cDir) < SEA_LEVEL + 0.8)) continue;
    const pos = getSurfacePosition(cDir, 0);
    const mesh = new THREE.Mesh(new THREE.OctahedronGeometry(1.1, 0), nodeMat);
    mesh.scale.set(0.75, 2.2, 0.75);
    mesh.position.copy(pos).addScaledVector(cDir, 1.2);
    mesh.quaternion.setFromUnitVectors(upRef, cDir);
    mesh.castShadow = true;
    group.add(mesh);
    crystalNodes.push({ pos, mesh, hp: 45, destroyed: false });
  }

  // 5. MASSIVE 92m EXPLORABLE MULTI-ROOM UNDERGROUND CAVES
  const caves: CaveInstance[] = [];
  const caveWallMat = new THREE.MeshStandardMaterial({
    color: '#7a8ba6',
    emissive: '#101826',
    emissiveIntensity: 0.45,
    map: tex.rockAlbedo,
    normalMap: tex.rockNormal,
    roughness: 0.82,
    metalness: 0.1,
  });

  const chests: TreasureChest[] = [];
  const chestConfigs: { pos: THREE.Vector3; up: THREE.Vector3; rewardWeapon?: WeaponId; shards: number; label: string }[] = [];

  for (let cIdx = 0; cIdx < CAVE_BASES.length; cIdx++) {
    const cb = CAVE_BASES[cIdx];
    const site = CAVE_SITES[cIdx];
    const caveGroup = new THREE.Group();

    const mouthPos = caveLocalToWorld(cb, 0, 0, 0);
    const chamberZ = -site.length + site.chamberRadius * 0.45;
    const chamberPos = caveLocalToWorld(cb, 0, 0, chamberZ);

    for (let step = 0; step <= 21; step++) {
      const lz = -step * 3.6;
      const inAlcove = lz <= -38 && lz >= -52;
      const leftWallX = -11.5;
      const rightWallX = inAlcove ? 21.0 : 11.5;

      for (const wx of [leftWallX, rightWallX]) {
        for (const wy of [4.2, 9.8]) {
          const wallPos = caveLocalToWorld(cb, wx, wy, lz);
          const wallRock = new THREE.Mesh(rockGeo, caveWallMat);
          wallRock.position.copy(wallPos);
          wallRock.quaternion.setFromUnitVectors(upRef, wallPos.clone().normalize());
          wallRock.scale.set(4.6, 5.8, 4.8);
          wallRock.castShadow = true;
          wallRock.receiveShadow = true;
          caveGroup.add(wallRock);
        }
      }

      const roofSpan = inAlcove ? [-10, -4, 2, 8, 14, 19] : [-10, -5, 0, 5, 10];
      for (const ax of roofSpan) {
        const ay = 14.0 - Math.abs(ax) * 0.18;
        const roofPos = caveLocalToWorld(cb, ax, ay, lz);
        const roofRock = new THREE.Mesh(rockGeo, caveWallMat);
        roofRock.position.copy(roofPos);
        roofRock.quaternion.setFromUnitVectors(upRef, roofPos.clone().normalize());
        roofRock.scale.set(5.4, 3.2, 4.8);
        roofRock.castShadow = true;
        roofRock.receiveShadow = true;
        caveGroup.add(roofRock);
      }
    }

    for (const endZ of [-36, -54]) {
      for (const endX of [13.5, 18.0]) {
        for (const wy of [4.2, 9.8]) {
          const ePos = caveLocalToWorld(cb, endX, wy, endZ);
          const eRock = new THREE.Mesh(rockGeo, caveWallMat);
          eRock.position.copy(ePos);
          eRock.quaternion.setFromUnitVectors(upRef, ePos.clone().normalize());
          eRock.scale.set(4.2, 5.6, 4.0);
          eRock.castShadow = true;
          eRock.receiveShadow = true;
          caveGroup.add(eRock);
        }
      }
    }

    for (const lightZ of [-12, -32, -55, chamberZ]) {
      const lPos = caveLocalToWorld(cb, 0, 9.5, lightZ);
      const caveLight = new THREE.PointLight(site.color, 34, 68, 1.0);
      caveLight.position.copy(lPos);
      caveGroup.add(caveLight);
    }

    for (let a = 0; a < 22; a++) {
      const ang = (a / 22) * Math.PI * 2;
      if (Math.sin(ang) > 0.55 && Math.abs(Math.cos(ang)) < 0.72) continue;
      const lx = Math.cos(ang) * (site.chamberRadius + 4.0);
      const lz = chamberZ + Math.sin(ang) * (site.chamberRadius + 4.0);
      for (const wy of [4.8, 12.2]) {
        const wPos = caveLocalToWorld(cb, lx, wy, lz);
        const wMesh = new THREE.Mesh(rockGeo, caveWallMat);
        wMesh.position.copy(wPos);
        wMesh.quaternion.setFromUnitVectors(upRef, wPos.clone().normalize());
        wMesh.scale.set(6.5, 7.2, 6.5);
        wMesh.castShadow = true;
        wMesh.receiveShadow = true;
        caveGroup.add(wMesh);
      }
    }

    for (let r = 0; r <= 3; r++) {
      const ringCount = r === 0 ? 1 : r * 6;
      const rad = r * 5.8;
      for (let k = 0; k < ringCount; k++) {
        const ang = (k / ringCount) * Math.PI * 2;
        const lx = Math.cos(ang) * rad;
        const lz = chamberZ + Math.sin(ang) * rad;
        const cPos = caveLocalToWorld(cb, lx, 20.5 - r * 0.7, lz);
        const cap = new THREE.Mesh(rockGeo, caveWallMat);
        cap.position.copy(cPos);
        cap.quaternion.setFromUnitVectors(upRef, cPos.clone().normalize());
        cap.scale.set(6.2, 2.8, 6.2);
        cap.castShadow = true;
        cap.receiveShadow = true;
        caveGroup.add(cap);

        const stalPos = caveLocalToWorld(cb, lx, 16.8 - r * 0.7, lz);
        const stal = new THREE.Mesh(new THREE.ConeGeometry(0.75, 3.4, 8), caveWallMat);
        stal.position.copy(stalPos);
        stal.quaternion.setFromUnitVectors(upRef, stalPos.clone().normalize());
        stal.rotateX(Math.PI);
        caveGroup.add(stal);
      }
    }

    const chestPos = caveLocalToWorld(cb, 14.5, 0.0, -45);
    const chestRewards: WeaponId[] = ['scatter', 'voidblade', 'rail'];
    chestConfigs.push({
      pos: chestPos,
      up: chestPos.clone().normalize(),
      rewardWeapon: chestRewards[cIdx],
      shards: 100,
      label: cIdx === 1 ? 'Crimson Void-Blade Katana!' : cIdx === 0 ? 'Scatter Shotgun!' : 'Helios Railgun!',
    });

    for (const [px, pz] of [
      [-9.5, chamberZ - 6.0],
      [9.5, chamberZ - 6.0],
      [-9.5, chamberZ + 6.0],
      [9.5, chamberZ + 6.0],
    ]) {
      const pPos = caveLocalToWorld(cb, px, 7.0, pz);
      const pillar = new THREE.Mesh(new THREE.CylinderGeometry(1.0, 1.45, 15.0, 10), caveWallMat);
      pillar.position.copy(pPos);
      pillar.quaternion.setFromUnitVectors(upRef, pPos.clone().normalize());
      pillar.castShadow = true;
      pillar.receiveShadow = true;
      caveGroup.add(pillar);
      physics.addCollider(caveLocalToWorld(cb, px, 0, pz), 1.45, 'wall', 15.0);
    }

    const pylons: CavePylon[] = [];
    const pylonCoords: [number, number][] = [
      [-11.5, chamberZ],
      [11.5, chamberZ],
      [0, chamberZ - 11.5],
    ];
    for (const [qx, qz] of pylonCoords) {
      const qPos = caveLocalToWorld(cb, qx, 2.0, qz);
      const pMesh = new THREE.Mesh(
        new THREE.OctahedronGeometry(1.3, 0),
        new THREE.MeshStandardMaterial({
          color: '#735cff',
          emissive: '#3e20a8',
          emissiveIntensity: 1.5,
          roughness: 0.2,
        })
      );
      pMesh.scale.set(0.75, 2.0, 0.75);
      pMesh.position.copy(qPos);
      pMesh.quaternion.setFromUnitVectors(upRef, qPos.clone().normalize());
      caveGroup.add(pMesh);
      pylons.push({ mesh: pMesh, worldPos: qPos, ignited: false });
    }

    group.add(caveGroup);
    caves.push({
      id: site.id,
      name: site.name,
      taskTitle: site.taskTitle,
      mouthPos,
      chamberPos,
      pylons,
      waveTriggered: false,
      bossSpawned: false,
      completed: false,
    });
  }

  // Overworld Treasure Chests (more legendary weapons to discover!)
  const extraChestDirs: { dir: THREE.Vector3; weapon?: WeaponId; shards: number; label: string }[] = [
    { dir: new THREE.Vector3(-0.08, 0.23, 0.969).normalize(), weapon: 'nova', shards: 80, label: 'Nova Launcher!' },
    { dir: new THREE.Vector3(0.45, 0.42, 0.788).normalize(), weapon: 'warhammer', shards: 120, label: 'Titan Warhammer!' },
    { dir: new THREE.Vector3(-0.36, -0.22, 0.906).normalize(), weapon: 'spear', shards: 85, label: 'Voidstrike Spear!' },
    { dir: new THREE.Vector3(0.55, -0.35, -0.758).normalize(), weapon: 'dualblades', shards: 120, label: 'Phantom Dual-Blades!' },
    { dir: new THREE.Vector3(-0.62, 0.28, -0.733).normalize(), weapon: 'pickaxe', shards: 120, label: 'Crystal Pickaxe!' },
    { dir: new THREE.Vector3(0.18, 0.56, -0.808).normalize(), weapon: 'minigun', shards: 160, label: 'Vulcan Rotary Cannon!' },
  ];
  for (const ec of extraChestDirs) {
    const pos = getSurfacePosition(ec.dir, 0);
    chestConfigs.push({ pos, up: ec.dir, rewardWeapon: ec.weapon, shards: ec.shards, label: ec.label });
  }

  const chestMat = new THREE.MeshPhysicalMaterial({
    color: '#202b3d',
    map: tex.metalAlbedo,
    normalMap: tex.metalNormal,
    roughness: 0.28,
    metalness: 0.78,
    clearcoat: 0.6,
  });
  const goldTrimMat = new THREE.MeshStandardMaterial({
    color: '#ffd666',
    emissive: '#a66f0c',
    emissiveIntensity: 1.2,
    metalness: 0.9,
    roughness: 0.2,
  });

  chestConfigs.forEach((cfg, idx) => {
    const holder = new THREE.Group();
    holder.position.copy(cfg.pos);
    holder.quaternion.setFromUnitVectors(upRef, cfg.up);

    const base = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.95, 1.35), chestMat);
    base.position.y = 0.48;
    base.castShadow = true;
    holder.add(base);

    const band = new THREE.Mesh(new THREE.BoxGeometry(2.08, 0.16, 1.42), goldTrimMat);
    band.position.y = 0.86;
    holder.add(band);

    const lidPivot = new THREE.Group();
    lidPivot.position.set(0, 0.95, -0.65);
    const lid = new THREE.Mesh(new THREE.CylinderGeometry(0.68, 0.68, 2.02, 12, 1, false, 0, Math.PI), chestMat);
    lid.rotation.z = Math.PI / 2;
    lid.position.set(0, 0.0, 0.65);
    lid.castShadow = true;
    lidPivot.add(lid);
    holder.add(lidPivot);

    const light = new THREE.PointLight('#ffd666', 10, 18);
    light.position.y = 1.6;
    holder.add(light);

    const beamGeo = new THREE.CylinderGeometry(0.14, 0.38, 12, 10, 1, true);
    const beamMat = new THREE.MeshBasicMaterial({
      color: '#ffd666',
      transparent: true,
      opacity: 0.28,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    const chestBeam = new THREE.Mesh(beamGeo, beamMat);
    chestBeam.position.y = 6.5;
    holder.add(chestBeam);

    group.add(holder);
    chests.push({
      id: `chest-${idx}`,
      pos: cfg.pos,
      lidPivot,
      light,
      opened: false,
      rewardWeapon: cfg.rewardWeapon,
      shards: cfg.shards,
      label: cfg.label,
    });
  });

  // 6. Glowing Jump Boost Pads
  const boostPads: BoostPad[] = [];
  const padDirs = [
    new THREE.Vector3(-0.08, 0.21, 0.974).normalize(),
    new THREE.Vector3(0.45, 0.04, 0.892).normalize(),
    new THREE.Vector3(-0.45, 0.08, 0.889).normalize(),
    new THREE.Vector3(0.65, -0.15, 0.745).normalize(),
    new THREE.Vector3(0.05, 0.65, 0.758).normalize(),
    new THREE.Vector3(-0.15, -0.35, -0.924).normalize(),
  ];
  for (const pDir of padDirs) {
    if (evaluateCaveAtDir(pDir) !== null) continue;
    const pos = getSurfacePosition(pDir, 0.15);
    const padGroup = new THREE.Group();
    padGroup.position.copy(pos);
    padGroup.quaternion.setFromUnitVectors(upRef, pDir);

    const base = new THREE.Mesh(
      new THREE.BoxGeometry(4.4, 0.4, 6.4),
      new THREE.MeshStandardMaterial({ color: '#1b2638', emissive: '#083a5c', roughness: 0.3, metalness: 0.8 })
    );
    base.rotation.x = -0.18;
    padGroup.add(base);

    const strip = new THREE.Mesh(
      new THREE.BoxGeometry(2.6, 0.45, 5.2),
      new THREE.MeshBasicMaterial({ color: new THREE.Color(0.3, 2.2, 2.8) })
    );
    strip.rotation.x = -0.18;
    padGroup.add(strip);

    group.add(padGroup);
    boostPads.push({ pos, dir: pDir, mesh: padGroup });
  }

  // 7. Speed Boost Ring Trial (6 Glowing Sky Rings)
  const trialRings: TrialRing[] = [];
  for (let i = 0; i < 6; i++) {
    const ang = -0.35 + i * 0.28;
    const tDir = new THREE.Vector3(Math.sin(ang) * 0.9, 0.35 + i * 0.06, Math.cos(ang) * 0.9).normalize();
    const pos = getSurfacePosition(tDir, 3.0);
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(4.0, 0.28, 12, 32),
      new THREE.MeshBasicMaterial({ color: i === 0 ? '#ffd666' : '#3ee6ff' })
    );
    ring.position.copy(pos);
    ring.quaternion.setFromUnitVectors(upRef, tDir);
    ring.rotateX(Math.PI / 2);
    group.add(ring);
    trialRings.push({ pos, mesh: ring, passed: false });
  }

  // 8. Polar Citadel Monolith
  const polarGroup = new THREE.Group();
  const polarH = getTerrainHeight(POLAR_SPIRE_DIR);
  const polarBasePos = POLAR_SPIRE_DIR.clone().multiplyScalar(polarH);
  polarGroup.position.copy(polarBasePos);
  polarGroup.quaternion.setFromUnitVectors(upRef, POLAR_SPIRE_DIR);
  physics.addCollider(polarBasePos, 7.0, 'wall', 16.0);

  const plinth = new THREE.Mesh(
    new THREE.CylinderGeometry(6.5, 8.2, 1.5, 12),
    new THREE.MeshStandardMaterial({ color: '#273549', roughness: 0.45, metalness: 0.6 })
  );
  plinth.position.y = 0.75;
  plinth.receiveShadow = true;
  plinth.castShadow = true;
  polarGroup.add(plinth);

  const obelisk = new THREE.Mesh(
    new THREE.CylinderGeometry(1.0, 2.4, 15, 8),
    new THREE.MeshStandardMaterial({ color: '#1b2838', roughness: 0.3, metalness: 0.75 })
  );
  obelisk.position.y = 8.0;
  obelisk.castShadow = true;
  obelisk.receiveShadow = true;
  polarGroup.add(obelisk);

  const polarBeaconRing = new THREE.Mesh(
    new THREE.TorusGeometry(3.8, 0.26, 14, 40),
    new THREE.MeshStandardMaterial({ color: '#63e6ff', emissive: '#1db7ff', emissiveIntensity: 1.9 })
  );
  polarBeaconRing.position.y = 13.5;
  polarGroup.add(polarBeaconRing);

  const polarBeaconCore = new THREE.Mesh(
    new THREE.OctahedronGeometry(1.4, 1),
    new THREE.MeshStandardMaterial({ color: '#ffffff', emissive: '#58e2ff', emissiveIntensity: 2.2 })
  );
  polarBeaconCore.position.y = 13.5;
  polarGroup.add(polarBeaconCore);

  const spireLight = new THREE.PointLight('#4de8ff', 10, 42);
  spireLight.position.y = 13.5;
  polarGroup.add(spireLight);
  group.add(polarGroup);

  // 9. Air Force Jet Landing Pad Right Beside Spawn (clear 19m separation so wings NEVER clip Rover!)
  const airPadDir = new THREE.Vector3(0.118, 0.23, 0.966).normalize();
  const airPadPos = getSurfacePosition(airPadDir, 0.25);
  const airPadGroup = new THREE.Group();
  airPadGroup.position.copy(airPadPos);
  airPadGroup.quaternion.setFromUnitVectors(upRef, airPadDir);
  const padDeck = new THREE.Mesh(
    new THREE.CylinderGeometry(6.8, 7.6, 0.65, 16),
    new THREE.MeshPhysicalMaterial({ color: '#1d2838', roughness: 0.35, metalness: 0.75, clearcoat: 0.4 })
  );
  airPadGroup.add(padDeck);
  const padRing = new THREE.Mesh(
    new THREE.TorusGeometry(6.2, 0.14, 8, 36),
    new THREE.MeshBasicMaterial({ color: new THREE.Color(0.3, 2.0, 2.8) })
  );
  padRing.rotation.x = Math.PI / 2;
  padRing.position.y = 0.36;
  airPadGroup.add(padRing);
  group.add(airPadGroup);

  const fallRotQuat = new THREE.Quaternion();
  const baseQuat = new THREE.Quaternion();

  return {
    group,
    caves,
    chests,
    crystalNodes,
    boostPads,
    trialRings,
    trialActive: false,
    trialTimer: 0,
    polarBeaconRing,
    polarBeaconCore,
    airPadPos,
    knockDownTree,
    damageTree,
    update(time: number, dt: number, spireActivated: boolean) {
      windUniform.value = time;
      polarBeaconRing.rotation.x = time * (spireActivated ? 2.4 : 0.7);
      polarBeaconRing.rotation.y = time * (spireActivated ? 1.8 : 0.45);
      polarBeaconCore.rotation.y = -time * (spireActivated ? 3.0 : 1.1);
      const coreMat = polarBeaconCore.material as THREE.MeshStandardMaterial;
      coreMat.emissiveIntensity = spireActivated ? 3.2 : 1.7 + Math.sin(time * 3) * 0.35;
      spireLight.intensity = spireActivated ? 16 : 9;

      for (const cave of caves) {
        for (const p of cave.pylons) p.mesh.rotation.y = time * (p.ignited ? 2.5 : 0.8);
      }
      for (const node of crystalNodes) {
        if (!node.destroyed) node.mesh.rotation.y = time * 0.9;
      }
      for (const tr of trialRings) {
        if (!tr.passed) tr.mesh.rotation.z = time * 1.4;
      }

      // Real Physics Falling Trees!
      for (let i = fallingTrees.length - 1; i >= 0; i--) {
        const ft = fallingTrees[i];
        ft.life -= dt;
        const nUp = ft.pos.clone().normalize();
        ft.vel.addScaledVector(nUp, -26 * dt);
        ft.pos.addScaledVector(ft.vel, dt);

        const gh = Math.max(SEA_LEVEL, getTerrainHeight(nUp));
        if (ft.pos.length() <= gh + 0.35) {
          ft.pos.copy(nUp).multiplyScalar(gh + 0.35);
          ft.vel.multiplyScalar(0.45);
          if (!ft.settled && ft.fallAngle > 1.35) {
            ft.settled = true;
            ft.angVel = 0;
          }
        }

        if (!ft.settled) {
          ft.angVel += 4.2 * dt;
          ft.fallAngle += ft.angVel * dt;
          if (ft.fallAngle >= Math.PI * 0.49) {
            ft.fallAngle = Math.PI * 0.49;
            ft.angVel = -ft.angVel * 0.25;
            if (Math.abs(ft.angVel) < 0.4) ft.settled = true;
          }
        }

        baseQuat.setFromUnitVectors(upRef, ft.up);
        const yawQuat = new THREE.Quaternion().setFromAxisAngle(upRef, ft.rotY);
        baseQuat.multiply(yawQuat);
        fallRotQuat.setFromAxisAngle(ft.fallAxis, ft.fallAngle);
        ft.mesh.quaternion.copy(fallRotQuat).multiply(baseQuat);
        ft.mesh.position.copy(ft.pos);

        if (ft.life < 1.2) {
          const s = Math.max(0.01, ft.life / 1.2);
          ft.mesh.scale.set(ft.scale * s, ft.scaleY * s, ft.scale * s);
        }
        if (ft.life <= 0) {
          group.remove(ft.mesh);
          fallingTrees.splice(i, 1);
        }
      }

      // Flying Wood Splinters & Leaves!
      for (let i = splinters.length - 1; i >= 0; i--) {
        const sp = splinters[i];
        sp.life -= dt;
        const spUp = sp.mesh.position.clone().normalize();
        sp.vel.addScaledVector(spUp, -24 * dt);
        sp.mesh.position.addScaledVector(sp.vel, dt);
        sp.mesh.rotation.x += dt * 11;
        sp.mesh.rotation.z += dt * 9;
        sp.mesh.scale.setScalar(Math.max(0.01, sp.life));
        if (sp.life <= 0) {
          group.remove(sp.mesh);
          splinters.splice(i, 1);
        }
      }
    },
  };
}
