import * as THREE from 'three';
import { CAVE_BASES, PLANETS, PlanetConfig, evaluateCaveAtDir, projectOntoTangent } from '../math/spherical';

export interface StaticCollider {
  id: number;
  pos: THREE.Vector3;
  radius: number;
  height: number;
  kind: 'tree' | 'rock' | 'wall' | 'crystal';
  broken?: boolean;
  metaIdx?: number;
  scale?: number;
}

/**
 * Spatial 3D cylinder/sphere collision solver supporting destructible props (trees, crystals)
 * and planet-centered local coordinate spheres.
 */
export class PhysicsWorld {
  public colliders: StaticCollider[] = [];
  private buckets = new Map<string, StaticCollider[]>();
  private nextId = 1;

  public clear(): void {
    this.colliders = [];
    this.buckets.clear();
  }

  private getKey(dir: THREE.Vector3): string {
    const gx = Math.floor(dir.x * 14);
    const gy = Math.floor(dir.y * 14);
    const gz = Math.floor(dir.z * 14);
    return `${gx},${gy},${gz}`;
  }

  public addCollider(
    pos: THREE.Vector3,
    radius: number,
    kind: StaticCollider['kind'],
    height = 5.0,
    metaIdx?: number,
    scale?: number
  ): StaticCollider {
    const col: StaticCollider = {
      id: this.nextId++,
      pos: pos.clone(),
      radius,
      height,
      kind,
      broken: false,
      metaIdx,
      scale,
    };
    this.colliders.push(col);
    const dir = pos.clone().normalize();
    const k = this.getKey(dir);
    let list = this.buckets.get(k);
    if (!list) {
      list = [];
      this.buckets.set(k, list);
    }
    list.push(col);
    return col;
  }

  public resolveCollisions(
    position: THREE.Vector3,
    velocity: THREE.Vector3,
    entityRadius: number,
    planet: PlanetConfig = PLANETS[0],
    onBreakCollider?: (col: StaticCollider, impactSpeed: number, impactDir: THREE.Vector3) => boolean
  ): number {
    let maxImpact = 0;
    const localPos = position.clone().sub(planet.center);
    const up = localPos.clone().normalize();
    const entityR = localPos.length();
    const delta = new THREE.Vector3();

    // Static Aetheria Prime spatial grid props (trees, rocks, cave walls, outposts)
    if (planet.id === 'aetheria') {
      const gx = Math.floor(up.x * 14);
      const gy = Math.floor(up.y * 14);
      const gz = Math.floor(up.z * 14);

      for (let dx = -1; dx <= 1; dx++) {
        for (let dy = -1; dy <= 1; dy++) {
          for (let dz = -1; dz <= 1; dz++) {
            const list = this.buckets.get(`${gx + dx},${gy + dy},${gz + dz}`);
            if (!list) continue;
            for (const col of list) {
              if (col.broken) continue;
              const colR = col.pos.length();
              if (entityR > colR + col.height || entityR + 2.2 < colR) continue;

              delta.copy(position).sub(col.pos);
              projectOntoTangent(delta, up, delta);
              const distSq = delta.lengthSq();
              const minD = entityRadius + col.radius;
              if (distSq < minD * minD) {
                const impactSpd = velocity.length();
                if (onBreakCollider && col.kind === 'tree' && onBreakCollider(col, impactSpd, velocity.clone().normalize())) {
                  col.broken = true;
                  maxImpact = Math.max(maxImpact, impactSpd * 0.4);
                  // Keep momentum! Only minor wood-crunch slowdown (12%) instead of dead-stopping
                  velocity.multiplyScalar(0.88);
                  continue;
                }

                const dist = Math.sqrt(distSq);
                const n = dist > 0.001 ? delta.divideScalar(dist) : new THREE.Vector3(1, 0, 0).cross(up).normalize();
                const push = minD - dist;
                position.addScaledVector(n, push);

                const vn = velocity.dot(n);
                if (vn < 0) {
                  maxImpact = Math.max(maxImpact, -vn);
                  velocity.addScaledVector(n, -vn * 1.15);
                }
              }
            }
          }
        }
      }

      // Asymmetric cave wall containment
      const cInfo = evaluateCaveAtDir(up);
      if (cInfo && cInfo.localZ < -1.5 && entityR < cInfo.ceilingR) {
        const cb = CAVE_BASES.find((b) => b.site.id === cInfo.cave.id);
        if (cb) {
          const leftLimit = Math.max(2.0, cInfo.leftExtend - entityRadius);
          const rightLimit = Math.max(2.0, cInfo.rightExtend - entityRadius);
          if (cInfo.localX < -leftLimit) {
            const push = -cInfo.localX - leftLimit;
            position.addScaledVector(cb.right, push);
            const vn = velocity.dot(cb.right);
            if (vn < 0) {
              maxImpact = Math.max(maxImpact, -vn);
              velocity.addScaledVector(cb.right, -vn * 1.15);
            }
          } else if (cInfo.localX > rightLimit) {
            const push = cInfo.localX - rightLimit;
            position.addScaledVector(cb.right, -push);
            const vn = velocity.dot(cb.right);
            if (vn > 0) {
              maxImpact = Math.max(maxImpact, vn);
              velocity.addScaledVector(cb.right, -vn * 1.15);
            }
          }
          const chamberCenterZ = -cb.site.length + cb.site.chamberRadius * 0.45;
          const maxDepth = -(chamberCenterZ - cb.site.chamberRadius + entityRadius);
          if (cInfo.inChamber) {
            const cx = cInfo.localX;
            const cz = cInfo.localZ - chamberCenterZ;
            const maxChR = Math.max(4.0, cb.site.chamberRadius - entityRadius);
            const distCh = Math.hypot(cx, cz);
            if (distCh > maxChR && cInfo.localZ < chamberCenterZ + cb.site.chamberRadius * 0.4) {
              const nx = cx / distCh;
              const nz = cz / distCh;
              const push = distCh - maxChR;
              const pushVec = new THREE.Vector3().addScaledVector(cb.right, -nx).addScaledVector(cb.fwd, nz).normalize();
              position.addScaledVector(pushVec, push);
              const vn = velocity.dot(pushVec);
              if (vn < 0) {
                maxImpact = Math.max(maxImpact, -vn);
                velocity.addScaledVector(pushVec, -vn * 1.15);
              }
            }
          }
          if (-cInfo.localZ > maxDepth) {
            const push = -cInfo.localZ - maxDepth;
            position.addScaledVector(cb.fwd, -push);
            const vf = velocity.dot(cb.fwd);
            if (vf > 0) {
              maxImpact = Math.max(maxImpact, vf);
              velocity.addScaledVector(cb.fwd, -vf * 1.15);
            }
          }
        }
      }
    }

    return maxImpact;
  }

  public findHitTree(point: THREE.Vector3, maxDist: number, prevPoint?: THREE.Vector3): StaticCollider | null {
    const up = point.clone().normalize();
    const gx = Math.floor(up.x * 14);
    const gy = Math.floor(up.y * 14);
    const gz = Math.floor(up.z * 14);
    const samplePt = prevPoint ? prevPoint.clone().lerp(point, 0.5) : point;
    const tUp = new THREE.Vector3();
    const topPos = new THREE.Vector3();
    const closest = new THREE.Vector3();
    const seg = new THREE.Line3();

    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        for (let dz = -1; dz <= 1; dz++) {
          const list = this.buckets.get(`${gx + dx},${gy + dy},${gz + dz}`);
          if (!list) continue;
          for (const col of list) {
            if (col.broken || col.kind !== 'tree') continue;
            tUp.copy(col.pos).normalize();
            topPos.copy(col.pos).addScaledVector(tUp, col.height);
            seg.set(col.pos, topPos);
            seg.closestPointToPoint(samplePt, true, closest);
            const hitR = maxDist + col.radius * 2.2;
            if (closest.distanceToSquared(samplePt) <= hitR * hitR) return col;
          }
        }
      }
    }
    return null;
  }
}
