import * as THREE from 'three';
import { PLANET_RADIUS } from '../math/spherical';

export interface SurroundingsSystem {
  group: THREE.Group;
  sunMesh: THREE.Mesh;
  update(time: number, sunDir: THREE.Vector3): void;
}

export function createSurroundings(sunDir: THREE.Vector3): SurroundingsSystem {
  const group = new THREE.Group();
  const sunDirUniform = { value: sunDir.clone().normalize() };
  const timeUniform = { value: 0 };

  // 1. Opaque Atmospheric Sky + Nebula + Sun-Lit Cloud Dome (wraps entire 4-planet solar system!)
  const skyGeo = new THREE.SphereGeometry(1950, 36, 28);
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    transparent: false,
    uniforms: {
      uSunDir: sunDirUniform,
      uTime: timeUniform,
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vDir;
      uniform vec3 uSunDir;
      uniform float uTime;

      float h3(vec3 p) {
        p = fract(p * 0.1031);
        p += dot(p, p.yzx + 33.33);
        return fract((p.x + p.y) * p.z);
      }
      float vn(vec3 x) {
        vec3 i = floor(x);
        vec3 f = fract(x);
        f = f * f * (3.0 - 2.0 * f);
        return mix(
          mix(mix(h3(i), h3(i + vec3(1,0,0)), f.x), mix(h3(i + vec3(0,1,0)), h3(i + vec3(1,1,0)), f.x), f.y),
          mix(mix(h3(i + vec3(0,0,1)), h3(i + vec3(1,0,1)), f.x), mix(h3(i + vec3(0,1,1)), h3(i + vec3(1,1,1)), f.x), f.y),
          f.z
        );
      }
      float fbm(vec3 p) {
        return vn(p) * 0.55 + vn(p * 2.1) * 0.28 + vn(p * 4.4) * 0.17;
      }

      void main() {
        float sunDot = max(0.0, dot(vDir, uSunDir));
        float sunGlow = pow(sunDot, 7.0) * 0.58 + pow(sunDot, 48.0) * 0.68;

        vec3 spaceCol = vec3(0.014, 0.028, 0.068);
        vec3 nebA = vec3(0.04, 0.12, 0.24) * exp(-pow(vDir.y * 2.2 + vDir.x * 0.7, 2.0));
        vec3 daySky = vec3(0.08, 0.24, 0.48);
        vec3 horizonGold = vec3(1.0, 0.66, 0.38);

        float dayMask = smoothstep(-0.2, 0.78, dot(vDir, uSunDir));
        vec3 col = mix(spaceCol + nebA, daySky, dayMask * 0.72);
        col += horizonGold * sunGlow;

        vec3 cloudCoord = vDir * 4.2 + vec3(uTime * 0.012, 0.0, -uTime * 0.008);
        float c = fbm(cloudCoord);
        float cloudAlpha = smoothstep(0.57, 0.82, c) * (0.26 + 0.55 * dayMask);
        vec3 cloudCol = mix(vec3(0.32, 0.46, 0.68), vec3(1.0, 0.93, 0.86), sunDot * 0.75 + 0.25);
        col = mix(col, cloudCol, cloudAlpha * 0.58);

        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const skyMesh = new THREE.Mesh(skyGeo, skyMat);
  skyMesh.renderOrder = -10;
  group.add(skyMesh);

  // 2. Deep-Space Starfield
  const starCount = 3600;
  const starPos = new Float32Array(starCount * 3);
  const starCol = new Float32Array(starCount * 3);
  const tmpCol = new THREE.Color();
  for (let i = 0; i < starCount; i++) {
    const u = Math.random();
    const v = Math.random();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);
    const r = 1650 + Math.random() * 200;
    starPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    starPos[i * 3 + 1] = r * Math.cos(phi);
    starPos[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);

    const tint = Math.random();
    if (tint < 0.25) tmpCol.setHex(0x9ad4ff);
    else if (tint < 0.45) tmpCol.setHex(0xffe1b5);
    else tmpCol.setHex(0xffffff);
    const b = 0.6 + Math.random() * 0.4;
    starCol[i * 3] = tmpCol.r * b;
    starCol[i * 3 + 1] = tmpCol.g * b;
    starCol[i * 3 + 2] = tmpCol.b * b;
  }
  const starGeo = new THREE.BufferGeometry();
  starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
  starGeo.setAttribute('color', new THREE.BufferAttribute(starCol, 3));
  // Soft circular radial star sprite (no flat blocky square pixels!)
  const starCanvas = document.createElement('canvas');
  starCanvas.width = 32;
  starCanvas.height = 32;
  const sCtx = starCanvas.getContext('2d')!;
  const grad = sCtx.createRadialGradient(16, 16, 0, 16, 16, 16);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.35, 'rgba(255,255,255,0.85)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  sCtx.fillStyle = grad;
  sCtx.fillRect(0, 0, 32, 32);
  const starSprite = new THREE.CanvasTexture(starCanvas);

  const starMat = new THREE.PointsMaterial({
    size: 4.5,
    map: starSprite,
    alphaTest: 0.02,
    vertexColors: true,
    transparent: true,
    opacity: 0.9,
    sizeAttenuation: true,
    depthWrite: false,
  });
  const stars = new THREE.Points(starGeo, starMat);
  stars.renderOrder = -9;
  group.add(stars);

  // 3. Radiant Sun + Corona Halo
  const sunGroup = new THREE.Group();
  const sunMesh = new THREE.Mesh(
    new THREE.SphereGeometry(42, 28, 28),
    new THREE.MeshBasicMaterial({ color: new THREE.Color(2.5, 2.0, 1.4) })
  );
  sunGroup.add(sunMesh);

  const coronaGeo = new THREE.PlaneGeometry(290, 290);
  const coronaMat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    vertexShader: `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        vec4 mvCenter = modelViewMatrix * vec4(0.0, 0.0, 0.0, 1.0);
        mvCenter.xy += position.xy;
        gl_Position = projectionMatrix * mvCenter;
      }
    `,
    fragmentShader: `
      varying vec2 vUv;
      void main() {
        float d = length(vUv - 0.5) * 2.0;
        float glow = exp(-d * 3.4) * 0.92 + exp(-d * 1.3) * 0.28;
        float edge = 1.0 - smoothstep(0.7, 1.0, d);
        vec3 col = vec3(1.0, 0.84, 0.58) * glow * edge;
        gl_FragColor = vec4(col, clamp(glow * edge, 0.0, 1.0));
      }
    `,
  });
  sunGroup.add(new THREE.Mesh(coronaGeo, coronaMat));
  sunGroup.position.copy(sunDir).multiplyScalar(1350);
  group.add(sunGroup);

  // 4. Own Planet Tilted Ring System (the other 3 planets Aurelia, Pyros, Glacies are now REAL explorable worlds in multiplanet.ts!)
  const ringPivot = new THREE.Group();
  ringPivot.rotation.set(0.36, 0.24, -0.2);
  group.add(ringPivot);

  const ringGeo = new THREE.RingGeometry(PLANET_RADIUS + 80, PLANET_RADIUS + 165, 128, 1);
  const ringMat = new THREE.ShaderMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
    uniforms: {
      uInner: { value: PLANET_RADIUS + 80 },
      uOuter: { value: PLANET_RADIUS + 165 },
      uPlanetR: { value: PLANET_RADIUS },
      uSunDir: sunDirUniform,
    },
    vertexShader: `
      varying vec3 vLocalPos;
      varying vec3 vWorldPos;
      void main() {
        vLocalPos = position;
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorldPos = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      varying vec3 vLocalPos;
      varying vec3 vWorldPos;
      uniform float uInner;
      uniform float uOuter;
      uniform float uPlanetR;
      uniform vec3 uSunDir;
      void main() {
        float r = length(vLocalPos.xy);
        float t = clamp((r - uInner) / (uOuter - uInner), 0.0, 1.0);
        float bands = sin(t * 48.0) * 0.35 + sin(t * 17.0) * 0.35 + 0.55;
        float cassini = smoothstep(0.02, 0.06, abs(t - 0.58));
        float edgeFade = smoothstep(0.0, 0.14, t) * (1.0 - smoothstep(0.82, 1.0, t));

        float proj = dot(vWorldPos, uSunDir);
        float shadow = 1.0;
        if (proj < 0.0) {
          float perpDist = length(vWorldPos - uSunDir * proj);
          shadow = smoothstep(uPlanetR - 4.0, uPlanetR + 8.0, perpDist);
        }

        vec3 col = mix(vec3(0.48, 0.78, 1.0), vec3(0.92, 0.78, 0.64), t) * (0.14 + 0.86 * shadow);
        float alpha = clamp(bands * cassini * edgeFade * 0.34, 0.0, 0.44);
        gl_FragColor = vec4(col, alpha);
      }
    `,
  });
  const ringMesh = new THREE.Mesh(ringGeo, ringMat);
  ringMesh.rotation.x = Math.PI / 2;
  ringPivot.add(ringMesh);

  return {
    group,
    sunMesh,
    update(time: number, curSunDir: THREE.Vector3) {
      sunDirUniform.value.copy(curSunDir).normalize();
      timeUniform.value = time;
      sunGroup.position.copy(curSunDir).multiplyScalar(1350);
      ringMesh.rotation.z = time * 0.012;
    },
  };
}
