export function getPlanetById(id: PlanetId): PlanetConfig {
  return PLANETS.find((p) => p.id === id) ?? PLANETS[0];
}

export function getNearestPlanet(worldPos: THREE.Vector3): { planet: PlanetConfig; altitude: number; distFromCenter: number } {
  let best = PLANETS[0];
  let bestAlt = Infinity;
  let bestDist = Infinity;
  for (const p of PLANETS) {
    const d = worldPos.distanceTo(p.center);
    const alt = d - p.radius;
    if (alt < bestAlt) {
      bestAlt = alt;
      best = p;
      bestDist = d;
    }
  }
  return { planet: best, altitude: bestAlt, distFromCenter: bestDist };
}

