export const LAKE_DIRS = [
  new THREE.Vector3(-0.14, 0.30, 0.943).normalize(),
  new THREE.Vector3(0.76, -0.15, 0.63).normalize(),
  new THREE.Vector3(-0.66, 0.42, -0.62).normalize(),
  new THREE.Vector3(0.45, -0.58, 0.68).normalize(),
  new THREE.Vector3(-0.15, 0.64, 0.75).normalize(),
];

function hash3(ix: number, iy: number, iz: number): number {
  let n = ix * 374761393 + iy * 668265263 + iz * 1274126177;
  n = (n ^ (n >> 13)) * 1274126177;
  return ((n ^ (n >> 16)) >>> 0) / 4294967295;
}

function fade(t: number): number {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

export function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = Math.max(0, Math.min(1, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

export function noise3D(x: number, y: number, z: number): number {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const iz = Math.floor(z);
  const fx = fade(x - ix);
  const fy = fade(y - iy);
  const fz = fade(z - iz);

  const c000 = hash3(ix, iy, iz);
  const c100 = hash3(ix + 1, iy, iz);
  const c010 = hash3(ix, iy + 1, iz);
  const c110 = hash3(ix + 1, iy + 1, iz);
  const c001 = hash3(ix, iy, iz + 1);
  const c101 = hash3(ix + 1, iy, iz + 1);
  const c011 = hash3(ix, iy + 1, iz + 1);
  const c111 = hash3(ix + 1, iy + 1, iz + 1);

  return (
    lerp(
      lerp(lerp(c000, c100, fx), lerp(c010, c110, fx), fy),
      lerp(lerp(c001, c101, fx), lerp(c011, c111, fx), fy),
      fz
    ) *
      2 -
    1
  );
}

export function fbm3D(x: number, y: number, z: number, octaves = 4): number {
  let value = 0;
  let amp = 0.5;
  let freq = 1;
  for (let i = 0; i < octaves; i++) {
    value += amp * noise3D(x * freq, y * freq, z * freq);
    freq *= 2.07;
    amp *= 0.5;
  }
  return value;
}

export function ridged3D(x: number, y: number, z: number, octaves = 4): number {
  let value = 0;
  let amp = 0.5;
  let freq = 1;
  for (let i = 0; i < octaves; i++) {
    const n = 1.0 - Math.abs(noise3D(x * freq, y * freq, z * freq));
    value += amp * n * n;
    freq *= 2.15;
    amp *= 0.5;
  }
  return value;
}

export interface CaveBasis {
  site: CaveSiteConfig;
  up: THREE.Vector3;
  fwd: THREE.Vector3;
  right: THREE.Vector3;
  mouthR: number;
}

const HERO_PEAK_A = new THREE.Vector3(0.06, 0.43, 0.901).normalize();
const HERO_PEAK_B = new THREE.Vector3(-0.26, 0.42, 0.869).normalize();

function baseElevation(dx: number, dy: number, dz: number): number {
  const continent = fbm3D(dx * 2.1 + 11.3, dy * 2.1 - 4.7, dz * 2.1 + 7.1, 4);
  const ridges = ridged3D(dx * 4.2 - 2.1, dy * 4.2 + 5.9, dz * 4.2 - 9.2, 4);
  const detail = fbm3D(dx * 11.0 + 3.1, dy * 11.0 + 8.4, dz * 11.0 - 1.5, 3);

  const mountainMask = smoothstep(-0.2, 0.48, continent);
  let h = 2.8 + continent * 5.2 + ridges * 15.5 * mountainMask + detail * 1.1;

  for (const peak of [HERO_PEAK_A, HERO_PEAK_B]) {
    const peakD = Math.hypot(dx - peak.x, dy - peak.y, dz - peak.z) * PLANET_RADIUS;
    if (peakD < 36) {
      h += (1 - smoothstep(4, 36, peakD)) * 20.0;
    }
  }

  for (const lDir of LAKE_DIRS) {
    const d = Math.hypot(dx - lDir.x, dy - lDir.y, dz - lDir.z) * PLANET_RADIUS;
    if (d < 22) {
      const bowl = 1 - smoothstep(4.5, 22, d);
      h -= bowl * 18.5;
    }
  }

  const polar = Math.abs(dy);
  if (polar > 0.82) {
    h += smoothstep(0.82, 0.98, polar) * 4.0;
  }

  return PLANET_RADIUS + h;
}

const SPAWN_BASE_H = Math.max(SEA_LEVEL + 5.5, baseElevation(SPAWN_DIR.x, SPAWN_DIR.y, SPAWN_DIR.z));
const POLAR_BASE_H = Math.max(SEA_LEVEL + 8.5, baseElevation(POLAR_SPIRE_DIR.x, POLAR_SPIRE_DIR.y, POLAR_SPIRE_DIR.z));
const CAMP_BASE_HS = CAMP_SITES.map((c) =>
  Math.max(SEA_LEVEL + 5.5, baseElevation(c.dir.x, c.dir.y, c.dir.z))
);

export const CAVE_BASES: CaveBasis[] = CAVE_SITES.map((site) => {
  const up = site.mouthDir.clone().normalize();
  const fwd = site.inwardHint.clone().addScaledVector(up, -site.inwardHint.dot(up)).normalize();
  const right = new THREE.Vector3().crossVectors(fwd, up).normalize();
  const mouthR = Math.max(PLANET_RADIUS + 10.5, baseElevation(up.x, up.y, up.z));
  return { site, up, fwd, right, mouthR };
});

const _cTang = new THREE.Vector3();

export function evaluateCaveAtDir(dir: THREE.Vector3): CaveLocalInfo | null {
  for (const cb of CAVE_BASES) {
    const cosT = dir.dot(cb.up);
    if (cosT < 0.6) continue;

    _cTang.copy(dir).addScaledVector(cb.up, -cosT);
    const sinT = _cTang.length();
    let localX = 0;
    let localZ = 0;
    if (sinT > 0.00001) {
      const arcDist = Math.atan2(sinT, cosT) * PLANET_RADIUS;
      localX = (_cTang.dot(cb.right) / sinT) * arcDist;
      localZ = -(_cTang.dot(cb.fwd) / sinT) * arcDist;
    }

    const chamberCenterZ = -cb.site.length + cb.site.chamberRadius * 0.45;
    const minZ = chamberCenterZ - cb.site.chamberRadius - 6.0;
    if (localZ > 12 || localZ < minZ) continue;

    const distToChamber = Math.hypot(localX, localZ - chamberCenterZ);
    const tunnelWidth = 9.5;
    const chamberBlend = 1 - smoothstep(cb.site.chamberRadius - 2.0, cb.site.chamberRadius + 7.0, distToChamber);
    const chamberHalf = Math.sqrt(
      Math.max(0, cb.site.chamberRadius * cb.site.chamberRadius - (localZ - chamberCenterZ) * (localZ - chamberCenterZ))
    );
    const baseHalf = Math.max(tunnelWidth, lerp(tunnelWidth, Math.max(tunnelWidth, chamberHalf), chamberBlend));

    const alcoveW = (1 - smoothstep(6, 13, Math.abs(localZ + 45))) * 9.5;
    const leftExtend = baseHalf;
    const rightExtend = baseHalf + alcoveW;
    const halfWidth = Math.max(leftExtend, rightExtend);
    const inChamber = distToChamber <= cb.site.chamberRadius + 2.0;

    if (localX >= -(leftExtend + 5.0) && localX <= rightExtend + 5.0) {
      const depthIntoCave = Math.max(0, -localZ);
      const tDepth = Math.min(1, depthIntoCave / (cb.site.length * 0.68));
      const drop = smoothstep(0.0, 1.0, tDepth) * 12.0;
      const floorR = cb.mouthR - drop;
      const ceilingHeight = lerp(13.5, 19.5, chamberBlend);
      const ceilingR = floorR + ceilingHeight;
      const exteriorR = Math.max(ceilingR + 0.5, baseElevation(dir.x, dir.y, dir.z));
      const inCorridor =
        localZ <= 5.0 &&
        localZ >= chamberCenterZ - cb.site.chamberRadius - 1.5 &&
        localX >= -(leftExtend + 1.5) &&
        localX <= rightExtend + 1.5;

      return {
        cave: cb.site,
        inCorridor,
        inChamber,
        localX,
        localZ,
        halfWidth,
        leftExtend,
        rightExtend,
        floorR,
        ceilingR,
        exteriorR,
        distFromMouth: depthIntoCave,
      };
    }
  }
  return null;
}

const _tmpDir = new THREE.Vector3();

/** Height evaluation on any of our 4 explorable 3D planets (returns radial distance from planet center) */
export function getPlanetTerrainHeight(dirOrLocalPos: THREE.Vector3, planetId: PlanetId = 'aetheria'): number {
  if (planetId === 'aetheria') return getTerrainHeight(dirOrLocalPos);

  _tmpDir.copy(dirOrLocalPos).normalize();
  const dx = _tmpDir.x;
  const dy = _tmpDir.y;
  const dz = _tmpDir.z;

  if (planetId === 'aurelia') {
    const p = PLANETS[1];
    const cont = fbm3D(dx * 2.5 + 3.1, dy * 2.5 - 8.2, dz * 2.5 + 4.4, 3);
    const ridge = ridged3D(dx * 4.5 + 1.2, dy * 4.5 + 2.3, dz * 4.5 - 5.1, 3);
    const h = 1.5 + cont * 3.8 + ridge * 7.5 * smoothstep(-0.15, 0.5, cont);
    return p.radius + h;
  }
  if (planetId === 'pyros') {
    const p = PLANETS[2];
    const cracks = ridged3D(dx * 3.8 - 6.1, dy * 3.8 + 1.9, dz * 3.8 + 3.3, 3);
    const plates = fbm3D(dx * 2.2 + 9.0, dy * 2.2 - 3.0, dz * 2.2 - 2.0, 3);
    const lavaMask = smoothstep(-0.35, 0.2, plates);
    const h = -4.0 + lavaMask * (4.5 + cracks * 8.0);
    return p.radius + h;
  }
  // glacies
  const p = PLANETS[3];
  const ice = fbm3D(dx * 3.0 + 5.2, dy * 3.0 + 6.1, dz * 3.0 - 4.7, 3);
  const craters = Math.abs(noise3D(dx * 5.4, dy * 5.4, dz * 5.4));
  const craterBowl = smoothstep(0.05, 0.35, craters);
  const h = -1.5 + ice * 3.5 + craterBowl * 4.8;
  return p.radius + h;
}

export function getPlanetSurfacePosition(
  planet: PlanetConfig,
  localDir: THREE.Vector3,
  heightOffset = 0,
  out = new THREE.Vector3()
): THREE.Vector3 {
  const n = out.copy(localDir).normalize();
  const h = Math.max(planet.seaLevel + 0.15, getPlanetTerrainHeight(n, planet.id));
  return n.multiplyScalar(h + heightOffset).add(planet.center);
}

export function getTerrainHeight(posOrDir: THREE.Vector3): number {
  _tmpDir.copy(posOrDir).normalize();
  const dx = _tmpDir.x;
  const dy = _tmpDir.y;
  const dz = _tmpDir.z;

  let h = baseElevation(dx, dy, dz);

  const spawnDist = _tmpDir.distanceTo(SPAWN_DIR) * PLANET_RADIUS;
  if (spawnDist < 22) {
    const w = 1 - smoothstep(10, 22, spawnDist);
    h = lerp(h, SPAWN_BASE_H, w);
  }

  const polarDist = _tmpDir.distanceTo(POLAR_SPIRE_DIR) * PLANET_RADIUS;
  if (polarDist < 22) {
    const w = 1 - smoothstep(10, 22, polarDist);
    h = lerp(h, POLAR_BASE_H, w);
  }

  for (let i = 0; i < CAMP_SITES.length; i++) {
    const camp = CAMP_SITES[i];
    const dist = _tmpDir.distanceTo(camp.dir) * PLANET_RADIUS;
    if (dist < camp.plateauRadius + 10) {
      const w = 1 - smoothstep(camp.plateauRadius * 0.65, camp.plateauRadius + 10, dist);
      h = lerp(h, CAMP_BASE_HS[i], w);
    }
  }

  const cInfo = evaluateCaveAtDir(_tmpDir);
  if (cInfo) {
    const limitX = cInfo.localX >= 0 ? cInfo.rightExtend : cInfo.leftExtend;
    const chamberBackZ = -cInfo.cave.length - cInfo.cave.chamberRadius * 0.7;
    const edgeW = 1 - smoothstep(limitX + 1.5, limitX + 6.0, Math.abs(cInfo.localX));
    const frontW = cInfo.localZ > 0 ? 1 - smoothstep(0, 11, cInfo.localZ) : 1;
    const backW =
      cInfo.localZ < chamberBackZ
        ? 1 - smoothstep(0, 7, -(cInfo.localZ - chamberBackZ))
        : 1;
    const w = Math.max(0, Math.min(1, edgeW * frontW * backW));
    h = lerp(h, cInfo.floorR, w);
  }

  return h;
}

const _nUp = new THREE.Vector3();
const _nRef = new THREE.Vector3();
const _nT1 = new THREE.Vector3();
const _nT2 = new THREE.Vector3();
const _nP1p = new THREE.Vector3();
const _nP1n = new THREE.Vector3();
const _nP2p = new THREE.Vector3();
const _nP2n = new THREE.Vector3();

export function getTerrainNormal(posOrDir: THREE.Vector3, out = new THREE.Vector3(), planetId: PlanetId = 'aetheria'): THREE.Vector3 {
  _nUp.copy(posOrDir).normalize();
  if (Math.abs(_nUp.y) < 0.9) _nRef.set(0, 1, 0);
  else _nRef.set(1, 0, 0);
  _nT1.crossVectors(_nRef, _nUp).normalize();
  _nT2.crossVectors(_nUp, _nT1).normalize();

  const eps = 0.005;
  _nP1p.copy(_nUp).addScaledVector(_nT1, eps).normalize();
  _nP1n.copy(_nUp).addScaledVector(_nT1, -eps).normalize();
  _nP2p.copy(_nUp).addScaledVector(_nT2, eps).normalize();
  _nP2n.copy(_nUp).addScaledVector(_nT2, -eps).normalize();

  const h1p = getPlanetTerrainHeight(_nP1p, planetId);
  const h1n = getPlanetTerrainHeight(_nP1n, planetId);
  const h2p = getPlanetTerrainHeight(_nP2p, planetId);
  const h2n = getPlanetTerrainHeight(_nP2n, planetId);

  _nP1p.multiplyScalar(h1p).sub(_nP1n.multiplyScalar(h1n));
  _nP2p.multiplyScalar(h2p).sub(_nP2n.multiplyScalar(h2n));

  out.crossVectors(_nP1p, _nP2p).normalize();
  if (out.dot(_nUp) < 0) out.negate();
  return out;
}

const _rayPt = new THREE.Vector3();
const _rayLo = new THREE.Vector3();

export function raycastTerrain(
  origin: THREE.Vector3,
  dir: THREE.Vector3,
  minDist: number,
  maxDist: number,
  planet: PlanetConfig = PLANETS[0]
): number | null {
  const step = 2.5;
  let prevT = minDist;
  const localOrigin = origin.clone().sub(planet.center);
  for (let t = minDist + step; t <= maxDist; t += step) {
    _rayPt.copy(localOrigin).addScaledVector(dir, t);
    const r = _rayPt.length();
    const ground = getPlanetTerrainHeight(_rayPt, planet.id);
    let hitCeiling = false;
    if (planet.id === 'aetheria') {
      const cInfo = evaluateCaveAtDir(_rayPt.clone().normalize());
      hitCeiling = cInfo !== null && cInfo.inCorridor && cInfo.localZ < -2.0 && r >= cInfo.ceilingR - 1.5;
    }

    if (r <= ground || hitCeiling) {
      let lo = prevT;
      let hi = t;
      for (let k = 0; k < 5; k++) {
        const mid = (lo + hi) * 0.5;
        _rayLo.copy(localOrigin).addScaledVector(dir, mid);
        const mr = _rayLo.length();
        const mg = getPlanetTerrainHeight(_rayLo, planet.id);
        let mCeil = false;
        if (planet.id === 'aetheria') {
          const mc = evaluateCaveAtDir(_rayLo.clone().normalize());
          mCeil = mc !== null && mc.inCorridor && mc.localZ < -2.0 && mr >= mc.ceilingR - 1.5;
        }
        if (mr <= mg || mCeil) hi = mid;
        else lo = mid;
      }
      return (lo + hi) * 0.5;
    }
    prevT = t;
  }
  return null;
}

export function getMoistureAtDir(dir: THREE.Vector3): number {
  const spawnDist = dir.distanceTo(SPAWN_DIR) * PLANET_RADIUS;
  let m = fbm3D(dir.x * 3.1 + 20, dir.y * 3.1, dir.z * 3.1 - 14, 3);
  if (spawnDist < 58) {
    m = lerp(m, 0.45, 1 - smoothstep(24, 58, spawnDist));
  }
  return m;
}

export function getBiomeName(posOrDir: THREE.Vector3, height: number, radialAltitude?: number, planet: PlanetConfig = PLANETS[0]): string {
  if (planet.id === 'aurelia') {
    if (height < planet.seaLevel + 0.5) return 'Aurelia Liquid Gold Basin';
    return height > planet.radius + 5 ? 'Aurelia Spire Plateaus' : 'Aurelia Amber Dunes';
  }
  if (planet.id === 'pyros') {
    if (height < planet.seaLevel + 0.5) return 'Pyros Molten Magma Sea';
    return 'Pyros Obsidian Caldera';
  }
  if (planet.id === 'glacies') {
    if (height < planet.seaLevel + 0.5) return 'Glacies Frozen Cryo-Basin';
    return 'Glacies Diamond Craters';
  }

  const dir = _tmpDir.copy(posOrDir).normalize();
  const cInfo = evaluateCaveAtDir(dir);
  const alt = radialAltitude ?? (posOrDir.length() > 10 ? posOrDir.length() : height);
  if (cInfo && cInfo.inCorridor && cInfo.localZ < -1.5 && alt < cInfo.ceilingR) {
    return `${cInfo.cave.name} (Underground)`;
  }
  if (height < SEA_LEVEL + 0.4) return 'Crystal Lake';
  const lat = Math.abs(dir.y);
  if (lat > 0.78) return 'Polar Cryo-Peaks';
  if (height > PLANET_RADIUS + 12.0) return 'Alpine Spire Peaks';
  const moisture = getMoistureAtDir(dir);
  if (moisture > 0.0) return 'Emerald Forest';
  if (moisture < -0.18) return 'Solaris Amber Canyons';
  return 'Aetherian Highlands';
}

const _deltaQuat = new THREE.Quaternion();
export function parallelTransport(
  orientation: THREE.Quaternion,
  prevUp: THREE.Vector3,
  newUp: THREE.Vector3
): void {
  if (prevUp.dot(newUp) < 0.9999999) {
    _deltaQuat.setFromUnitVectors(prevUp, newUp);
    orientation.premultiply(_deltaQuat).normalize();
  }
}

export function projectOntoTangent(
  vec: THREE.Vector3,
  up: THREE.Vector3,
  out = new THREE.Vector3()
): THREE.Vector3 {
  return out.copy(vec).addScaledVector(up, -vec.dot(up));
}

export function getSurfacePosition(
  dir: THREE.Vector3,
  heightOffset = 0,
  out = new THREE.Vector3()
): THREE.Vector3 {
  const n = out.copy(dir).normalize();
  const h = Math.max(SEA_LEVEL + 0.1, getTerrainHeight(n));
  return n.multiplyScalar(h + heightOffset);
}
