import * as THREE from 'three';
import {
  CAMP_SITES,
  PLANETS,
  PlanetConfig,
  getPlanetSurfacePosition,
  getPlanetTerrainHeight,
  getSurfacePosition,
} from '../math/spherical';
import { PhysicsWorld } from '../physics/collision';
import { getProceduralTextures } from '../rendering/textures';

export type EnemyType = 'drone' | 'mech' | 'boss' | 'scout' | 'berserker' | 'sniper';

export interface EnemyUnit {
  id: string;
  kind: EnemyType;
  customName?: string;
  planet: PlanetConfig;
  mesh: THREE.Group;
  hpBarFill: THREE.Mesh;
  hpBarGroup: THREE.Group;
  position: THREE.Vector3;
  anchorCenter: THREE.Vector3;
  hp: number;
  maxHp: number;
  damage: number;
  alive: boolean;
  fireCooldown: number;
  patrolAngle: number;
  hitFlash: number;
  limbs: THREE.Object3D[];
  aiState: 'idle' | 'chase' | 'flank' | 'strafe' | 'charge' | 'retreat' | 'slamCharge';
  strafeDir: number;
  dodgeCd: number;
  meleeRange: number;
  meleeCd: number;
  leapTimer: number;
  slamTimer: number;
  slamRing?: THREE.Mesh;
  speedMult: number;
  ramCd?: number;
}

export interface EnemyCamp {
  id: string;
  name: string;
  center: THREE.Vector3;
  coreMesh: THREE.Mesh;
  coreRing: THREE.Mesh;
  coreHp: number;
  coreMaxHp: number;
  wave: number;
  maxWaves: number;
  cleared: boolean;
  enemies: EnemyUnit[];
  group: THREE.Group;
}

interface Projectile {
  mesh: THREE.Mesh;
  pos: THREE.Vector3;
  prevPos: THREE.Vector3;
  vel: THREE.Vector3;
  fromPlayer: boolean;
  life: number;
  damage: number;
  explosive: boolean;
  piercing: boolean;
  planet: PlanetConfig;
  hitIds: Set<string>;
}

interface ExplosionParticle {
  mesh: THREE.Mesh;
  vel: THREE.Vector3;
  up: THREE.Vector3;
  life: number;
  maxLife: number;
}

interface LootOrb {
  mesh: THREE.Mesh;
  pos: THREE.Vector3;
  vel: THREE.Vector3;
  planet: PlanetConfig;
  value: number;
  life: number;
}

export interface CombatEvents {
  playerHit: number;
  enemyKilled: boolean;
  shardsCollected: number;
  campCleared: string | null;
  waveBanner: string | null;
  explosion: boolean;
  killCount: number;
  defeatedHiddenBossIds: string[];
}

export class CampsAndCombatSystem {
  public readonly group = new THREE.Group();
  public readonly camps: EnemyCamp[] = [];
  public readonly dynamicEnemies: EnemyUnit[] = [];

  private projectiles: Projectile[] = [];
  private particles: ExplosionParticle[] = [];
  private lootOrbs: LootOrb[] = [];
  private pendingHiddenBossIds: string[] = [];

  private playerBoltGeo = new THREE.SphereGeometry(0.24, 8, 8);
  private missileBoltGeo = new THREE.CylinderGeometry(0.18, 0.28, 1.85, 8);
  private waveArcGeo = new THREE.TorusGeometry(1.4, 0.14, 6, 16, Math.PI * 0.85);
  private enemyBoltGeo = new THREE.SphereGeometry(0.25, 8, 8);
  private enemyBoltMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(2.8, 0.3, 0.3) });
  private sniperBoltMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(3.5, 0.5, 2.5) });
  private sparkGeo = new THREE.DodecahedronGeometry(0.26, 0);
  private orbGeo = new THREE.OctahedronGeometry(0.38, 0);
  private orbMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(2.4, 1.8, 0.3) });

  constructor(physics: PhysicsWorld) {
    this.buildCamps(physics);
  }

  private buildCamps(physics: PhysicsWorld): void {
    const tex = getProceduralTextures();
    const upRef = new THREE.Vector3(0, 1, 0);
    const wallMat = new THREE.MeshPhysicalMaterial({
      color: '#2a3342',
      map: tex.metalAlbedo,
      normalMap: tex.metalNormal,
      roughness: 0.38,
      metalness: 0.72,
      clearcoat: 0.4,
    });
    const trimMat = new THREE.MeshStandardMaterial({
      color: '#ff384c',
      emissive: '#b80c22',
      emissiveIntensity: 1.5,
    });

    for (const site of CAMP_SITES) {
      const campGroup = new THREE.Group();
      const center = getSurfacePosition(site.dir, 0);
      const up = site.dir.clone().normalize();
      const ref = Math.abs(up.y) < 0.9 ? new THREE.Vector3(0, 1, 0) : new THREE.Vector3(1, 0, 0);
      const t1 = new THREE.Vector3().crossVectors(ref, up).normalize();
      const t2 = new THREE.Vector3().crossVectors(up, t1).normalize();

      const pedestalGroup = new THREE.Group();
      pedestalGroup.position.copy(center);
      pedestalGroup.quaternion.setFromUnitVectors(upRef, up);

      const base = new THREE.Mesh(new THREE.CylinderGeometry(2.8, 3.6, 1.2, 12), wallMat);
      base.position.y = 0.6;
      base.castShadow = true;
      base.receiveShadow = true;
      pedestalGroup.add(base);
      physics.addCollider(center, 3.0, 'wall', 5.0);

      const coreMesh = new THREE.Mesh(
        new THREE.OctahedronGeometry(1.45, 1),
        new THREE.MeshStandardMaterial({
          color: '#ff4757',
          emissive: '#ff1f38',
          emissiveIntensity: 2.2,
          roughness: 0.2,
          metalness: 0.5,
        })
      );
      coreMesh.position.y = 3.5;
      coreMesh.castShadow = true;
      pedestalGroup.add(coreMesh);

      const coreRing = new THREE.Mesh(new THREE.TorusGeometry(2.25, 0.16, 10, 28), trimMat);
      coreRing.position.y = 3.5;
      pedestalGroup.add(coreRing);

      campGroup.add(pedestalGroup);

      for (let i = 0; i < 6; i++) {
        const ang = (i / 6) * Math.PI * 2;
        const offsetDir = up
          .clone()
          .addScaledVector(t1, Math.cos(ang) * 0.068)
          .addScaledVector(t2, Math.sin(ang) * 0.068)
          .normalize();
        const pos = getSurfacePosition(offsetDir, 0);
        const struct = new THREE.Group();
        struct.position.copy(pos);
        const radOut = offsetDir.clone();
        const tang = new THREE.Vector3().crossVectors(up, radOut).normalize();
        const fDir = new THREE.Vector3().crossVectors(radOut, tang).normalize();
        struct.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(tang, radOut, fDir));

        if (i % 2 === 0) {
          const tower = new THREE.Mesh(new THREE.CylinderGeometry(1.0, 1.45, 6.2, 8), wallMat);
          tower.position.y = 3.1;
          tower.castShadow = true;
          tower.receiveShadow = true;
          struct.add(tower);

          const beacon = new THREE.Mesh(new THREE.CylinderGeometry(1.15, 1.15, 0.4, 8), trimMat);
          beacon.position.y = 5.9;
          struct.add(beacon);
          physics.addCollider(pos, 1.5, 'wall', 6.5);
        } else {
          const wall = new THREE.Mesh(new THREE.BoxGeometry(5.2, 2.6, 1.4), wallMat);
          wall.position.y = 1.3;
          wall.castShadow = true;
          wall.receiveShadow = true;
          struct.add(wall);
          physics.addCollider(pos, 2.4, 'wall', 3.0);
        }
        campGroup.add(struct);
      }

      this.group.add(campGroup);
      this.camps.push({
        id: site.id,
        name: site.name,
        center,
        coreMesh,
        coreRing,
        coreHp: 220,
        coreMaxHp: 220,
        wave: 0,
        maxWaves: 3,
        cleared: false,
        enemies: [],
        group: campGroup,
      });
    }
  }

  public spawnEnemy(
    kind: EnemyType,
    center: THREE.Vector3,
    angleOffset: number,
    radius = 8.0,
    targetList?: EnemyUnit[],
    hpMult = 1.0,
    dmgMult = 1.0,
    spdMult = 1.0,
    planet: PlanetConfig = PLANETS[0],
    customName?: string,
    overrideId?: string
  ): EnemyUnit {
    const up = center.clone().sub(planet.center).normalize();
    const ref = Math.abs(up.y) < 0.9 ? new THREE.Vector3(0, 1, 0) : new THREE.Vector3(1, 0, 0);
    const t1 = new THREE.Vector3().crossVectors(ref, up).normalize();
    const t2 = new THREE.Vector3().crossVectors(up, t1).normalize();

    const dir = up
      .clone()
      .addScaledVector(t1, Math.cos(angleOffset) * (radius / planet.radius))
      .addScaledVector(t2, Math.sin(angleOffset) * (radius / planet.radius))
      .normalize();
    const hoverY = kind === 'drone' ? 2.4 : kind === 'scout' ? 1.8 : kind === 'sniper' ? 3.0 : 0.0;
    const pos = getPlanetSurfacePosition(planet, dir, hoverY);

    const { mesh, hpBarFill, hpBarGroup, limbs, slamRing } = this.buildSculptedEnemyModel(kind);
    mesh.position.copy(pos);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    this.group.add(mesh);

    const baseHp: Record<EnemyType, number> = { drone: 95, mech: 185, boss: 540, scout: 70, berserker: 250, sniper: 115 };
    const baseDmg: Record<EnemyType, number> = { drone: 9, mech: 14, boss: 22, scout: 7, berserker: 26, sniper: 18 };
    const maxHp = Math.round(baseHp[kind] * hpMult);
    const damage = Math.round(baseDmg[kind] * dmgMult);

    const unit: EnemyUnit = {
      id: overrideId ?? `${kind}-${Math.random().toString(36).slice(2, 8)}`,
      kind,
      customName,
      planet,
      mesh,
      hpBarFill,
      hpBarGroup,
      position: pos,
      anchorCenter: center.clone(),
      hp: maxHp,
      maxHp,
      damage,
      alive: true,
      fireCooldown: 0.9 + Math.random() * 0.8,
      patrolAngle: angleOffset,
      hitFlash: 0,
      limbs,
      aiState: kind === 'berserker' ? 'charge' : kind === 'scout' ? 'flank' : kind === 'sniper' ? 'retreat' : 'chase',
      strafeDir: Math.random() > 0.5 ? 1 : -1,
      dodgeCd: 2 + Math.random() * 3,
      meleeRange: kind === 'berserker' ? 4.5 : kind === 'boss' ? 8.5 : 2.5,
      meleeCd: 0,
      leapTimer: 0,
      slamTimer: kind === 'boss' ? 4.0 : 0,
      slamRing,
      speedMult: spdMult,
    };

    if (targetList) targetList.push(unit);
    else this.dynamicEnemies.push(unit);
    return unit;
  }

  public spawnEndlessWave(
    center: THREE.Vector3,
    mix: { drones: number; mechs: number; bosses: number; scouts: number; berserkers: number; snipers: number },
    hpMult: number,
    dmgMult: number,
    spdMult: number,
    planet: PlanetConfig = PLANETS[0]
  ): EnemyUnit[] {
    const spawned: EnemyUnit[] = [];
    let angleOff = Math.random() * Math.PI * 2;
    const spawnType = (kind: EnemyType, count: number) => {
      for (let i = 0; i < count; i++) {
        spawned.push(this.spawnEnemy(kind, center, angleOff, 14 + Math.random() * 8, undefined, hpMult, dmgMult, spdMult, planet));
        angleOff += 0.75 + Math.random() * 0.5;
      }
    };
    spawnType('drone', mix.drones);
    spawnType('mech', mix.mechs);
    spawnType('boss', mix.bosses);
    spawnType('scout', mix.scouts);
    spawnType('berserker', mix.berserkers);
    spawnType('sniper', mix.snipers);
    return spawned;
  }

  public spawnHiddenBoss(
    center: THREE.Vector3,
    hpMult: number,
    dmgMult: number,
    planet: PlanetConfig,
    name: string,
    id: string
  ): EnemyUnit {
    return this.spawnEnemy('boss', center, 0, 10, undefined, hpMult * 3.4, dmgMult * 2.2, 1.15, planet, name, `hidden-boss:${id}`);
  }

  private buildSculptedEnemyModel(kind: EnemyType): {
    mesh: THREE.Group;
    hpBarFill: THREE.Mesh;
    hpBarGroup: THREE.Group;
    limbs: THREE.Object3D[];
    slamRing?: THREE.Mesh;
  } {
    const g = new THREE.Group();
    const limbs: THREE.Object3D[] = [];
    const tex = getProceduralTextures();

    const colorMap: Record<EnemyType, string> = {
      drone: '#262f3e', mech: '#262f3e', boss: '#24152b',
      scout: '#1a3a2e', berserker: '#3a1515', sniper: '#1a2a3e',
    };
    const glowColorMap: Record<EnemyType, string> = {
      drone: '#ff384c', mech: '#ff384c', boss: '#ff2499',
      scout: '#44ff88', berserker: '#ff6622', sniper: '#8844ff',
    };

    const armorMat = new THREE.MeshPhysicalMaterial({
      color: colorMap[kind],
      map: tex.metalAlbedo,
      normalMap: tex.metalNormal,
      roughness: 0.28,
      metalness: 0.78,
      clearcoat: 0.65,
    });
    const glowMat = new THREE.MeshStandardMaterial({
      color: glowColorMap[kind],
      emissive: glowColorMap[kind],
      emissiveIntensity: 2.0,
    });

    let slamRing: THREE.Mesh | undefined;

    if (kind === 'drone' || kind === 'scout') {
      const cowl = new THREE.Mesh(new THREE.SphereGeometry(kind === 'scout' ? 0.48 : 0.62, 16, 12), armorMat);
      cowl.scale.set(1.3, 0.55, 1.5);
      cowl.castShadow = true;
      g.add(cowl);

      const visor = new THREE.Mesh(new THREE.BoxGeometry(0.65, 0.14, 0.28), glowMat);
      visor.position.set(0, 0.04, -0.78);
      g.add(visor);

      for (const sx of [-1.05, 1.05]) {
        const pod = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.36, 0.32, 12), armorMat);
        pod.position.set(sx, 0.14, 0.1);
        pod.castShadow = true;
        g.add(pod);

        const ring = new THREE.Mesh(new THREE.TorusGeometry(0.32, 0.06, 8, 16), glowMat);
        ring.rotation.x = Math.PI / 2;
        ring.position.set(sx, 0.14, 0.1);
        g.add(ring);
        limbs.push(pod);
      }

      if (kind === 'scout') {
        for (const sx of [-0.6, 0.6]) {
          const fin = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.5, 0.35), armorMat);
          fin.position.set(sx, 0.2, 0.55);
          fin.rotation.z = sx > 0 ? -0.4 : 0.4;
          g.add(fin);
        }
      }
    } else if (kind === 'sniper') {
      const platform = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 1.1, 0.4, 10), armorMat);
      platform.position.y = 0.2;
      platform.castShadow = true;
      g.add(platform);

      const turretBody = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.9), armorMat);
      turretBody.position.set(0, 0.7, 0);
      turretBody.castShadow = true;
      g.add(turretBody);
      limbs.push(turretBody);

      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 1.6, 8), armorMat);
      barrel.rotation.x = Math.PI / 2;
      barrel.position.set(0, 0.7, -0.95);
      g.add(barrel);

      const scope = new THREE.Mesh(new THREE.SphereGeometry(0.14, 10, 10), glowMat);
      scope.position.set(0, 0.95, -0.3);
      g.add(scope);

      const hoverRing = new THREE.Mesh(new THREE.TorusGeometry(0.9, 0.06, 8, 20), glowMat);
      hoverRing.rotation.x = Math.PI / 2;
      hoverRing.position.y = 0;
      g.add(hoverRing);
    } else {
      const s = kind === 'boss' ? 1.75 : kind === 'berserker' ? 1.3 : 1.08;

      for (const lx of [-0.46 * s, 0.46 * s]) {
        const legPivot = new THREE.Group();
        legPivot.position.set(lx, 1.15 * s, 0);

        const thigh = new THREE.Mesh(new THREE.BoxGeometry(0.34 * s, 0.72 * s, 0.42 * s), armorMat);
        thigh.position.y = -0.28 * s;
        thigh.rotation.x = 0.25;
        thigh.castShadow = true;
        legPivot.add(thigh);

        const shin = new THREE.Mesh(new THREE.BoxGeometry(0.3 * s, 0.75 * s, 0.38 * s), armorMat);
        shin.position.set(0, -0.78 * s, -0.1 * s);
        shin.rotation.x = -0.22;
        shin.castShadow = true;
        legPivot.add(shin);

        const foot = new THREE.Mesh(new THREE.BoxGeometry(0.42 * s, 0.2 * s, 0.62 * s), armorMat);
        foot.position.set(0, -1.08 * s, -0.1 * s);
        legPivot.add(foot);

        g.add(legPivot);
        limbs.push(legPivot);
      }

      const pelvis = new THREE.Mesh(new THREE.BoxGeometry(0.98 * s, 0.32 * s, 0.62 * s), armorMat);
      pelvis.position.y = 1.15 * s;
      pelvis.castShadow = true;
      g.add(pelvis);

      const waist = new THREE.Mesh(new THREE.CylinderGeometry(0.32 * s, 0.36 * s, 0.35 * s, 10), armorMat);
      waist.position.y = 1.35 * s;
      g.add(waist);

      const torsoShape = new THREE.Shape();
      torsoShape.moveTo(-0.55 * s, -0.45 * s);
      torsoShape.lineTo(-0.75 * s, 0.25 * s);
      torsoShape.lineTo(0, 0.55 * s);
      torsoShape.lineTo(0.75 * s, 0.25 * s);
      torsoShape.lineTo(0.55 * s, -0.45 * s);
      torsoShape.closePath();
      const torsoGeo = new THREE.ExtrudeGeometry(torsoShape, {
        depth: 0.8 * s,
        bevelEnabled: true,
        bevelThickness: 0.1 * s,
        bevelSize: 0.08 * s,
        bevelSegments: 2,
      });
      torsoGeo.center();
      const torso = new THREE.Mesh(torsoGeo, armorMat);
      torso.position.y = 1.88 * s;
      torso.castShadow = true;
      g.add(torso);

      const reactor = new THREE.Mesh(new THREE.CylinderGeometry(0.24 * s, 0.24 * s, 0.18 * s, 12), glowMat);
      reactor.rotation.x = Math.PI / 2;
      reactor.position.set(0, 1.88 * s, -0.48 * s);
      g.add(reactor);

      const headShell = new THREE.Mesh(new THREE.BoxGeometry(0.56 * s, 0.4 * s, 0.52 * s), armorMat);
      headShell.position.set(0, 2.55 * s, -0.05 * s);
      headShell.castShadow = true;
      g.add(headShell);

      const visor = new THREE.Mesh(new THREE.BoxGeometry(0.52 * s, 0.14 * s, 0.12 * s), glowMat);
      visor.position.set(0, 2.56 * s, -0.3 * s);
      g.add(visor);

      for (const ax of [-0.92 * s, 0.92 * s]) {
        const shoulder = new THREE.Mesh(new THREE.BoxGeometry(0.42 * s, 0.46 * s, 0.95 * s), armorMat);
        shoulder.position.set(ax, 2.15 * s, -0.15 * s);
        shoulder.castShadow = true;
        g.add(shoulder);

        const muzzleGlow = new THREE.Mesh(new THREE.CylinderGeometry(0.12 * s, 0.12 * s, 0.18 * s, 10), glowMat);
        muzzleGlow.rotation.x = Math.PI / 2;
        muzzleGlow.position.set(ax, 2.15 * s, -0.66 * s);
        g.add(muzzleGlow);
      }

      if (kind === 'boss') {
        const halo = new THREE.Mesh(new THREE.TorusGeometry(1.55 * s, 0.08 * s, 8, 32), glowMat);
        halo.position.set(0, 2.1 * s, 0.45 * s);
        g.add(halo);

        // Elden Ring Ground Shockwave Telegraph Ring!
        slamRing = new THREE.Mesh(
          new THREE.RingGeometry(1.0, 9.5, 36),
          new THREE.MeshBasicMaterial({
            color: '#ff2244',
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.48,
            blending: THREE.AdditiveBlending,
          })
        );
        slamRing.rotation.x = Math.PI / 2;
        slamRing.position.y = 0.25;
        slamRing.visible = false;
        g.add(slamRing);
      }

      if (kind === 'berserker') {
        for (const bx of [-0.92 * s, 0.92 * s]) {
          const blade = new THREE.Mesh(new THREE.BoxGeometry(0.06 * s, 0.1 * s, 0.8 * s), glowMat);
          blade.position.set(bx, 1.6 * s, -0.9 * s);
          g.add(blade);
        }
      }
    }

    const hpBarGroup = new THREE.Group();
    const barY = kind === 'boss' ? 5.1 : kind === 'mech' || kind === 'berserker' ? 3.3 : kind === 'sniper' ? 2.0 : 1.7;
    hpBarGroup.position.set(0, barY, 0);
    const barW = kind === 'boss' ? 3.2 : 1.6;
    const bg = new THREE.Mesh(
      new THREE.PlaneGeometry(barW, 0.18),
      new THREE.MeshBasicMaterial({ color: '#11161f', side: THREE.DoubleSide })
    );
    hpBarGroup.add(bg);

    const hpBarFill = new THREE.Mesh(
      new THREE.PlaneGeometry(barW - 0.06, 0.12),
      new THREE.MeshBasicMaterial({ color: kind === 'boss' ? '#ff33aa' : glowColorMap[kind] || '#ff4757', side: THREE.DoubleSide })
    );
    hpBarFill.position.z = 0.01;
    hpBarGroup.add(hpBarFill);
    g.add(hpBarGroup);

    return { mesh: g, hpBarFill, hpBarGroup, limbs, slamRing };
  }

  public firePlayerBolt(
    origin: THREE.Vector3,
    dir: THREE.Vector3,
    damage = 28,
    colorHex = '#4de8ff',
    explosive = false,
    speed = 145,
    waveProjectile = false,
    planet: PlanetConfig = PLANETS[0]
  ): void {
    const mat = new THREE.MeshBasicMaterial({ color: new THREE.Color(colorHex).multiplyScalar(2.1) });
    const mesh = new THREE.Mesh(
      waveProjectile ? this.waveArcGeo : explosive ? this.missileBoltGeo : this.playerBoltGeo,
      mat
    );
    if (waveProjectile || explosive) {
      mesh.lookAt(origin.clone().add(dir));
      mesh.rotateX(Math.PI / 2);
      if (explosive) mesh.scale.setScalar(1.35);
    }
    mesh.position.copy(origin);
    this.group.add(mesh);
    this.projectiles.push({
      mesh,
      pos: origin.clone(),
      prevPos: origin.clone(),
      vel: dir.clone().normalize().multiplyScalar(speed),
      fromPlayer: true,
      life: 2.0,
      damage,
      explosive,
      piercing: waveProjectile,
      planet,
      hitIds: new Set<string>(),
    });
  }

  public performMeleeSlash(
    playerPos: THREE.Vector3,
    forwardDir: THREE.Vector3,
    range: number,
    damage: number,
    colorHex: string,
    launchWave: boolean,
    planet: PlanetConfig = PLANETS[0],
    explosiveSlam = false,
    knockback = 6
  ): { hits: number; kills: number; deflected: number; campCleared: string | null } {
    let hits = 0;
    let kills = 0;
    let deflected = 0;
    let campCleared: string | null = null;
    const up = playerPos.clone().sub(planet.center).normalize();
    const strikeCenter = playerPos.clone().addScaledVector(up, 1.1).addScaledVector(forwardDir, 1.4);

    if (explosiveSlam) {
      kills += this.triggerNovaBlast(strikeCenter, range + 3.5, damage * 0.8);
    }

    const allUnits = [...this.dynamicEnemies, ...this.camps.flatMap((c) => c.enemies)];
    for (const enemy of allUnits) {
      if (!enemy.alive) continue;
      const dist = enemy.position.distanceTo(strikeCenter);
      if (dist <= range) {
        enemy.hp -= damage;
        enemy.hitFlash = 0.15;
        if (knockback > 0 && enemy.kind !== 'boss') {
          const kbDir = enemy.position.clone().sub(playerPos).normalize();
          kbDir.addScaledVector(up, -kbDir.dot(up));
          if (kbDir.lengthSq() > 0.001) enemy.position.addScaledVector(kbDir.normalize(), knockback * 0.25);
        }
        this.spawnExplosion(enemy.position.clone().addScaledVector(up, 1.1), new THREE.Color(colorHex).getHex(), 12, enemy.planet);
        hits++;
        if (enemy.hp <= 0) {
          this.killEnemy(enemy);
          kills++;
        }
      }
    }

    for (const camp of this.camps) {
      if (camp.cleared) continue;
      const coreWorld = camp.center.clone().addScaledVector(camp.center.clone().normalize(), 3.5);
      if (coreWorld.distanceTo(strikeCenter) <= range + 1.5) {
        camp.coreHp -= damage;
        this.spawnExplosion(coreWorld, 0xffaa44, 12);
        hits++;
        if (camp.coreHp <= 0) {
          camp.cleared = true;
          camp.coreMesh.visible = false;
          camp.coreRing.visible = false;
          this.spawnExplosion(coreWorld, 0xff5522, 34);
          campCleared = camp.name;
        }
      }
    }

    for (const p of this.projectiles) {
      if (!p.fromPlayer && p.pos.distanceTo(strikeCenter) <= range + 1.5) {
        p.fromPlayer = true;
        p.vel.negate().multiplyScalar(2.0);
        p.damage = damage;
        p.life = 1.6;
        p.mesh.material = new THREE.MeshBasicMaterial({ color: new THREE.Color(colorHex).multiplyScalar(1.9) });
        this.spawnExplosion(p.pos, 0x5effea, 8);
        deflected++;
      }
    }

    if (launchWave) {
      this.firePlayerBolt(strikeCenter, forwardDir, damage * 0.85, colorHex, false, 110, true, planet);
    }

    return { hits, kills, deflected, campCleared };
  }

  public triggerNovaBlast(center: THREE.Vector3, radius: number, damage: number): number {
    let kills = 0;
    this.spawnExplosion(center, 0x55e8ff, 28);
    const allUnits = [...this.dynamicEnemies, ...this.camps.flatMap((c) => c.enemies)];
    for (const enemy of allUnits) {
      if (!enemy.alive) continue;
      if (enemy.position.distanceTo(center) <= radius) {
        enemy.hp -= damage;
        enemy.hitFlash = 0.15;
        if (enemy.hp <= 0) {
          this.killEnemy(enemy);
          kills++;
        }
      }
    }
    return kills;
  }

  private killEnemy(enemy: EnemyUnit): void {
    enemy.alive = false;
    this.group.remove(enemy.mesh);
    if (enemy.id.startsWith('hidden-boss:')) {
      this.pendingHiddenBossIds.push(enemy.id.slice(12));
    }
    this.spawnExplosion(enemy.position, enemy.kind === 'boss' ? 0xff44cc : 0xff8833, enemy.kind === 'boss' ? 35 : 18, enemy.planet);

    const orbCount = enemy.kind === 'boss' ? 10 : enemy.kind === 'mech' || enemy.kind === 'berserker' ? 4 : 3;
    const up = enemy.position.clone().sub(enemy.planet.center).normalize();
    for (let i = 0; i < orbCount; i++) {
      const m = new THREE.Mesh(this.orbGeo, this.orbMat);
      m.position.copy(enemy.position).addScaledVector(up, 1.0);
      this.group.add(m);
      const randVel = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5)
        .normalize()
        .multiplyScalar(7)
        .addScaledVector(up, 8);
      this.lootOrbs.push({ mesh: m, pos: m.position.clone(), vel: randVel, planet: enemy.planet, value: 14, life: 30 });
    }
  }

  public getAliveEnemyCount(planetId?: string): number {
    return this.dynamicEnemies.filter((e) => e.alive && (!planetId || e.planet.id === planetId) && !e.id.startsWith('hidden-boss:')).length;
  }

  public getHiddenBossUnits(): EnemyUnit[] {
    return this.dynamicEnemies.filter((e) => e.alive && e.id.startsWith('hidden-boss:'));
  }

  public getActiveBoss(): EnemyUnit | null {
    const allUnits = [...this.dynamicEnemies, ...this.camps.flatMap((c) => c.enemies)];
    return allUnits.find((e) => e.alive && e.kind === 'boss') ?? null;
  }

  private fireEnemyBolt(origin: THREE.Vector3, target: THREE.Vector3, damage: number, planet: PlanetConfig, isSniper = false): void {
    const dir = target.clone().sub(origin).normalize();
    const mat = isSniper ? this.sniperBoltMat : this.enemyBoltMat;
    const mesh = new THREE.Mesh(this.enemyBoltGeo, mat);
    if (isSniper) mesh.scale.setScalar(1.4);
    mesh.position.copy(origin);
    this.group.add(mesh);
    this.projectiles.push({
      mesh,
      pos: origin.clone(),
      prevPos: origin.clone(),
      vel: dir.multiplyScalar(isSniper ? 88 : 60),
      fromPlayer: false,
      life: 2.3,
      damage,
      explosive: false,
      piercing: false,
      planet,
      hitIds: new Set<string>(),
    });
  }

  private spawnExplosion(pos: THREE.Vector3, colorHex: number, count = 14, planet: PlanetConfig = PLANETS[0]): void {
    const up = pos.clone().sub(planet.center).normalize();
    for (let i = 0; i < count; i++) {
      const mat = new THREE.MeshBasicMaterial({ color: colorHex, transparent: true, opacity: 1 });
      const mesh = new THREE.Mesh(this.sparkGeo, mat);
      mesh.position.copy(pos);
      this.group.add(mesh);

      const randVel = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5)
        .normalize()
        .multiplyScalar(6 + Math.random() * 15)
        .addScaledVector(up, 5);

      this.particles.push({ mesh, vel: randVel, up: up.clone(), life: 0.55 + Math.random() * 0.35, maxLife: 0.9 });
    }
  }

  public update(
    dt: number,
    time: number,
    camera: THREE.Camera,
    playerOrRoverPos: THREE.Vector3,
    roverPos: THREE.Vector3,
    roverSpeed: number,
    isDriving: boolean,
    onPlayerBoltHitPos?: (pos: THREE.Vector3, prevPos: THREE.Vector3, dmg: number, piercing: boolean) => boolean,
    playerHasIFrames = false
  ): CombatEvents {
    const events: CombatEvents = {
      playerHit: 0,
      enemyKilled: false,
      shardsCollected: 0,
      campCleared: null,
      waveBanner: null,
      explosion: false,
      killCount: 0,
      defeatedHiddenBossIds: this.pendingHiddenBossIds.splice(0, this.pendingHiddenBossIds.length),
    };

    for (const camp of this.camps) {
      if (!camp.cleared) {
        camp.coreMesh.rotation.y = time * 1.6;
        camp.coreRing.rotation.x = time * 2.1;
        camp.coreRing.rotation.y = -time * 1.2;

        const dist = camp.center.distanceTo(playerOrRoverPos);
        const aliveInCamp = camp.enemies.filter((e) => e.alive).length;

        if (camp.wave === 0 && dist < 48) {
          camp.wave = 1;
          events.waveBanner = `${camp.name}: WAVE 1/3 — Hunter Drones & Scouts Incoming!`;
          for (let i = 0; i < 3; i++) this.spawnEnemy('drone', camp.center, i * 2.1, 8.5, camp.enemies);
          this.spawnEnemy('scout', camp.center, 5.0, 10, camp.enemies);
        } else if (camp.wave === 1 && aliveInCamp === 0) {
          camp.wave = 2;
          events.waveBanner = `${camp.name}: WAVE 2/3 — Mechs & Berserker Deployed!`;
          for (let i = 0; i < 2; i++) this.spawnEnemy('mech', camp.center, i * 2.1 + 0.5, 9.5, camp.enemies);
          this.spawnEnemy('berserker', camp.center, 4.5, 8.5, camp.enemies);
          this.spawnEnemy('scout', camp.center, 6.0, 11, camp.enemies);
        } else if (camp.wave === 2 && aliveInCamp === 0) {
          camp.wave = 3;
          events.waveBanner = `${camp.name}: BOSS WAVE 3/3 — Colossus Titan & Sniper!`;
          this.spawnEnemy('boss', camp.center, 0, 7.0, camp.enemies);
          this.spawnEnemy('sniper', camp.center, 2.2, 12.0, camp.enemies);
          this.spawnEnemy('drone', camp.center, 4.4, 10.0, camp.enemies);
        }
      }
    }

    const allUnits = [...this.dynamicEnemies, ...this.camps.flatMap((c) => c.enemies)];
    for (const enemy of allUnits) {
      if (!enemy.alive) continue;

      const pCenter = enemy.planet.center;
      const distToTarget = enemy.position.distanceTo(playerOrRoverPos);
      const eLocal = enemy.position.clone().sub(pCenter);
      const eUp = eLocal.clone().normalize();
      const aggro = distToTarget < 85;

      if (aggro) {
        const enraged = enemy.kind === 'boss' && enemy.hp < enemy.maxHp * 0.5;
        const baseSpd = enemy.speedMult * (enraged ? 1.28 : 1.0);
        const toTarget = playerOrRoverPos.clone().sub(enemy.position);
        toTarget.addScaledVector(eUp, -toTarget.dot(eUp));
        if (toTarget.lengthSq() > 0.01) toTarget.normalize();
        const strafeVec = new THREE.Vector3().crossVectors(toTarget, eUp).normalize().multiplyScalar(enemy.strafeDir);

        enemy.dodgeCd -= dt;
        if (enemy.dodgeCd <= 0) {
          enemy.strafeDir *= -1;
          enemy.dodgeCd = 1.4 + Math.random() * 2.2;
        }

        // Boss Elden-Ring Telegraphed Shockwave Slam Attack!
        if (enemy.kind === 'boss') {
          enemy.slamTimer -= dt;
          if (enemy.aiState !== 'slamCharge' && enemy.slamTimer <= 0 && distToTarget < 18) {
            enemy.aiState = 'slamCharge';
            enemy.leapTimer = 1.1; // 1.1s red telegraph warning window!
            if (enemy.slamRing) {
              enemy.slamRing.visible = true;
              enemy.slamRing.scale.setScalar(0.2);
            }
          }
          if (enemy.aiState === 'slamCharge') {
            enemy.leapTimer -= dt;
            if (enemy.slamRing) {
              const progT = 1 - Math.max(0, enemy.leapTimer) / 1.1;
              enemy.slamRing.scale.setScalar(0.2 + progT * 0.9);
            }
            if (enemy.leapTimer <= 0) {
              if (enemy.slamRing) enemy.slamRing.visible = false;
              enemy.aiState = 'chase';
              enemy.slamTimer = enraged ? 3.5 : 5.5;
              this.spawnExplosion(enemy.position.clone().addScaledVector(eUp, 1.5), 0xff2255, 28, enemy.planet);
              events.explosion = true;
              if (distToTarget < 11.5 && !playerHasIFrames) {
                events.playerHit += enemy.damage * 1.6;
              }
            }
          }
        }

        if (enemy.kind === 'drone') {
          enemy.patrolAngle += dt * 1.1;
          const desiredDir = playerOrRoverPos
            .clone()
            .sub(pCenter)
            .normalize()
            .addScaledVector(new THREE.Vector3(1, 0, 0).cross(eUp).normalize(), Math.cos(enemy.patrolAngle) * 0.08)
            .normalize();
          const desiredPos = getPlanetSurfacePosition(enemy.planet, desiredDir, 2.5 + Math.sin(time * 3 + enemy.patrolAngle) * 0.45);
          enemy.position.lerp(desiredPos, Math.min(1, dt * 3.0 * baseSpd));
        } else if (enemy.kind === 'scout') {
          enemy.patrolAngle += dt * 1.6 * baseSpd;
          const desiredDist = 18 + Math.sin(enemy.patrolAngle * 0.7) * 6;
          if (distToTarget < desiredDist) enemy.position.addScaledVector(toTarget, -6 * dt * baseSpd);
          else if (distToTarget > desiredDist + 5) enemy.position.addScaledVector(toTarget, 10 * dt * baseSpd);
          enemy.position.addScaledVector(strafeVec, 9 * dt * baseSpd);
          const dir = enemy.position.clone().sub(pCenter).normalize();
          enemy.position.copy(getPlanetSurfacePosition(enemy.planet, dir, 1.8));
        } else if (enemy.kind === 'sniper') {
          const preferDist = 34;
          if (distToTarget < preferDist - 5) enemy.position.addScaledVector(toTarget, -5 * dt * baseSpd);
          else if (distToTarget > preferDist + 10) enemy.position.addScaledVector(toTarget, 5 * dt * baseSpd);
          enemy.position.addScaledVector(strafeVec, 3 * dt * baseSpd);
          const dir = enemy.position.clone().sub(pCenter).normalize();
          enemy.position.copy(getPlanetSurfacePosition(enemy.planet, dir, 3.0));
        } else if (enemy.kind === 'berserker') {
          enemy.leapTimer -= dt;
          if (distToTarget > enemy.meleeRange + 1.5) {
            enemy.position.addScaledVector(toTarget, 13 * baseSpd * dt);
            enemy.position.addScaledVector(strafeVec, 2.5 * dt * baseSpd);
          }
          if (distToTarget <= enemy.meleeRange && enemy.meleeCd <= 0) {
            enemy.meleeCd = 1.0;
            if (!playerHasIFrames) {
              events.playerHit += enemy.damage;
              this.spawnExplosion(playerOrRoverPos.clone().addScaledVector(eUp, 1), 0xff6622, 10, enemy.planet);
            }
          }
          enemy.meleeCd = Math.max(0, enemy.meleeCd - dt);
          const dir = enemy.position.clone().sub(pCenter).normalize();
          enemy.position.copy(getPlanetSurfacePosition(enemy.planet, dir, 0));
          const swing = Math.sin(time * 8 + enemy.patrolAngle) * 0.55;
          if (enemy.limbs.length >= 2) {
            enemy.limbs[0].rotation.x = swing;
            enemy.limbs[1].rotation.x = -swing;
          }
        } else if (enemy.aiState !== 'slamCharge') {
          if (distToTarget > 11) {
            const spd = (enemy.kind === 'boss' ? 8.0 : 8.5) * baseSpd;
            enemy.position.addScaledVector(toTarget, spd * dt);
          }
          if (distToTarget < 25 && distToTarget > 6) {
            enemy.position.addScaledVector(strafeVec, 4.5 * dt * baseSpd);
          }
          const dir = enemy.position.clone().sub(pCenter).normalize();
          enemy.position.copy(getPlanetSurfacePosition(enemy.planet, dir, 0));
          const swing = Math.sin(time * 8 + enemy.patrolAngle) * 0.45;
          if (enemy.limbs.length >= 2) {
            enemy.limbs[0].rotation.x = swing;
            enemy.limbs[1].rotation.x = -swing;
          }
        }

        const toP = playerOrRoverPos.clone().sub(enemy.position);
        toP.addScaledVector(eUp, -toP.dot(eUp)).normalize();
        if (toP.lengthSq() > 0.001) {
          const right = new THREE.Vector3().crossVectors(toP, eUp).normalize();
          const mat = new THREE.Matrix4().makeBasis(right, eUp, toP.clone().negate());
          enemy.mesh.quaternion.setFromRotationMatrix(mat);
        }

        if (enemy.kind !== 'berserker' && enemy.aiState !== 'slamCharge') {
          enemy.fireCooldown -= dt;
          const fireRange = enemy.kind === 'sniper' ? 75 : 58;
          const fireCdBase =
            enemy.kind === 'boss'
              ? enraged ? 0.55 : 0.75
              : enemy.kind === 'sniper'
              ? 1.7
              : enemy.kind === 'scout'
              ? 0.9
              : 1.2 + Math.random() * 0.4;
          if (enemy.fireCooldown <= 0 && distToTarget < fireRange) {
            enemy.fireCooldown = fireCdBase;
            const shootOrigin = enemy.position.clone().addScaledVector(eUp, enemy.kind === 'boss' ? 2.8 : enemy.kind === 'sniper' ? 1.2 : 1.6);
            this.fireEnemyBolt(
              shootOrigin,
              playerOrRoverPos.clone().addScaledVector(eUp, 1.0),
              enemy.damage,
              enemy.planet,
              enemy.kind === 'sniper'
            );
          }
        }
      }

      const hpRatio = Math.max(0.01, enemy.hp / enemy.maxHp);
      enemy.hpBarFill.scale.x = hpRatio;
      enemy.hpBarGroup.up.copy(eUp);
      enemy.hpBarGroup.lookAt(camera.position);
      enemy.mesh.position.copy(enemy.position);

      if (enemy.ramCd && enemy.ramCd > 0) enemy.ramCd -= dt;
      if (isDriving && Math.abs(roverSpeed) > 14 && enemy.position.distanceTo(roverPos) < 3.4 && (!enemy.ramCd || enemy.ramCd <= 0)) {
        enemy.ramCd = 0.35;
        enemy.hp -= Math.abs(roverSpeed) * 3.8;
        this.spawnExplosion(enemy.position, 0xffaa44, 10, enemy.planet);
        if (enemy.hp <= 0) {
          this.killEnemy(enemy);
          events.enemyKilled = true;
          events.killCount++;
          events.explosion = true;
        }
      }
    }

    const seg = new THREE.Line3();
    const closest = new THREE.Vector3();

    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      p.prevPos.copy(p.pos);
      p.pos.addScaledVector(p.vel, dt);
      p.mesh.position.copy(p.pos);
      let remove = p.life <= 0;
      seg.set(p.prevPos, p.pos);

      const localPos = p.pos.clone().sub(p.planet.center);
      const groundH = Math.max(p.planet.seaLevel, getPlanetTerrainHeight(localPos, p.planet.id));
      if (!remove && localPos.length() < groundH) {
        if (p.fromPlayer && p.explosive) {
          const k = this.triggerNovaBlast(p.pos, 10.5, p.damage);
          if (k > 0) {
            events.enemyKilled = true;
            events.killCount += k;
          }
          events.explosion = true;
        } else {
          this.spawnExplosion(p.pos, p.fromPlayer ? 0x55e8ff : 0xff4433, 5, p.planet);
        }
        if (p.fromPlayer && onPlayerBoltHitPos) onPlayerBoltHitPos(p.pos, p.prevPos, p.damage, p.piercing);
        remove = true;
      }

      if (!remove && p.fromPlayer) {
        for (const enemy of allUnits) {
          if (!enemy.alive || p.hitIds.has(enemy.id)) continue;
          const eUp = enemy.position.clone().sub(enemy.planet.center).normalize();
          const eCenter = enemy.position.clone().addScaledVector(eUp, 1.3);
          const hitR = (enemy.kind === 'boss' ? 3.2 : 2.0) + (p.piercing ? 1.2 : 0);
          seg.closestPointToPoint(eCenter, true, closest);
          if (closest.distanceTo(eCenter) < hitR) {
            p.hitIds.add(enemy.id);
            if (p.explosive) {
              const k = this.triggerNovaBlast(closest, 11.0, p.damage);
              if (k > 0) {
                events.enemyKilled = true;
                events.killCount += k;
              }
              events.explosion = true;
            } else {
              enemy.hp -= p.damage;
              this.spawnExplosion(closest, 0x7beeff, 7, enemy.planet);
              if (enemy.hp <= 0) {
                this.killEnemy(enemy);
                events.enemyKilled = true;
                events.killCount++;
                events.explosion = true;
              }
            }
            if (!p.piercing) remove = true;
            break;
          }
        }

        if (!remove) {
          for (const camp of this.camps) {
            if (camp.cleared || p.hitIds.has(camp.id)) continue;
            const coreWorld = camp.center.clone().addScaledVector(camp.center.clone().normalize(), 3.5);
            seg.closestPointToPoint(coreWorld, true, closest);
            if (closest.distanceTo(coreWorld) < 3.0) {
              p.hitIds.add(camp.id);
              camp.coreHp -= p.damage;
              this.spawnExplosion(closest, 0xffaa44, 8);
              if (!p.piercing) remove = true;
              if (camp.coreHp <= 0) {
                camp.cleared = true;
                camp.coreMesh.visible = false;
                camp.coreRing.visible = false;
                this.spawnExplosion(coreWorld, 0xff5522, 34);
                events.campCleared = camp.name;
                events.explosion = true;
              }
              break;
            }
          }
        }

        if (!remove && onPlayerBoltHitPos) {
          if (onPlayerBoltHitPos(p.pos, p.prevPos, p.damage, p.piercing) && !p.piercing) {
            this.spawnExplosion(p.pos, 0x7beeff, 6, p.planet);
            remove = true;
          }
        }
      } else if (!remove && !p.fromPlayer) {
        if (!playerHasIFrames) {
          const hitRadius = isDriving ? 2.4 : 1.1;
          const up = playerOrRoverPos.clone().sub(p.planet.center).normalize();
          const targetCenter = playerOrRoverPos.clone().addScaledVector(up, 1.0);
          seg.closestPointToPoint(targetCenter, true, closest);
          if (closest.distanceTo(targetCenter) < hitRadius) {
            events.playerHit += p.damage;
            this.spawnExplosion(closest, 0xff3344, 6, p.planet);
            remove = true;
          }
        }
      }

      if (remove) {
        this.group.remove(p.mesh);
        if (p.mesh.material !== this.enemyBoltMat && p.mesh.material !== this.sniperBoltMat) {
          (p.mesh.material as THREE.Material).dispose();
        }
        this.projectiles.splice(i, 1);
      }
    }

    // Prune dead dynamic enemies so Endless mode never leaks memory/iteration!
    for (let i = this.dynamicEnemies.length - 1; i >= 0; i--) {
      if (!this.dynamicEnemies[i].alive) this.dynamicEnemies.splice(i, 1);
    }

    // Flush any hidden bosses slain during projectile/explosion loop
    if (this.pendingHiddenBossIds.length > 0) {
      events.defeatedHiddenBossIds.push(...this.pendingHiddenBossIds.splice(0, this.pendingHiddenBossIds.length));
    }

    for (let i = this.lootOrbs.length - 1; i >= 0; i--) {
      const orb = this.lootOrbs[i];
      orb.life -= dt;
      const dist = orb.pos.distanceTo(playerOrRoverPos);
      if (dist < 22) {
        const pull = playerOrRoverPos.clone().sub(orb.pos).normalize();
        orb.pos.addScaledVector(pull, 32 * dt);
      } else {
        orb.pos.addScaledVector(orb.vel, dt);
        const up = orb.pos.clone().sub(orb.planet.center).normalize();
        orb.vel.addScaledVector(up, -18 * dt);
        const gh = Math.max(orb.planet.seaLevel + 0.5, getPlanetTerrainHeight(up, orb.planet.id) + 0.6);
        if (orb.pos.distanceTo(orb.planet.center) < gh) {
          orb.pos.copy(up).multiplyScalar(gh).add(orb.planet.center);
          orb.vel.multiplyScalar(0.2);
        }
      }
      orb.mesh.position.copy(orb.pos);
      orb.mesh.rotation.y = time * 4;

      if (dist < 3.0 || orb.life <= 0) {
        if (dist < 3.0) events.shardsCollected += orb.value;
        this.group.remove(orb.mesh);
        this.lootOrbs.splice(i, 1);
      }
    }

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const pt = this.particles[i];
      pt.life -= dt;
      pt.mesh.position.addScaledVector(pt.vel, dt);
      pt.vel.multiplyScalar(0.94);
      const mat = pt.mesh.material as THREE.MeshBasicMaterial;
      mat.opacity = Math.max(0, pt.life / pt.maxLife);
      pt.mesh.scale.setScalar(0.4 + (pt.life / pt.maxLife) * 0.9);
      if (pt.life <= 0) {
        this.group.remove(pt.mesh);
        mat.dispose();
        this.particles.splice(i, 1);
      }
    }

    return events;
  }
}
