import { PlanetId } from '../math/spherical';

export interface MissionState {
  stage: number;
  title: string;
  description: string;
  progressText: string;
  spireActivated: boolean;
  endlessWave: number;
  endlessActive: boolean;
  bossAlert: string | null;
  score: number;
}

export interface HiddenBoss {
  id: string;
  name: string;
  triggerWave: number;
  spawned: boolean;
  defeated: boolean;
  planetId: PlanetId;
}

export class MissionManager {
  public stage = 0;
  public polarWave = 0;
  public spireActivated = false;

  // Endless mode (can also trigger early when off-world bosses & waves are cleared!)
  public endlessWave = 0;
  public endlessActive = false;

  // Hidden Elden-Ring Style World Bosses triggered on specific planets & waves!
  public hiddenBosses: HiddenBoss[] = [
    { id: 'shadow-titan', name: 'SHADOW TITAN', triggerWave: 2, spawned: false, defeated: false, planetId: 'aetheria' },
    { id: 'void-wyrm', name: 'AURELIA VOID SERPENT', triggerWave: 4, spawned: false, defeated: false, planetId: 'aurelia' },
    { id: 'infernal-lord', name: 'INFERNAL OVERLORD', triggerWave: 6, spawned: false, defeated: false, planetId: 'pyros' },
    { id: 'frost-colossus', name: 'GLACIES FROST COLOSSUS', triggerWave: 8, spawned: false, defeated: false, planetId: 'glacies' },
    { id: 'apex-predator', name: 'APEX SYNDICATE EMPEROR', triggerWave: 12, spawned: false, defeated: false, planetId: 'aetheria' },
    { id: 'cosmic-devourer', name: 'COSMIC DEVOURER', triggerWave: 20, spawned: false, defeated: false, planetId: 'aurelia' },
  ];

  public update(
    coresCollected: number,
    chestsOpened: number,
    campsCleared: number,
    totalCamps: number,
    cavesCleared: number,
    totalCaves: number,
    offworldCleared: number,
    totalOffworld: number,
    score: number
  ): { state: MissionState; justAdvanced: string | null; spawnBoss: HiddenBoss | null } {
    let justAdvanced: string | null = null;
    let spawnBoss: HiddenBoss | null = null;

    if (this.stage === 0 && (coresCollected >= 1 || chestsOpened >= 1 || cavesCleared >= 1 || offworldCleared >= 1)) {
      this.stage = 1;
      justAdvanced = 'OBJECTIVE COMPLETE: First Contact — Conquer the 4 Syndicate Outposts!';
    } else if (this.stage === 1 && campsCleared >= totalCamps) {
      this.stage = 2;
      justAdvanced = 'OUTPOSTS LIBERATED! Raid a 92m Cave Dungeon & Harvest 4 Cores!';
    } else if (this.stage === 2 && coresCollected >= 4 && cavesCleared >= 1) {
      this.stage = 3;
      justAdvanced = 'CAVERNS CONQUERED! Board the Air Force Jet [G] & Liberate Aurelia, Pyros & Glacies!';
    } else if (this.stage === 3 && offworldCleared >= totalOffworld) {
      this.stage = 4;
      justAdvanced = 'SYSTEM SECURED! Return to Aetheria North Polar Citadel for the Final Siege!';
    } else if (this.stage === 4 && this.polarWave >= 4) {
      this.stage = 5;
      this.spireActivated = true;
      this.endlessActive = true;
      this.endlessWave = 0;
      justAdvanced = '★ ENDLESS ASCENSION UNLOCKED! Infinite Scaling Waves & Hidden Cosmic Bosses! ★';
    }

    if (this.endlessActive) {
      for (const boss of this.hiddenBosses) {
        if (!boss.spawned && !boss.defeated && this.endlessWave >= boss.triggerWave) {
          boss.spawned = true;
          spawnBoss = boss;
          break;
        }
      }
    }

    const state = this.getState(
      coresCollected,
      chestsOpened,
      campsCleared,
      totalCamps,
      cavesCleared,
      totalCaves,
      offworldCleared,
      totalOffworld,
      score
    );
    return { state, justAdvanced, spawnBoss };
  }

  public advanceEndlessWave(): string {
    this.endlessWave++;
    const waveType =
      this.endlessWave % 10 === 0
        ? 'MEGA BOSS WAVE'
        : this.endlessWave % 5 === 0
        ? 'ELITE SIEGE WAVE'
        : `WAVE ${this.endlessWave}`;
    return `★ ENDLESS ${waveType} ★ — Enemy Threat x${(1 + this.endlessWave * 0.15).toFixed(1)}`;
  }

  public getEndlessEnemyMix(): {
    drones: number;
    mechs: number;
    bosses: number;
    scouts: number;
    berserkers: number;
    snipers: number;
  } {
    const w = this.endlessWave;
    if (w % 10 === 0) {
      return { drones: 2, mechs: 3, bosses: 2, scouts: 3, berserkers: 3, snipers: 2 };
    }
    if (w % 5 === 0) {
      return { drones: 3, mechs: 2, bosses: 1, scouts: 3, berserkers: 2, snipers: 2 };
    }
    if (w < 3) {
      return { drones: 3 + w, mechs: Math.max(1, w), bosses: 0, scouts: 1 + w, berserkers: w > 1 ? 1 : 0, snipers: 0 };
    }
    return {
      drones: Math.min(5, 2 + Math.floor(w / 4)),
      mechs: Math.min(4, 1 + Math.floor(w / 3)),
      bosses: Math.floor(w / 8),
      scouts: Math.min(6, 2 + Math.floor(w / 4)),
      berserkers: Math.min(5, 1 + Math.floor(w / 4)),
      snipers: Math.min(4, 1 + Math.floor(w / 5)),
    };
  }

  public getState(
    coresCollected: number,
    chestsOpened: number,
    campsCleared: number,
    totalCamps: number,
    cavesCleared: number,
    totalCaves: number,
    offworldCleared: number,
    totalOffworld: number,
    score: number
  ): MissionState {
    let bossAlert: string | null = null;
    for (const boss of this.hiddenBosses) {
      if (boss.spawned && !boss.defeated) {
        bossAlert = `⚠ HIDDEN BOSS (${boss.planetId.toUpperCase()}): ${boss.name}`;
        break;
      }
    }

    switch (this.stage) {
      case 0:
        return {
          stage: 0,
          title: '1. First Contact & Sky Deployment',
          description: 'Loot a Chest [E], shatter Trees/Crystals, hunt Stalkers, breach a Cave, or fly the Air Force Jet [G]!',
          progressText: `Chests: ${chestsOpened}/15  |  Caves: ${cavesCleared}/${totalCaves}`,
          spireActivated: false,
          endlessWave: 0,
          endlessActive: false,
          bossAlert,
          score,
        };
      case 1:
        return {
          stage: 1,
          title: '2. Outpost Liberation',
          description: 'Smash all 4 Syndicate Outposts across Aetheria! Crash through trees & climb any ridge!',
          progressText: `Outposts: ${campsCleared}/${totalCamps}  |  Score: ${score.toLocaleString()}`,
          spireActivated: false,
          endlessWave: 0,
          endlessActive: false,
          bossAlert,
          score,
        };
      case 2:
        return {
          stage: 2,
          title: '3. Deep 92m Cavern Raid',
          description: 'Breach a 92m Underground Cave, ignite all 3 Pylons & gather 4 Aether Cores.',
          progressText: `Cores: ${coresCollected}/4  |  Caves: ${cavesCleared}/${totalCaves}`,
          spireActivated: false,
          endlessWave: 0,
          endlessActive: false,
          bossAlert,
          score,
        };
      case 3:
        return {
          stage: 3,
          title: '4. Interplanetary Air-Force Strike',
          description: 'Fly the Air Force Jet [G] across space to Aurelia, Pyros & Glacies and destroy their Syndicate Citadels!',
          progressText: `Off-World Citadels: ${offworldCleared}/${totalOffworld}`,
          spireActivated: false,
          endlessWave: 0,
          endlessActive: false,
          bossAlert,
          score,
        };
      case 4:
        return {
          stage: 4,
          title: '5. North Polar Citadel Siege',
          description:
            this.polarWave === 0
              ? 'Land at Aetheria North Polar Citadel to trigger the 3-Wave Final Siege!'
              : `SURVIVE THE SIEGE! Wave ${this.polarWave}/3`,
          progressText: `Siege Wave: ${this.polarWave}/3`,
          spireActivated: false,
          endlessWave: 0,
          endlessActive: false,
          bossAlert,
          score,
        };
      default:
        return {
          stage: 5,
          title: `★ ENDLESS: Wave ${this.endlessWave}`,
          description: `Infinite Escalation! Upgrade infinitely in [TAB] Market — Bosses hunt you across all 4 planets!`,
          progressText: `Score: ${score.toLocaleString()}  |  Wave: ${this.endlessWave}  |  Bosses: ${this.hiddenBosses.filter((b) => b.defeated).length}/${this.hiddenBosses.length}`,
          spireActivated: true,
          endlessWave: this.endlessWave,
          endlessActive: this.endlessActive,
          bossAlert,
          score,
        };
    }
  }
}
