import * as THREE from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { PLANET_RADIUS } from '../math/spherical';

/**
 * Jittered, Planet-Occluded Screen-Space Volumetric God Rays Shader.
 * - Uses interleaved gradient noise jitter to eliminate radial banding.
 * - Rejects out-of-bounds UV steps cleanly instead of clamping border pixels.
 * - Fades smoothly when sun is off-screen or eclipsed behind the planet.
 */
const GodRaysShader = {
  uniforms: {
    tDiffuse: { value: null },
    uSunScreenPos: { value: new THREE.Vector2(0.5, 0.5) },
    uSunVisible: { value: 1.0 },
    uExposure: { value: 0.28 },
    uDecay: { value: 0.945 },
    uDensity: { value: 0.85 },
    uWeight: { value: 0.14 },
  },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform sampler2D tDiffuse;
    uniform vec2 uSunScreenPos;
    uniform float uSunVisible;
    uniform float uExposure;
    uniform float uDecay;
    uniform float uDensity;
    uniform float uWeight;
    varying vec2 vUv;

    const int SAMPLES = 32;

    float ign(vec2 p) {
      return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715))));
    }

    void main() {
      vec4 base = texture2D(tDiffuse, vUv);
      if (uSunVisible <= 0.001) {
        gl_FragColor = base;
        return;
      }

      vec2 deltaTexCoord = (vUv - uSunScreenPos) * (1.0 / float(SAMPLES)) * uDensity;
      float jitter = ign(gl_FragCoord.xy);
      vec2 coord = vUv - deltaTexCoord * jitter;
      float illuminationDecay = 1.0;
      vec3 rays = vec3(0.0);

      for (int i = 0; i < SAMPLES; i++) {
        coord -= deltaTexCoord;
        if (coord.x >= 0.0 && coord.x <= 1.0 && coord.y >= 0.0 && coord.y <= 1.0) {
          vec3 s = texture2D(tDiffuse, coord).rgb;
          float lum = dot(s, vec3(0.299, 0.587, 0.114));
          float mask = smoothstep(0.72, 1.45, lum);
          rays += s * mask * illuminationDecay * uWeight;
        }
        illuminationDecay *= uDecay;
      }

      float distToSun = length(vUv - uSunScreenPos);
      float radialFalloff = exp(-distToSun * 1.35);
      vec3 warmRays = rays * uExposure * uSunVisible * (0.4 + 0.8 * radialFalloff);
      warmRays *= vec3(1.08, 0.94, 0.78);

      gl_FragColor = vec4(base.rgb + warmRays, base.a);
    }
  `,
};

export interface PostFXPipeline {
  composer: EffectComposer;
  resize(width: number, height: number): void;
  render(camera: THREE.Camera, sunWorldPos: THREE.Vector3): void;
}

function isSunOccludedByPlanet(camPos: THREE.Vector3, toSunDir: THREE.Vector3): boolean {
  // Ray-sphere intersection against planet at origin with radius PLANET_RADIUS - 1.5
  const r = PLANET_RADIUS - 1.5;
  const b = camPos.dot(toSunDir);
  if (b > 0) return false; // Sun is in front of planet relative to camera
  const c = camPos.lengthSq() - r * r;
  const disc = b * b - c;
  return disc > 0;
}

export function createPostFX(
  renderer: THREE.WebGLRenderer,
  scene: THREE.Scene,
  camera: THREE.Camera
): PostFXPipeline {
  const composer = new EffectComposer(renderer);
  const renderPass = new RenderPass(scene, camera);
  composer.addPass(renderPass);

  const godRaysPass = new ShaderPass(GodRaysShader);
  composer.addPass(godRaysPass);

  const bloomPass = new UnrealBloomPass(
    new THREE.Vector2(window.innerWidth, window.innerHeight),
    0.24, // crisp restrained bloom so white armor & sunlight never clip white!
    0.45,
    0.98
  );
  composer.addPass(bloomPass);

  const outputPass = new OutputPass();
  composer.addPass(outputPass);

  const proj = new THREE.Vector3();
  const camFwd = new THREE.Vector3();
  const toSun = new THREE.Vector3();

  return {
    composer,
    resize(width: number, height: number) {
      composer.setSize(width, height);
      bloomPass.resolution.set(width, height);
    },
    render(cam: THREE.Camera, sunWorldPos: THREE.Vector3) {
      proj.copy(sunWorldPos).project(cam);
      const sx = proj.x * 0.5 + 0.5;
      const sy = proj.y * 0.5 + 0.5;

      cam.getWorldDirection(camFwd);
      toSun.copy(sunWorldPos).sub(cam.position).normalize();
      const facing = camFwd.dot(toSun);

      let vis = 0;
      if (proj.z < 1.0 && facing > 0.15 && !isSunOccludedByPlanet(cam.position, toSun)) {
        const edgeDist = Math.max(Math.abs(sx - 0.5), Math.abs(sy - 0.5));
        const screenFade = 1.0 - THREE.MathUtils.smoothstep(edgeDist, 0.55, 0.95);
        vis = THREE.MathUtils.smoothstep(facing, 0.15, 0.6) * screenFade;
      }

      godRaysPass.uniforms.uSunScreenPos.value.set(
        THREE.MathUtils.clamp(sx, -0.5, 1.5),
        THREE.MathUtils.clamp(sy, -0.5, 1.5)
      );
      godRaysPass.uniforms.uSunVisible.value = vis;

      composer.render();
    },
  };
}
