import * as THREE from 'three';

/**
 * Generates an isotropic cosmic-daylight PMREM Environment Map so metals, glass,
 * armor, and blades reflect bright sunlit sky & nebula highlights everywhere on the sphere
 * (without a flat-Earth +Y green ground artifact in the southern hemisphere).
 */
export function createEnvironmentMap(
  renderer: THREE.WebGLRenderer,
  sunDir: THREE.Vector3
): { texture: THREE.Texture; dispose: () => void } {
  const pmrem = new THREE.PMREMGenerator(renderer);
  const envScene = new THREE.Scene();

  const skyGeo = new THREE.SphereGeometry(50, 24, 16);
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    uniforms: {
      uSunDir: { value: sunDir.clone().normalize() },
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vDir;
      uniform vec3 uSunDir;
      void main() {
        float sunDot = max(0.0, dot(vDir, uSunDir));
        float band = 0.5 + 0.5 * sin(vDir.y * 2.5 + vDir.x * 1.4);
        vec3 baseSpace = vec3(0.08, 0.16, 0.30);
        vec3 coolCyan = vec3(0.18, 0.42, 0.68);
        vec3 col = mix(baseSpace, coolCyan, band * 0.65);
        col += vec3(3.2, 2.4, 1.5) * pow(sunDot, 26.0);
        col += vec3(0.75, 0.52, 0.34) * pow(sunDot, 3.5) * 0.7;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  envScene.add(new THREE.Mesh(skyGeo, skyMat));

  const rt = pmrem.fromScene(envScene, 0.04);
  pmrem.dispose();
  skyGeo.dispose();
  skyMat.dispose();

  return {
    texture: rt.texture,
    dispose: () => rt.dispose(),
  };
}
