import * as THREE from 'three';
import {
  PLANET_RADIUS,
  SEA_LEVEL,
  getSurfacePosition,
  getTerrainHeight,
  parallelTransport,
  projectOntoTangent,
} from '../math/spherical';

export type CreatureKind = 'grazer' | 'manta' | 'stalker';

export interface Creature {
  id: string;
  kind: CreatureKind;
  mesh: THREE.Group;
  hpBarGroup: THREE.Group;
  hpBarFill: THREE.Mesh;
  position: THREE.Vector3;
  prevUp: THREE.Vector3;
  orientation: THREE.Quaternion;
  headingAngle: number;
  speed: number;
  hp: number;
  maxHp: number;
  alive: boolean;
  respawnTimer: number;
  panicTimer: number;
  hitFlash: number;
  biteCooldown: number;
  phase: number;
  limbs: THREE.Object3D[];
}

export interface WildlifeEvents {
  stalkerHit: number;
  creatureKills: number;
  shardsGained: number;
}

export class WildlifeSystem {
  public readonly group = new THREE.Group();
  public readonly creatures: Creature[] = [];
  private sparks: { mesh: THREE.Mesh; vel: THREE.Vector3; life: number }[] = [];
  private sparkGeo = new THREE.DodecahedronGeometry(0.22, 0);

  constructor() {
    this.spawnWildlife();
  }

  private createHpBar(maxW: number, y: number): { hpBarGroup: THREE.Group; hpBarFill: THREE.Mesh } {
    const hpBarGroup = new THREE.Group();
    hpBarGroup.position.set(0, y, 0);
    hpBarGroup.visible = false;
    const bg = new THREE.Mesh(
      new THREE.PlaneGeometry(maxW, 0.16),
      new THREE.MeshBasicMaterial({ color: '#11161f', side: THREE.DoubleSide })
    );
    hpBarGroup.add(bg);
    const hpBarFill = new THREE.Mesh(
      new THREE.PlaneGeometry(maxW - 0.05, 0.1),
      new THREE.MeshBasicMaterial({ color: '#5effa8', side: THREE.DoubleSide })
    );
    hpBarFill.position.z = 0.01;
    hpBarGroup.add(hpBarFill);
    return { hpBarGroup, hpBarFill };
  }

  private spawnWildlife(): void {
    const upRef = new THREE.Vector3(0, 1, 0);

    // 1. 18 Lumina Grazers
    for (let i = 0; i < 18; i++) {
      const ang = (i / 18) * Math.PI * 2 + 0.3;
      const dir = new THREE.Vector3(Math.cos(ang) * 0.85, Math.sin(i * 1.7) * 0.45, Math.sin(ang) * 0.85).normalize();
      if (getTerrainHeight(dir) < SEA_LEVEL + 0.5) dir.y += 0.35;
      dir.normalize();
      const pos = getSurfacePosition(dir, 0);
      const { mesh, limbs } = this.buildGrazerMesh();
      const { hpBarGroup, hpBarFill } = this.createHpBar(1.4, 2.5);
      mesh.add(hpBarGroup);
      const quat = new THREE.Quaternion().setFromUnitVectors(upRef, dir);
      mesh.position.copy(pos);
      mesh.quaternion.copy(quat);
      this.group.add(mesh);

      this.creatures.push({
        id: `grazer-${i}`,
        kind: 'grazer',
        mesh,
        hpBarGroup,
        hpBarFill,
        position: pos,
        prevUp: dir.clone(),
        orientation: quat,
        headingAngle: i * 1.1,
        speed: 4.0,
        hp: 45,
        maxHp: 45,
        alive: true,
        respawnTimer: 0,
        panicTimer: 0,
        hitFlash: 0,
        biteCooldown: 0,
        phase: i * 0.7,
        limbs,
      });
    }

    // 2. 12 Sky Mantas
    for (let i = 0; i < 12; i++) {
      const ang = (i / 12) * Math.PI * 2;
      const dir = new THREE.Vector3(Math.cos(ang) * 0.9, Math.sin(i * 2.3) * 0.4, Math.sin(ang) * 0.9).normalize();
      const pos = dir.clone().multiplyScalar(PLANET_RADIUS + 20 + (i % 3) * 4);
      const { mesh, limbs } = this.buildMantaMesh();
      const { hpBarGroup, hpBarFill } = this.createHpBar(1.8, 1.4);
      mesh.add(hpBarGroup);
      const quat = new THREE.Quaternion().setFromUnitVectors(upRef, dir);
      mesh.position.copy(pos);
      mesh.quaternion.copy(quat);
      this.group.add(mesh);

      this.creatures.push({
        id: `manta-${i}`,
        kind: 'manta',
        mesh,
        hpBarGroup,
        hpBarFill,
        position: pos,
        prevUp: dir.clone(),
        orientation: quat,
        headingAngle: ang,
        speed: 9.5,
        hp: 60,
        maxHp: 60,
        alive: true,
        respawnTimer: 0,
        panicTimer: 0,
        hitFlash: 0,
        biteCooldown: 0,
        phase: i * 1.3,
        limbs,
      });
    }

    // 3. 10 Crystal Stalkers (Predators!)
    for (let i = 0; i < 10; i++) {
      const ang = (i / 10) * Math.PI * 2 + 0.8;
      const dir = new THREE.Vector3(Math.cos(ang) * 0.75, i % 2 === 0 ? 0.35 : -0.35, Math.sin(ang) * 0.75).normalize();
      const pos = getSurfacePosition(dir, 0);
      const { mesh, limbs } = this.buildStalkerMesh();
      const { hpBarGroup, hpBarFill } = this.createHpBar(1.6, 2.2);
      (hpBarFill.material as THREE.MeshBasicMaterial).color.set('#ff3877');
      mesh.add(hpBarGroup);
      const quat = new THREE.Quaternion().setFromUnitVectors(upRef, dir);
      mesh.position.copy(pos);
      mesh.quaternion.copy(quat);
      this.group.add(mesh);

      this.creatures.push({
        id: `stalker-${i}`,
        kind: 'stalker',
        mesh,
        hpBarGroup,
        hpBarFill,
        position: pos,
        prevUp: dir.clone(),
        orientation: quat,
        headingAngle: ang,
        speed: 7.5,
        hp: 85,
        maxHp: 85,
        alive: true,
        respawnTimer: 0,
        panicTimer: 0,
        hitFlash: 0,
        biteCooldown: 0,
        phase: i * 0.9,
        limbs,
      });
    }
  }

  private buildGrazerMesh(): { mesh: THREE.Group; limbs: THREE.Object3D[] } {
    const g = new THREE.Group();
    const bodyMat = new THREE.MeshStandardMaterial({ color: '#d8cbb5', roughness: 0.65 });
    const glowMat = new THREE.MeshStandardMaterial({
      color: '#63f5ff',
      emissive: '#1bc8ff',
      emissiveIntensity: 1.5,
    });

    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.32, 0.9, 8, 12), bodyMat);
    torso.rotation.x = Math.PI / 2;
    torso.position.y = 1.05;
    torso.castShadow = true;
    g.add(torso);

    const neck = new THREE.Mesh(new THREE.CapsuleGeometry(0.14, 0.55, 6, 10), bodyMat);
    neck.position.set(0, 1.48, -0.55);
    neck.rotation.x = 0.45;
    neck.castShadow = true;
    g.add(neck);

    const head = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 10), bodyMat);
    head.scale.set(0.85, 0.85, 1.3);
    head.position.set(0, 1.78, -0.75);
    g.add(head);

    for (const sx of [-0.14, 0.14]) {
      const horn = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.55, 6), glowMat);
      horn.position.set(sx, 2.08, -0.7);
      horn.rotation.z = sx * -1.4;
      g.add(horn);
    }

    const limbs: THREE.Object3D[] = [];
    const legGeo = new THREE.CapsuleGeometry(0.08, 0.72, 6, 8);
    legGeo.translate(0, -0.36, 0);
    for (const [lx, lz] of [[-0.2, -0.4], [0.2, -0.4], [-0.2, 0.45], [0.2, 0.45]]) {
      const leg = new THREE.Mesh(legGeo, bodyMat);
      leg.position.set(lx, 0.9, lz);
      leg.castShadow = true;
      g.add(leg);
      limbs.push(leg);
    }
    return { mesh: g, limbs };
  }

  private buildMantaMesh(): { mesh: THREE.Group; limbs: THREE.Object3D[] } {
    const g = new THREE.Group();
    const mat = new THREE.MeshStandardMaterial({
      color: '#2c5c8a',
      emissive: '#0c2c4d',
      roughness: 0.35,
      metalness: 0.3,
    });
    const trimMat = new THREE.MeshStandardMaterial({
      color: '#6ff7ff',
      emissive: '#1bd4ff',
      emissiveIntensity: 1.5,
    });

    const core = new THREE.Mesh(new THREE.SphereGeometry(0.85, 12, 10), mat);
    core.scale.set(1.3, 0.28, 2.1);
    g.add(core);

    const limbs: THREE.Object3D[] = [];
    for (const sx of [-1, 1]) {
      const wingPivot = new THREE.Group();
      const wing = new THREE.Mesh(new THREE.SphereGeometry(1.1, 10, 8), mat);
      wing.scale.set(2.2, 0.12, 1.1);
      wing.position.x = sx * 1.5;
      wingPivot.add(wing);

      const stripe = new THREE.Mesh(new THREE.BoxGeometry(1.9, 0.08, 0.18), trimMat);
      stripe.position.set(sx * 1.4, 0.06, -0.3);
      wingPivot.add(stripe);

      g.add(wingPivot);
      limbs.push(wingPivot);
    }
    return { mesh: g, limbs };
  }

  private buildStalkerMesh(): { mesh: THREE.Group; limbs: THREE.Object3D[] } {
    const g = new THREE.Group();
    const bodyMat = new THREE.MeshStandardMaterial({ color: '#261a2e', roughness: 0.45, metalness: 0.4 });
    const glowMat = new THREE.MeshStandardMaterial({
      color: '#ff3877',
      emissive: '#ff1255',
      emissiveIntensity: 1.8,
    });

    const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.42, 0.9, 8, 12), bodyMat);
    body.rotation.x = Math.PI / 2;
    body.position.y = 0.95;
    body.castShadow = true;
    g.add(body);

    const crest = new THREE.Mesh(new THREE.OctahedronGeometry(0.45, 0), glowMat);
    crest.scale.set(0.6, 1.3, 0.9);
    crest.position.set(0, 1.35, -0.3);
    g.add(crest);

    const limbs: THREE.Object3D[] = [];
    const legGeo = new THREE.CapsuleGeometry(0.1, 0.65, 6, 8);
    legGeo.translate(0, -0.32, 0);
    for (const [lx, lz] of [[-0.36, -0.4], [0.36, -0.4], [-0.36, 0.45], [0.36, 0.45]]) {
      const leg = new THREE.Mesh(legGeo, bodyMat);
      leg.position.set(lx, 0.85, lz);
      leg.castShadow = true;
      g.add(leg);
      limbs.push(leg);
    }
    return { mesh: g, limbs };
  }

  private spawnHitSparks(pos: THREE.Vector3, colorHex: number, count = 10): void {
    const up = pos.clone().normalize();
    for (let i = 0; i < count; i++) {
      const mat = new THREE.MeshBasicMaterial({ color: colorHex, transparent: true, opacity: 1 });
      const m = new THREE.Mesh(this.sparkGeo, mat);
      m.position.copy(pos).addScaledVector(up, 1.0);
      this.group.add(m);
      const vel = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5)
        .normalize()
        .multiplyScalar(6 + Math.random() * 10)
        .addScaledVector(up, 5);
      this.sparks.push({ mesh: m, vel, life: 0.45 + Math.random() * 0.25 });
    }
  }

  public damageCreature(c: Creature, damage: number, hitFromPos?: THREE.Vector3): { killed: boolean; shards: number } {
    if (!c.alive) return { killed: false, shards: 0 };
    c.hp -= damage;
    c.hitFlash = 0.2;
    c.panicTimer = 4.0;
    c.hpBarGroup.visible = true;
    const up = c.position.clone().normalize();
    if (hitFromPos) {
      const push = c.position.clone().sub(hitFromPos);
      projectOntoTangent(push, up, push);
      if (push.lengthSq() > 0.001) {
        c.position.addScaledVector(push.normalize(), 1.2);
      }
    }
    this.spawnHitSparks(c.position, c.kind === 'stalker' ? 0xff3877 : 0x5effd8, 8);

    if (c.hp <= 0) {
      c.alive = false;
      c.mesh.visible = false;
      c.respawnTimer = 18.0;
      this.spawnHitSparks(c.position, c.kind === 'stalker' ? 0xff4499 : 0x66f5ff, 18);
      return { killed: true, shards: c.kind === 'stalker' ? 22 : c.kind === 'manta' ? 18 : 12 };
    }
    return { killed: false, shards: 0 };
  }

  public damageAtPoint(
    point: THREE.Vector3,
    radius: number,
    damage: number,
    fromPos?: THREE.Vector3,
    prevPoint?: THREE.Vector3
  ): { hits: number; kills: number; shards: number } {
    let hits = 0;
    let kills = 0;
    let shards = 0;
    const seg = prevPoint ? new THREE.Line3(prevPoint, point) : null;
    const closest = new THREE.Vector3();
    for (const c of this.creatures) {
      if (!c.alive) continue;
      const bodyCenter = c.position.clone().addScaledVector(c.position.clone().normalize(), c.kind === 'manta' ? 0.2 : 1.0);
      const rHit = radius + (c.kind === 'manta' ? 2.4 : 1.5);
      const dist = seg ? seg.closestPointToPoint(bodyCenter, true, closest).distanceTo(bodyCenter) : bodyCenter.distanceTo(point);
      if (dist <= rHit) {
        hits++;
        const res = this.damageCreature(c, damage, fromPos);
        if (res.killed) {
          kills++;
          shards += res.shards;
        }
      }
    }
    return { hits, kills, shards };
  }

  public update(
    dt: number,
    time: number,
    playerPos: THREE.Vector3,
    camera: THREE.Camera,
    entityVel?: THREE.Vector3,
    entityRadius = 1.4,
    isVehicle = false
  ): WildlifeEvents {
    let stalkerHit = 0;
    let creatureKills = 0;
    let shardsGained = 0;

    for (const c of this.creatures) {
      if (!c.alive) {
        c.respawnTimer -= dt;
        if (c.respawnTimer <= 0) {
          c.alive = true;
          c.hp = c.maxHp;
          c.hpBarGroup.visible = false;
          c.mesh.visible = true;
          const ang = Math.random() * Math.PI * 2;
          const rDir = new THREE.Vector3(Math.cos(ang), (Math.random() - 0.5) * 0.9, Math.sin(ang)).normalize();
          if (c.kind !== 'manta' && getTerrainHeight(rDir) < SEA_LEVEL + 0.4) rDir.y = Math.abs(rDir.y) + 0.35;
          rDir.normalize();
          c.position.copy(
            c.kind === 'manta'
              ? rDir.clone().multiplyScalar(PLANET_RADIUS + 20)
              : getSurfacePosition(rDir, 0)
          );
          c.prevUp.copy(rDir);
        }
        continue;
      }

      const up = c.position.clone().normalize();
      parallelTransport(c.orientation, c.prevUp, up);
      c.prevUp.copy(up);

      if (c.panicTimer > 0) c.panicTimer -= dt;
      if (c.hitFlash > 0) c.hitFlash -= dt;

      const dist = c.position.distanceTo(playerPos);
      let moveSpeed = c.speed;

      if (c.kind === 'grazer') {
        if (dist < 18 || c.panicTimer > 0) {
          const away = c.position.clone().sub(playerPos);
          away.addScaledVector(up, -away.dot(up));
          if (away.lengthSq() > 0.001) away.normalize();
          else {
            const ref = Math.abs(up.x) < 0.85 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
            away.crossVectors(ref, up).normalize();
          }
          c.position.addScaledVector(away, 10.5 * dt);
          const right = new THREE.Vector3().crossVectors(away, up).normalize();
          c.orientation.setFromRotationMatrix(new THREE.Matrix4().makeBasis(right, up, away.clone().negate()));
          moveSpeed = 10.5;
        } else {
          c.headingAngle += Math.sin(time * 0.4 + c.phase) * 0.5 * dt;
          const fwd = new THREE.Vector3(0, 0, -1).applyQuaternion(c.orientation);
          c.position.addScaledVector(fwd, 2.6 * dt);
          const yaw = new THREE.Quaternion().setFromAxisAngle(up, Math.sin(time * 0.5 + c.phase) * 0.6 * dt);
          c.orientation.premultiply(yaw).normalize();
        }
        const newUp = c.position.clone().normalize();
        const h = Math.max(SEA_LEVEL + 0.15, getTerrainHeight(newUp));
        c.position.copy(newUp).multiplyScalar(h);

        const swing = Math.sin(time * (moveSpeed * 1.4) + c.phase) * 0.5;
        c.limbs[0].rotation.x = swing;
        c.limbs[1].rotation.x = -swing;
        c.limbs[2].rotation.x = -swing;
        c.limbs[3].rotation.x = swing;
      } else if (c.kind === 'manta') {
        const fwd = new THREE.Vector3(0, 0, -1).applyQuaternion(c.orientation);
        c.position.addScaledVector(fwd, c.speed * dt);
        const yaw = new THREE.Quaternion().setFromAxisAngle(up, 0.18 * dt);
        c.orientation.premultiply(yaw).normalize();
        const newUp = c.position.clone().normalize();
        c.position.copy(newUp).multiplyScalar(PLANET_RADIUS + 20 + Math.sin(time * 0.7 + c.phase) * 2.5);

        const flap = Math.sin(time * 3.2 + c.phase) * 0.32;
        c.limbs[0].rotation.z = flap;
        c.limbs[1].rotation.z = -flap;
      } else if (c.kind === 'stalker') {
        if (dist < 34 || c.panicTimer > 0) {
          const toPlayer = playerPos.clone().sub(c.position);
          toPlayer.addScaledVector(up, -toPlayer.dot(up));
          if (toPlayer.lengthSq() > 0.001) {
            toPlayer.normalize();
            c.position.addScaledVector(toPlayer, 8.6 * dt);
            const right = new THREE.Vector3().crossVectors(toPlayer, up).normalize();
            c.orientation.setFromRotationMatrix(new THREE.Matrix4().makeBasis(right, up, toPlayer.clone().negate()));
          }
          if (c.biteCooldown > 0) c.biteCooldown -= dt;
          if (dist < 2.8 && c.biteCooldown <= 0) {
            c.biteCooldown = 0.9;
            stalkerHit += 14;
            this.spawnHitSparks(c.position, 0xff3877, 8);
          }
        } else {
          const fwd = new THREE.Vector3(0, 0, -1).applyQuaternion(c.orientation);
          c.position.addScaledVector(fwd, 3.4 * dt);
          const yaw = new THREE.Quaternion().setFromAxisAngle(up, 0.55 * dt);
          c.orientation.premultiply(yaw).normalize();
        }
        const newUp = c.position.clone().normalize();
        const h = Math.max(SEA_LEVEL + 0.15, getTerrainHeight(newUp));
        c.position.copy(newUp).multiplyScalar(h);

        const swing = Math.sin(time * 9 + c.phase) * 0.55;
        c.limbs[0].rotation.x = swing;
        c.limbs[1].rotation.x = -swing;
        c.limbs[2].rotation.x = -swing;
        c.limbs[3].rotation.x = swing;
      }

      // Tangible Solid Physical Touch & Vehicle Ramming (MUST check true 3D distance first so cross-planet never triggers!)
      if (dist < 10.0 && (c.kind !== 'manta' || isVehicle)) {
        const delta = c.position.clone().sub(playerPos);
        projectOntoTangent(delta, up, delta);
        const minTouchD = entityRadius + (c.kind === 'manta' ? 2.2 : 0.95);
        if (delta.lengthSq() < minTouchD * minTouchD && Math.abs(c.position.length() - playerPos.length()) < 4.5) {
          const d = Math.max(0.01, delta.length());
          const pushN = delta.divideScalar(d);
          const speed = entityVel ? entityVel.length() : 0;
          if (isVehicle && speed > 10) {
            const res = this.damageCreature(c, speed * 3.2, playerPos);
            if (res.killed) {
              creatureKills++;
              shardsGained += res.shards;
            }
          } else {
            c.position.addScaledVector(pushN, minTouchD - d + 0.15);
            c.panicTimer = 2.0;
          }
        }
      }

      // Update HP bar above injured creature
      if (c.hpBarGroup.visible) {
        c.hpBarFill.scale.x = Math.max(0.01, c.hp / c.maxHp);
        c.hpBarGroup.up.copy(up);
        c.hpBarGroup.lookAt(camera.position);
      }

      c.mesh.position.copy(c.position);
      c.mesh.quaternion.copy(c.orientation);
    }

    for (let i = this.sparks.length - 1; i >= 0; i--) {
      const s = this.sparks[i];
      s.life -= dt;
      const sUp = s.mesh.position.clone().normalize();
      s.vel.addScaledVector(sUp, -20 * dt);
      s.mesh.position.addScaledVector(s.vel, dt);
      (s.mesh.material as THREE.MeshBasicMaterial).opacity = Math.max(0, s.life * 2);
      if (s.life <= 0) {
        this.group.remove(s.mesh);
        (s.mesh.material as THREE.Material).dispose();
        this.sparks.splice(i, 1);
      }
    }

    return { stalkerHit, creatureKills, shardsGained };
  }
}
