import * as THREE from 'three';

function makeCanvas(size = 512): [HTMLCanvasElement, CanvasRenderingContext2D] {
  const c = document.createElement('canvas');
  c.width = size;
  c.height = size;
  return [c, c.getContext('2d')!];
}

function makeSeededRandom(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967295;
  };
}

function tileNoise(x: number, y: number, periodX: number, periodY: number, seed: number): number {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);

  const h = (ix: number, iy: number) => {
    const px = ((ix % periodX) + periodX) % periodX;
    const py = ((iy % periodY) + periodY) % periodY;
    let n = px * 374761393 + py * 668265263 + seed * 1442695041;
    n = (n ^ (n >> 13)) * 1274126177;
    return ((n ^ (n >> 16)) >>> 0) / 4294967295;
  };

  const a = h(xi, yi);
  const b = h(xi + 1, yi);
  const c = h(xi, yi + 1);
  const d = h(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

function tileFbm(u: number, v: number, freqX: number, freqY: number, octaves: number, seed: number): number {
  let val = 0;
  let amp = 0.5;
  let fx = freqX;
  let fy = freqY;
  for (let i = 0; i < octaves; i++) {
    val += amp * tileNoise(u * fx, v * fy, fx, fy, seed + i * 31);
    fx *= 2;
    fy *= 2;
    amp *= 0.5;
  }
  return val;
}

function buildTexturesFromHeight(
  size: number,
  heightFn: (u: number, v: number) => number,
  colorFn: (h: number, u: number, v: number) => [number, number, number],
  normalStrength: number,
  repeat = 1
): { albedo: THREE.CanvasTexture; normal: THREE.CanvasTexture } {
  const heights = new Float32Array(size * size);
  const [ac, actx] = makeCanvas(size);
  const aImg = actx.createImageData(size, size);

  for (let y = 0; y < size; y++) {
    const v = y / size;
    for (let x = 0; x < size; x++) {
      const u = x / size;
      const h = heightFn(u, v);
      heights[y * size + x] = h;
      const [r, g, b] = colorFn(h, u, v);
      const idx = (y * size + x) * 4;
      aImg.data[idx] = Math.max(0, Math.min(255, r));
      aImg.data[idx + 1] = Math.max(0, Math.min(255, g));
      aImg.data[idx + 2] = Math.max(0, Math.min(255, b));
      aImg.data[idx + 3] = 255;
    }
  }
  actx.putImageData(aImg, 0, 0);

  // OpenGL +Y normal map (Canvas y increases downward while WebGL v increases upward under flipY=true)
  const [nc, nctx] = makeCanvas(size);
  const nImg = nctx.createImageData(size, size);
  for (let y = 0; y < size; y++) {
    const ym = (y - 1 + size) % size;
    const yp = (y + 1) % size;
    for (let x = 0; x < size; x++) {
      const xm = (x - 1 + size) % size;
      const xp = (x + 1) % size;
      const dx = (heights[y * size + xp] - heights[y * size + xm]) * normalStrength;
      const dy = (heights[yp * size + x] - heights[ym * size + x]) * normalStrength;
      const nx = -dx;
      const ny = dy; // +dy matches OpenGL +Y up!
      const nz = 1;
      const len = Math.hypot(nx, ny, nz);
      const idx = (y * size + x) * 4;
      nImg.data[idx] = ((nx / len) * 0.5 + 0.5) * 255;
      nImg.data[idx + 1] = ((ny / len) * 0.5 + 0.5) * 255;
      nImg.data[idx + 2] = ((nz / len) * 0.5 + 0.5) * 255;
      nImg.data[idx + 3] = 255;
    }
  }
  nctx.putImageData(nImg, 0, 0);

  const albedo = new THREE.CanvasTexture(ac);
  albedo.wrapS = THREE.RepeatWrapping;
  albedo.wrapT = THREE.RepeatWrapping;
  albedo.repeat.set(repeat, repeat);
  albedo.colorSpace = THREE.SRGBColorSpace;
  albedo.anisotropy = 8;

  const normal = new THREE.CanvasTexture(nc);
  normal.wrapS = THREE.RepeatWrapping;
  normal.wrapT = THREE.RepeatWrapping;
  normal.repeat.set(repeat, repeat);
  normal.anisotropy = 8;

  return { albedo, normal };
}

/**
 * Bleeds foliage green into transparent pixels (alpha === 0) with premultiplyAlpha=false
 * so mipmapping & bilinear filtering NEVER produce dark black alpha halos!
 */
function finalizeFoliageCanvasTexture(canvas: HTMLCanvasElement, r: number, g: number, b: number): THREE.CanvasTexture {
  const ctx = canvas.getContext('2d')!;
  const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    if (d[i + 3] < 8) {
      d[i] = r;
      d[i + 1] = g;
      d[i + 2] = b;
      d[i + 3] = 0;
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.premultiplyAlpha = false;
  tex.anisotropy = 8;
  return tex;
}

function buildGrassCardTexture(): THREE.CanvasTexture {
  const rand = makeSeededRandom(10101);
  const [c, ctx] = makeCanvas(256);
  ctx.clearRect(0, 0, 256, 256);

  for (let i = 0; i < 34; i++) {
    const bx = 34 + (i / 33) * 188 + (rand() - 0.5) * 10;
    const h = 115 + rand() * 115; // strictly inside y >= 26
    const lean = (rand() - 0.5) * 44; // stays cleanly within [12, 244]
    const w = 8 + rand() * 6;

    const grad = ctx.createLinearGradient(bx, 256, bx + lean, 256 - h);
    grad.addColorStop(0, '#1a4c26');
    grad.addColorStop(0.55, '#2e8842');
    grad.addColorStop(1, '#77d466');

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(bx - w * 0.5, 256);
    ctx.quadraticCurveTo(bx + lean * 0.45 - w * 0.25, 256 - h * 0.55, bx + lean, 256 - h);
    ctx.quadraticCurveTo(bx + lean * 0.45 + w * 0.25, 256 - h * 0.55, bx + w * 0.5, 256);
    ctx.closePath();
    ctx.fill();
  }

  return finalizeFoliageCanvasTexture(c, 42, 118, 56);
}

function buildLeafCardTexture(): THREE.CanvasTexture {
  const rand = makeSeededRandom(20202);
  const [c, ctx] = makeCanvas(256);
  ctx.clearRect(0, 0, 256, 256);

  ctx.strokeStyle = '#3a2b1d';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(128, 232);
  ctx.quadraticCurveTo(124, 140, 128, 42);
  ctx.stroke();

  for (let i = 0; i < 72; i++) {
    const ang = rand() * Math.PI * 2;
    const rad = Math.pow(rand(), 0.62) * 76; // 128 ± (76 + 22) stays strictly inside [30, 226]
    const lx = 128 + Math.cos(ang) * rad;
    const ly = 128 + Math.sin(ang) * rad;
    const size = 12 + rand() * 14;
    const rot = rand() * Math.PI * 2;

    const shade = rand();
    ctx.fillStyle =
      shade < 0.3 ? '#1e6030' : shade < 0.72 ? '#319046' : '#58bd5a';

    ctx.save();
    ctx.translate(lx, ly);
    ctx.rotate(rot);
    ctx.beginPath();
    ctx.ellipse(0, 0, size, size * 0.52, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  return finalizeFoliageCanvasTexture(c, 44, 124, 58);
}

export interface ProceduralTextures {
  grassAlbedo: THREE.CanvasTexture;
  grassNormal: THREE.CanvasTexture;
  rockAlbedo: THREE.CanvasTexture;
  rockNormal: THREE.CanvasTexture;
  sandAlbedo: THREE.CanvasTexture;
  barkAlbedo: THREE.CanvasTexture;
  barkNormal: THREE.CanvasTexture;
  metalAlbedo: THREE.CanvasTexture;
  metalNormal: THREE.CanvasTexture;
  grassCard: THREE.CanvasTexture;
  leafCard: THREE.CanvasTexture;
}

let cached: ProceduralTextures | null = null;

export function getProceduralTextures(): ProceduralTextures {
  if (cached) return cached;

  const grass = buildTexturesFromHeight(
    512,
    (u, v) => tileFbm(u, v, 8, 8, 5, 11) * 0.7 + tileFbm(u, v, 16, 16, 3, 29) * 0.3,
    (h) => [32 + h * 44, 88 + h * 80, 36 + h * 32],
    5.0
  );

  const rock = buildTexturesFromHeight(
    512,
    (u, v) => {
      const base = tileFbm(u, v, 6, 6, 5, 53);
      const strata = Math.abs(Math.sin((v + base * 0.28) * Math.PI * 10));
      return base * 0.6 + strata * 0.4;
    },
    (h) => [58 + h * 72, 64 + h * 74, 74 + h * 78],
    8.5
  );

  const sand = buildTexturesFromHeight(
    512,
    (u, v) => {
      const warp = tileFbm(u, v, 4, 4, 3, 91) * 0.2;
      const ripples = Math.sin((u * 12 + v * 4 + warp * 8) * Math.PI * 2) * 0.5 + 0.5;
      return ripples * 0.55 + tileFbm(u, v, 16, 16, 3, 77) * 0.45;
    },
    (h) => [175 + h * 58, 134 + h * 48, 82 + h * 34],
    3.5
  );

  // Exact integer tiling periods along both U and V (zero horizontal seam!)
  const bark = buildTexturesFromHeight(
    256,
    (u, v) => {
      const ridge = tileFbm(u, v, 16, 4, 4, 37);
      return ridge * 0.75 + Math.sin(u * Math.PI * 24) * 0.12 + 0.13;
    },
    (h) => [58 + h * 52, 40 + h * 34, 26 + h * 22],
    6.5,
    2
  );

  const metal = buildTexturesFromHeight(
    512,
    (u, v) => {
      const seamX = Math.abs(((u * 4) % 1) - 0.5) > 0.486 ? -0.35 : 0;
      const seamY = Math.abs(((v * 4) % 1) - 0.5) > 0.486 ? -0.35 : 0;
      const hex = Math.sin(u * Math.PI * 32) * Math.cos(v * Math.PI * 32) * 0.04;
      const brush = tileNoise(u * 64, v * 8, 64, 8, 19) * 0.1;
      return 0.68 + seamX + seamY + hex + brush;
    },
    (h) => [180 + h * 64, 194 + h * 58, 214 + h * 46],
    4.5,
    2
  );

  cached = {
    grassAlbedo: grass.albedo,
    grassNormal: grass.normal,
    rockAlbedo: rock.albedo,
    rockNormal: rock.normal,
    sandAlbedo: sand.albedo,
    barkAlbedo: bark.albedo,
    barkNormal: bark.normal,
    metalAlbedo: metal.albedo,
    metalNormal: metal.normal,
    grassCard: buildGrassCardTexture(),
    leafCard: buildLeafCardTexture(),
  };
  return cached;
}
