import * as THREE from 'three';
import { MissionState } from './missions';
import { ProgressionManager, VEHICLES, VehicleId, WEAPONS, WEAPON_ORDER, WeaponId } from './progression';

export interface WorldMarker {
  id: string;
  label: string;
  color: string;
  worldPos: THREE.Vector3;
  priority?: boolean;
}

export class GameHUD {
  private root: HTMLElement;
  private missionTitle!: HTMLElement;
  private missionDesc!: HTMLElement;
  private missionProgress!: HTMLElement;
  private shardsValue!: HTMLElement;
  private scoreBanner!: HTMLElement;
  private bossBarWrap!: HTMLElement;
  private bossBarName!: HTMLElement;
  private bossBarFill!: HTMLElement;
  private hpFill!: HTMLElement;
  private hpText!: HTMLElement;
  private boostFill!: HTMLElement;
  private boostText!: HTMLElement;
  private modeBadge!: HTMLElement;
  private speedVal!: HTMLElement;
  private speedUnit!: HTMLElement;
  private biomeLabel!: HTMLElement;
  private interactPrompt!: HTMLElement;
  private toastBanner!: HTMLElement;
  private damageVignette!: HTMLElement;
  private compassMarkers!: HTMLElement;
  private worldMarkers!: HTMLElement;
  private loadoutBar!: HTMLElement;
  private overlayScreen!: HTMLElement;
  private overlayTitle!: HTMLElement;
  private overlayDesc!: HTMLElement;
  private startBtn!: HTMLButtonElement;
  private armoryModal!: HTMLElement;
  private armoryBody!: HTMLElement;

  private toastTimer = 0;
  private damageFlash = 0;
  public armoryOpen = false;

  constructor(
    private prog: ProgressionManager,
    onStartClick: () => void,
    private onArmoryChange: () => void
  ) {
    this.root = document.getElementById('hud-root')!;
    this.root.innerHTML = `
      <div id="world-markers"></div>
      <div id="compass-bar" class="hud-panel"><div id="compass-markers"></div></div>
      <div id="boss-bar-wrap" class="hud-panel" style="display:none">
        <div id="boss-bar-name">BOSS</div>
        <div class="bar-track" style="margin-bottom:0;height:10px"><div class="bar-fill" id="boss-bar-fill" style="width:100%;background:linear-gradient(90deg,#ff2468,#ffaa33)"></div></div>
      </div>

      <div id="mission-panel" class="hud-panel">
        <div class="mission-kicker">ACTIVE OBJECTIVE</div>
        <div class="mission-title" id="mission-title">1. First Contact</div>
        <div class="mission-desc" id="mission-desc"></div>
        <div class="mission-progress-row" id="mission-progress"></div>
        <div id="shards-pill"><span>AETHER SHARDS</span><span id="shards-val">120</span></div>
        <div id="score-pill">SCORE: <span id="score-val">0</span></div>
      </div>

      <div id="controls-panel" class="hud-panel">
        <div><kbd>W A S D</kbd> Drive / Move / Fly</div>
        <div><kbd>1</kbd>–<kbd>=</kbd> Weapons &nbsp;<kbd>Tab</kbd> Market</div>
        <div><kbd>LMB</kbd> Fire / Slash &nbsp;<kbd>RMB</kbd> Aim / Missile</div>
        <div><kbd>F</kbd> Rover &nbsp;<kbd>G</kbd> Jet &nbsp;<kbd>↑↓</kbd>/<kbd>X</kbd> Pitch</div>
        <div><kbd>Q</kbd> Blink Dash &nbsp;<kbd>Z</kbd>/<kbd>Alt</kbd> Dodge Roll</div>
        <div><kbd>C</kbd> Blast &nbsp;<kbd>V</kbd> Shield &nbsp;<kbd>E</kbd> Loot</div>
        <div><kbd>Shift</kbd> Turbo/Afterburner &nbsp;<kbd>Space</kbd> Lift</div>
      </div>

      <div id="stats-panel" class="hud-panel">
        <div class="bar-label"><span>ARMOR INTEGRITY</span><span id="hp-text">140/140</span></div>
        <div class="bar-track"><div class="bar-fill" id="hp-fill" style="width:100%"></div></div>
        <div class="bar-label"><span>THRUSTER / JETPACK</span><span id="boost-text">100%</span></div>
        <div class="bar-track" style="margin-bottom:0"><div class="bar-fill" id="boost-fill" style="width:100%"></div></div>
      </div>

      <div id="loadout-bar" class="hud-panel"></div>

      <div id="speed-panel" class="hud-panel">
        <div id="mode-badge">VANGUARD BUGGY</div>
        <div id="speed-val">0</div>
        <div id="speed-unit">KM/H EQUIV</div>
        <div id="biome-label">Emerald Forest</div>
      </div>

      <div id="crosshair"></div>
      <div id="interact-prompt" class="hud-panel"></div>
      <div id="toast-banner" class="hud-panel"></div>
      <div id="damage-vignette"></div>

      <div id="overlay-screen">
        <div id="overlay-card" class="hud-panel">
          <h1 id="overlay-title">ORBITA: VANGUARD</h1>
          <p id="overlay-desc">
            Explore a 4-planet star system! Smash through destructible forests in your high-torque Rover, slice projectiles with Katanas &amp; Warhammers, teleport-dash &amp; dodge-roll Elden Ring bosses, and pilot the Valkyrie Air Force Jet straight to Aurelia, Pyros, and Glacies.
          </p>
          <button class="primary-btn" id="start-btn">DEPLOY TO PLANET</button>
        </div>
      </div>

      <div id="armory-modal">
        <div id="armory-card" class="hud-panel">
          <h2>BLACK-MARKET ARMORY &amp; INFINITE UPGRADES</h2>
          <div id="armory-body"></div>
          <div style="text-align:right;margin-top:12px">
            <button class="primary-btn" id="close-armory-btn">RESUME [TAB]</button>
          </div>
        </div>
      </div>
    `;

    this.missionTitle = document.getElementById('mission-title')!;
    this.missionDesc = document.getElementById('mission-desc')!;
    this.missionProgress = document.getElementById('mission-progress')!;
    this.shardsValue = document.getElementById('shards-val')!;
    this.scoreBanner = document.getElementById('score-val')!;
    this.bossBarWrap = document.getElementById('boss-bar-wrap')!;
    this.bossBarName = document.getElementById('boss-bar-name')!;
    this.bossBarFill = document.getElementById('boss-bar-fill')!;
    this.hpFill = document.getElementById('hp-fill')!;
    this.hpText = document.getElementById('hp-text')!;
    this.boostFill = document.getElementById('boost-fill')!;
    this.boostText = document.getElementById('boost-text')!;
    this.modeBadge = document.getElementById('mode-badge')!;
    this.speedVal = document.getElementById('speed-val')!;
    this.speedUnit = document.getElementById('speed-unit')!;
    this.biomeLabel = document.getElementById('biome-label')!;
    this.interactPrompt = document.getElementById('interact-prompt')!;
    this.toastBanner = document.getElementById('toast-banner')!;
    this.damageVignette = document.getElementById('damage-vignette')!;
    this.compassMarkers = document.getElementById('compass-markers')!;
    this.worldMarkers = document.getElementById('world-markers')!;
    this.loadoutBar = document.getElementById('loadout-bar')!;
    this.overlayScreen = document.getElementById('overlay-screen')!;
    this.overlayTitle = document.getElementById('overlay-title')!;
    this.overlayDesc = document.getElementById('overlay-desc')!;
    this.startBtn = document.getElementById('start-btn') as HTMLButtonElement;
    this.armoryModal = document.getElementById('armory-modal')!;
    this.armoryBody = document.getElementById('armory-body')!;

    this.startBtn.addEventListener('click', () => {
      this.overlayScreen.style.display = 'none';
      onStartClick();
    });

    document.getElementById('close-armory-btn')!.addEventListener('click', () => {
      this.toggleArmory(false);
    });
  }

  public toggleArmory(force?: boolean): void {
    this.armoryOpen = force !== undefined ? force : !this.armoryOpen;
    this.armoryModal.style.display = this.armoryOpen ? 'flex' : 'none';
    if (this.armoryOpen) {
      document.exitPointerLock?.();
      this.renderArmory();
    }
  }

  private renderArmory(): void {
    const p = this.prog;
    const weaponBtns = WEAPON_ORDER.map((id) => {
      const w = WEAPONS[id];
      const unlocked = p.unlockedWeapons.has(id);
      return `<button class="armory-btn ${p.weapon === id ? 'selected' : ''}" data-weapon="${id}">
        <div style="color:${w.color}">${w.key}. ${w.name}</div>
        <div style="font-size:10px;opacity:0.82">${
          unlocked
            ? p.weapon === id
              ? 'EQUIPPED'
              : w.kind === 'melee'
              ? `Melee (${w.damage} DMG)`
              : `Ranged (${w.damage} DMG)`
            : `Buy: ${w.cost} Shards`
        }</div>
      </button>`;
    }).join('');

    const vehicleBtns = (['buggy', 'interceptor', 'titan'] as VehicleId[])
      .map((id) => {
        const v = VEHICLES[id];
        const unlocked = p.unlockedVehicles.has(id);
        return `<button class="armory-btn ${p.vehicle === id ? 'selected' : ''}" data-vehicle="${id}">
          <div style="color:${v.accentColor}">${v.name}</div>
          <div style="font-size:10px;opacity:0.82">${unlocked ? (p.vehicle === id ? 'EQUIPPED' : 'Equip') : `Buy: ${v.cost} Shards`}</div>
        </button>`;
      })
      .join('');

    const upgBtn = (key: string, label: string, lv: number, bonus: string) => {
      const cost = p.getUpgradeCost(lv);
      return `<button class="armory-btn" data-upg="${key}">
        <div>${label} <span style="color:#6ce5ff">Lv ${lv}</span></div>
        <div style="font-size:10px;opacity:0.78">${bonus}</div>
        <div style="font-size:10.5px;color:#ffd666;margin-top:2px">Upgrade: ${cost} Shards</div>
      </button>`;
    };

    this.armoryBody.innerHTML = `
      <div style="display:flex;justify-content:space-between;font-size:13px;color:#ffd666;font-weight:700;margin-bottom:8px">
        <span>Aether Shards: ${p.shards.toLocaleString()}</span>
        <span style="color:#ff8ea8">Enemy Scaling Threat: x${p.getEnemyHpMult().toFixed(2)}</span>
      </div>
      <div style="font-size:11px;letter-spacing:0.1em;color:#8ee8ff">12 ARSENAL WEAPONS (MELEE + RANGED)</div>
      <div class="armory-grid armory-grid-4">${weaponBtns}</div>
      <div style="font-size:11px;letter-spacing:0.1em;color:#8ee8ff">PLANETARY VEHICLES</div>
      <div class="armory-grid">${vehicleBtns}</div>
      <div style="font-size:11px;letter-spacing:0.1em;color:#8ee8ff">UNLIMITED OVERCLOCK UPGRADES (NO CAP!)</div>
      <div class="armory-grid">
        ${upgBtn('weapon', 'Weapon Damage', p.weaponLv, `x${p.getWeaponDamageMult().toFixed(2)} DMG`)}
        ${upgBtn('engine', 'Jet & Car Thrusters', p.engineLv, `x${p.getEngineSpeedMult().toFixed(2)} Speed`)}
        ${upgBtn('armor', 'Titanium Hull', p.armorLv, `+${p.getArmorMaxBonus()} Max HP`)}
        ${upgBtn('dash', 'Blink Dash Matrix', p.dashLv, `${p.maxDashCharges} Charges (${p.dashRechargeDuration.toFixed(1)}s)`)}
        ${upgBtn('regen', 'Nano Bio-Regen', p.regenLv, `${p.getRegenRate().toFixed(1)} HP/s`)}
        ${upgBtn('greed', 'Aether Harvest', p.greedLv, `x${p.getGreedMult().toFixed(2)} Shards & Score`)}
      </div>
    `;

    this.armoryBody.querySelectorAll('[data-weapon]').forEach((el) => {
      el.addEventListener('click', () => {
        const id = el.getAttribute('data-weapon') as WeaponId;
        if (p.unlockOrEquipWeapon(id)) {
          this.onArmoryChange();
          this.renderArmory();
        } else {
          this.showToast('Earn more Shards or find in a Treasure Chest!', 2.0);
        }
      });
    });
    this.armoryBody.querySelectorAll('[data-vehicle]').forEach((el) => {
      el.addEventListener('click', () => {
        const id = el.getAttribute('data-vehicle') as VehicleId;
        if (p.unlockOrEquipVehicle(id)) {
          this.onArmoryChange();
          this.renderArmory();
        } else {
          this.showToast('Not enough Aether Shards!', 2.0);
        }
      });
    });
    this.armoryBody.querySelectorAll('[data-upg]').forEach((el) => {
      el.addEventListener('click', () => {
        const k = el.getAttribute('data-upg');
        const ok =
          k === 'weapon' ? p.upgradeWeapon()
          : k === 'engine' ? p.upgradeEngine()
          : k === 'armor' ? p.upgradeArmor()
          : k === 'dash' ? p.upgradeDash()
          : k === 'regen' ? p.upgradeRegen()
          : p.upgradeGreed();
        if (ok) {
          this.onArmoryChange();
          this.renderArmory();
        } else {
          this.showToast('Need more Aether Shards!', 2.0);
        }
      });
    });
  }

  public showToast(msg: string, duration = 3.5): void {
    this.toastBanner.textContent = msg;
    this.toastBanner.style.opacity = '1';
    this.toastTimer = duration;
  }

  public triggerDamageFlash(): void {
    this.damageFlash = 1.0;
  }

  public showVictory(): void {
    this.overlayTitle.textContent = 'ENDLESS GALAXY CONQUEST UNLOCKED';
    this.overlayDesc.innerHTML =
      'You liberated all 4 planets and ignited the North Polar Citadel! Infinite scaling waves & hidden Elden-Ring cosmic bosses are now active across Aetheria, Aurelia, Pyros & Glacies!';
    this.startBtn.textContent = 'ENTER ENDLESS WAR';
    this.overlayScreen.style.display = 'flex';
  }

  public update(
    dt: number,
    mission: MissionState,
    hp: number,
    maxHp: number,
    boost: number,
    speed: number,
    controlMode: 'rover' | 'foot' | 'jet',
    planetName: string,
    biome: string,
    interactText: string | null,
    camera: THREE.Camera,
    subjectPos: THREE.Vector3,
    subjectUp: THREE.Vector3,
    markers: WorldMarker[],
    activeBoss: { name: string; hp: number; maxHp: number } | null
  ): void {
    const p = this.prog;
    this.missionTitle.textContent = mission.bossAlert ? mission.bossAlert : mission.title;
    this.missionDesc.textContent = mission.description;
    this.missionProgress.textContent = mission.progressText;
    this.shardsValue.textContent = p.shards.toLocaleString();
    this.scoreBanner.textContent =
      p.killStreak > 1
        ? `${p.score.toLocaleString()} (🔥 ${p.killStreak}x STREAK · ${p.getScoreMultiplier().toFixed(1)}x)`
        : `${p.score.toLocaleString()}`;

    if (activeBoss) {
      this.bossBarWrap.style.display = 'block';
      this.bossBarName.textContent = `☠ ${activeBoss.name} (${Math.round(activeBoss.hp)} / ${Math.round(activeBoss.maxHp)})`;
      this.bossBarFill.style.width = `${Math.max(0, Math.min(100, (activeBoss.hp / activeBoss.maxHp) * 100))}%`;
    } else {
      this.bossBarWrap.style.display = 'none';
    }

    const hpPct = Math.max(0, Math.min(100, Math.round((hp / maxHp) * 100)));
    this.hpFill.style.width = `${hpPct}%`;
    this.hpText.textContent = `${Math.round(hp)}/${Math.round(maxHp)}`;

    const boostPct = Math.max(0, Math.min(100, Math.round(boost)));
    this.boostFill.style.width = `${boostPct}%`;
    this.boostText.textContent = `${boostPct}%`;

    this.modeBadge.textContent =
      controlMode === 'jet'
        ? 'AIR FORCE JET'
        : controlMode === 'rover'
        ? VEHICLES[p.vehicle].name.toUpperCase()
        : 'ON FOOT';
    this.speedVal.textContent = `${Math.round(Math.abs(speed) * 3.6)}`;
    this.speedUnit.textContent = controlMode === 'jet' ? 'AIRSPEED KT' : 'KM/H EQUIV';
    this.biomeLabel.textContent = `${planetName} · ${biome}`;

    const wShort: Record<WeaponId, string> = {
      pulse: '1 Pulse',
      katana: '2 Katana',
      scatter: '3 Scatter',
      voidblade: '4 Void',
      nova: '5 Nova',
      rail: '6 Rail',
      warhammer: '7 Hammer',
      spear: '8 Spear',
      dualblades: '9 Dual',
      pickaxe: '0 Pick',
      minigun: '- Vulcan',
      bfg: '= BFG',
    };

    const wPills = WEAPON_ORDER.filter((id) => p.unlockedWeapons.has(id))
      .map((id) => {
        const cls = p.weapon === id ? 'active' : '';
        return `<div class="slot-pill ${cls}">${wShort[id]}</div>`;
      })
      .join('');

    const dashPips = '◆'.repeat(p.dashCharges) + '◇'.repeat(Math.max(0, p.maxDashCharges - p.dashCharges));

    this.loadoutBar.innerHTML = `
      ${wPills}
      <div class="slot-pill ${p.dashCharges > 0 ? 'ready' : ''}">Q ${dashPips}</div>
      <div class="slot-pill ${p.dodgeRollCd <= 0 ? 'ready' : ''}">Z ${p.dodgeRollCd > 0 ? p.dodgeRollCd.toFixed(1) + 's' : 'Roll'}</div>
      <div class="slot-pill ${p.novaCd <= 0 ? 'ready' : ''}">C ${p.novaCd > 0 ? p.novaCd.toFixed(0) + 's' : 'Blast'}</div>
      <div class="slot-pill ${p.shieldCd <= 0 ? 'ready' : ''}">V ${p.shieldCd > 0 ? p.shieldCd.toFixed(0) + 's' : 'Shield'}</div>
    `;

    if (interactText) {
      this.interactPrompt.textContent = interactText;
      this.interactPrompt.style.display = 'block';
    } else {
      this.interactPrompt.style.display = 'none';
    }

    if (this.toastTimer > 0) {
      this.toastTimer -= dt;
      if (this.toastTimer <= 0) this.toastBanner.style.opacity = '0';
    }
    if (this.damageFlash > 0) {
      this.damageFlash = Math.max(0, this.damageFlash - dt * 3.5);
      this.damageVignette.style.opacity = `${this.damageFlash.toFixed(2)}`;
    }

    this.renderMarkers(camera, subjectPos, subjectUp, markers);
  }

  private renderMarkers(
    camera: THREE.Camera,
    subjectPos: THREE.Vector3,
    up: THREE.Vector3,
    markers: WorldMarker[]
  ): void {
    const camFwd = new THREE.Vector3();
    camera.getWorldDirection(camFwd);
    const camTangFwd = camFwd.clone().addScaledVector(up, -camFwd.dot(up));
    if (camTangFwd.lengthSq() < 0.001) {
      camTangFwd.set(0, 0, -1).applyQuaternion(camera.quaternion);
      camTangFwd.addScaledVector(up, -camTangFwd.dot(up));
    }
    if (camTangFwd.lengthSq() < 0.001) camTangFwd.copy(camFwd);
    camTangFwd.normalize();
    const camTangRight = new THREE.Vector3().crossVectors(camTangFwd, up);
    if (camTangRight.lengthSq() < 0.001) camTangRight.set(1, 0, 0);
    else camTangRight.normalize();

    let compassHtml = '';
    let worldHtml = '';
    const proj = new THREE.Vector3();
    const w = window.innerWidth;
    const h = window.innerHeight;
    const usedPcts: number[] = [];
    const placedPins: { x: number; y: number }[] = [];
    const sorted = [...markers].sort((a, b) => (b.priority ? 1 : 0) - (a.priority ? 1 : 0));

    for (const m of sorted) {
      const toMarker = m.worldPos.clone().sub(subjectPos);
      const dist = Math.round(toMarker.length());
      const tang = toMarker.clone().addScaledVector(up, -toMarker.dot(up));
      if (tang.lengthSq() > 0.001) tang.normalize();
      else tang.copy(toMarker).normalize();

      const fwdDot = tang.dot(camTangFwd);
      const rightDot = tang.dot(camTangRight);
      const angle = Math.atan2(rightDot, fwdDot);
      const isPlanet = m.id.startsWith('planet-');

      if (Math.abs(angle) < 1.45 || isPlanet) {
        const pct = THREE.MathUtils.clamp(50 + (angle / 1.45) * 38, 12, 88);
        const minGap = isPlanet ? 16 : 36;
        const overlaps = usedPcts.some((p) => Math.abs(p - pct) < minGap);
        if (!overlaps) {
          usedPcts.push(pct);
          const shortLabel = m.label.length > 20 ? `${m.label.slice(0, 18)}…` : m.label;
          compassHtml += `<div class="compass-marker" style="left:${pct.toFixed(1)}%;color:${m.color}"><span>◆ ${shortLabel}</span><span style="font-size:9px;opacity:0.8">${dist}m</span></div>`;
        }
      }

      if (dist < 115 || m.priority) {
        proj.copy(m.worldPos).project(camera);
        const inFront = proj.z < 1;
        const rawX = (inFront ? proj.x : -proj.x) * 0.5 + 0.5;
        const rawY = (-1 * (inFront ? proj.y : -proj.y)) * 0.5 + 0.5;
        const onScreen = inFront && Math.abs(proj.x) < 0.85 && proj.y > -0.6 && proj.y < 0.85;
        if (onScreen || isPlanet) {
          const sx = THREE.MathUtils.clamp(rawX * w, 315, w - 265);
          let sy = THREE.MathUtils.clamp(rawY * h, 72, h - 75);
          const hitsLeftCard = sx < 305 && sy < 235;
          const hitsRightCard = sx > w - 255 && sy < 195;
          if (!hitsLeftCard && !hitsRightCard) {
            if (placedPins.some((p) => Math.abs(p.x - sx) < 105 && Math.abs(p.y - sy) < 26)) {
              sy = Math.min(h - 60, sy + 28);
            }
            if (!placedPins.some((p) => Math.abs(p.x - sx) < 105 && Math.abs(p.y - sy) < 24)) {
              placedPins.push({ x: sx, y: sy });
              const prefix = !onScreen && isPlanet ? '⌖ ' : '';
              worldHtml += `<div class="world-pin" style="left:${sx.toFixed(0)}px;top:${sy.toFixed(0)}px;color:${m.color}">${prefix}${m.label} (${dist}m)</div>`;
            }
          }
        }
      }
    }

    this.compassMarkers.innerHTML = compassHtml;
    this.worldMarkers.innerHTML = worldHtml;
  }
}
