import * as THREE from 'three';
import {
  PLANETS,
  PlanetConfig,
  SPAWN_DIR,
  evaluateCaveAtDir,
  getPlanetSurfacePosition,
  getPlanetTerrainHeight,
  getTerrainNormal,
  parallelTransport,
  projectOntoTangent,
} from '../math/spherical';
import { getProceduralTextures } from '../rendering/textures';
import { VEHICLES, VehicleId } from '../game/progression';
import { PhysicsWorld, StaticCollider } from '../physics/collision';

export interface RoverInput {
  throttle: number;
  steer: number;
  brake: boolean;
  boost: boolean;
}

export class Rover {
  public readonly group = new THREE.Group();
  public readonly chassis = new THREE.Group();
  public readonly turretPivot = new THREE.Group();
  public readonly barrelTip = new THREE.Object3D();
  public readonly shieldDome: THREE.Mesh;

  public position = new THREE.Vector3();
  public orientation = new THREE.Quaternion();
  public prevUp = new THREE.Vector3(0, 1, 0);
  public velocity = new THREE.Vector3();
  public activePlanet: PlanetConfig = PLANETS[0];

  public forwardSpeed = 0;
  public radialVel = 0;
  public grounded = true;
  public isDrifting = false;
  public boostEnergy = 100;
  public hp = 140;
  public maxHp = 140;
  public vehicleId: VehicleId = 'buggy';
  public lastImpactSpeed = 0;
  public inLava = false;

  private wheels: THREE.Group[] = [];
  private frontSteerPivots: THREE.Group[] = [];
  private thrusterFlames: THREE.Mesh[] = [];
  private bodyMat!: THREE.MeshPhysicalMaterial;
  private accentMat!: THREE.MeshStandardMaterial;
  private spoilerMesh!: THREE.Mesh;
  private wheelSpin = 0;
  private currentSteerAngle = 0;
  private suspBounce = 0;
  private suspVel = 0;
  private bodyRoll = 0;
  private bodyPitch = 0;

  constructor() {
    this.shieldDome = new THREE.Mesh(
      new THREE.IcosahedronGeometry(3.2, 2),
      new THREE.MeshBasicMaterial({
        color: '#4de8ff',
        wireframe: true,
        transparent: true,
        opacity: 0.34,
      })
    );
    this.shieldDome.position.y = 1.0;
    this.shieldDome.visible = false;
    this.group.add(this.shieldDome);

    this.buildSculptedMesh();
    this.respawn();
  }

  public setVehicleType(id: VehicleId, armorBonus = 0): void {
    this.vehicleId = id;
    const spec = VEHICLES[id];
    this.bodyMat.color.set(spec.primaryColor);
    this.accentMat.color.set(spec.accentColor);
    this.accentMat.emissive.set(spec.accentColor);
    this.spoilerMesh.visible = id === 'interceptor';
    const prevMax = this.maxHp;
    this.maxHp = spec.maxHp + armorBonus;
    if (this.maxHp > prevMax) {
      this.hp = Math.min(this.maxHp, this.hp + (this.maxHp - prevMax));
    } else {
      this.hp = Math.min(this.maxHp, this.hp);
    }
  }

  public respawn(planet: PlanetConfig = PLANETS[0], customDir?: THREE.Vector3): void {
    this.activePlanet = planet;
    const dir = (customDir ? customDir.clone() : planet.id === 'aetheria' ? SPAWN_DIR.clone() : new THREE.Vector3(0, 1, 0)).normalize();
    getPlanetSurfacePosition(planet, dir, 1.0, this.position);
    const up = dir.clone();
    this.prevUp.copy(up);

    const targetDir =
      planet.id === 'aetheria'
        ? new THREE.Vector3(0.22, 0.21, 0.952).normalize()
        : Math.abs(up.x) < 0.85
        ? new THREE.Vector3(1, 0, 0)
        : new THREE.Vector3(0, 0, 1);
    const fwd = targetDir.clone().addScaledVector(up, -targetDir.dot(up)).normalize();
    const right = new THREE.Vector3().crossVectors(fwd, up).normalize();
    const mat = new THREE.Matrix4().makeBasis(right, up, fwd.clone().negate());
    this.orientation.setFromRotationMatrix(mat);

    this.forwardSpeed = 0;
    this.radialVel = 0;
    this.velocity.set(0, 0, 0);
    this.hp = this.maxHp;
    this.boostEnergy = 100;
    this.syncTransform();
  }

  private buildSculptedMesh(): void {
    this.group.add(this.chassis);
    const tex = getProceduralTextures();

    this.bodyMat = new THREE.MeshPhysicalMaterial({
      color: '#dde8f5',
      map: tex.metalAlbedo,
      normalMap: tex.metalNormal,
      roughness: 0.34,
      metalness: 0.58,
      clearcoat: 0.42,
      clearcoatRoughness: 0.25,
    });
    const darkMat = new THREE.MeshStandardMaterial({
      color: '#181e28',
      roughness: 0.42,
      metalness: 0.72,
    });
    this.accentMat = new THREE.MeshStandardMaterial({
      color: '#1b9cff',
      emissive: '#0c62b8',
      emissiveIntensity: 1.35,
      roughness: 0.2,
    });
    const glassMat = new THREE.MeshPhysicalMaterial({
      color: '#0c243b',
      emissive: '#0c3050',
      emissiveIntensity: 0.35,
      roughness: 0.05,
      metalness: 0.95,
      clearcoat: 1.0,
    });

    const sideShape = new THREE.Shape();
    sideShape.moveTo(-2.35, 0.45);
    sideShape.lineTo(-2.1, 0.92);
    sideShape.lineTo(-0.85, 1.06);
    sideShape.lineTo(-0.35, 1.56);
    sideShape.lineTo(1.05, 1.56);
    sideShape.lineTo(1.75, 1.15);
    sideShape.lineTo(2.25, 1.05);
    sideShape.lineTo(2.2, 0.5);
    sideShape.lineTo(-2.35, 0.45);

    const bodyGeo = new THREE.ExtrudeGeometry(sideShape, {
      depth: 1.85,
      bevelEnabled: true,
      bevelThickness: 0.14,
      bevelSize: 0.12,
      bevelSegments: 3,
    });
    bodyGeo.center();
    bodyGeo.rotateY(-Math.PI / 2);
    const mainBody = new THREE.Mesh(bodyGeo, this.bodyMat);
    mainBody.position.set(0, 1.02, 0);
    mainBody.castShadow = true;
    mainBody.receiveShadow = true;
    this.chassis.add(mainBody);

    const canopy = new THREE.Mesh(new THREE.SphereGeometry(0.95, 20, 14), glassMat);
    canopy.scale.set(0.88, 0.48, 1.38);
    canopy.position.set(0, 1.36, 0.18);
    this.chassis.add(canopy);

    for (const sx of [-0.88, 0.88]) {
      const curve = new THREE.CatmullRomCurve3([
        new THREE.Vector3(sx, 0.98, -0.95),
        new THREE.Vector3(sx * 0.92, 1.7, -0.25),
        new THREE.Vector3(sx * 0.92, 1.72, 0.95),
        new THREE.Vector3(sx, 1.05, 1.95),
      ]);
      const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 16, 0.065, 8, false), darkMat);
      tube.castShadow = true;
      this.chassis.add(tube);
    }

    for (const sx of [-1.14, 1.14]) {
      const rail = new THREE.Mesh(new THREE.CapsuleGeometry(0.06, 1.35, 6, 8), this.accentMat);
      rail.rotation.x = Math.PI / 2;
      rail.position.set(sx, 0.72, 0);
      this.chassis.add(rail);
    }

    this.spoilerMesh = new THREE.Mesh(new THREE.BoxGeometry(2.45, 0.08, 0.56), this.accentMat);
    this.spoilerMesh.position.set(0, 1.72, 2.05);
    this.spoilerMesh.visible = false;
    this.chassis.add(this.spoilerMesh);

    const hlMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(1.4, 1.55, 1.75) });
    const tlMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(2.2, 0.25, 0.25) });
    for (const sx of [-0.68, 0.68]) {
      const hl = new THREE.Mesh(new THREE.BoxGeometry(0.45, 0.12, 0.12), hlMat);
      hl.position.set(sx, 0.82, -2.5);
      this.chassis.add(hl);
    }
    const tailBar = new THREE.Mesh(new THREE.BoxGeometry(1.75, 0.1, 0.14), tlMat);
    tailBar.position.set(0, 1.05, 2.48);
    this.chassis.add(tailBar);

    const flameMat = new THREE.MeshBasicMaterial({
      color: new THREE.Color(0.4, 2.2, 2.9),
      transparent: true,
      opacity: 0.9,
    });
    for (const sx of [-0.52, 0.52]) {
      const nozzle = new THREE.Mesh(new THREE.LatheGeometry([
        new THREE.Vector2(0.18, 0),
        new THREE.Vector2(0.28, 0.15),
        new THREE.Vector2(0.22, 0.42),
      ], 16), darkMat);
      nozzle.rotation.x = Math.PI / 2;
      nozzle.position.set(sx, 0.78, 2.2);
      this.chassis.add(nozzle);

      const flame = new THREE.Mesh(new THREE.ConeGeometry(0.22, 1.5, 12), flameMat);
      flame.rotation.x = Math.PI / 2;
      flame.position.set(sx, 0.78, 3.15);
      flame.visible = false;
      this.chassis.add(flame);
      this.thrusterFlames.push(flame);
    }

    this.turretPivot.position.set(0, 1.72, 0.1);
    const turretBase = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.54, 0.22, 16), darkMat);
    this.turretPivot.add(turretBase);

    for (const bx of [-0.15, 0.15]) {
      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.08, 1.2, 10), darkMat);
      barrel.rotation.x = Math.PI / 2;
      barrel.position.set(bx, 0.2, -0.45);
      this.turretPivot.add(barrel);

      const glow = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.04, 0.98), this.accentMat);
      glow.position.set(bx, 0.25, -0.5);
      this.turretPivot.add(glow);
    }
    this.barrelTip.position.set(0, 0.22, -1.15);
    this.turretPivot.add(this.barrelTip);
    this.chassis.add(this.turretPivot);

    const wheelGeo = new THREE.CylinderGeometry(0.66, 0.66, 0.56, 28);
    wheelGeo.rotateZ(Math.PI / 2);
    const tireMat = new THREE.MeshStandardMaterial({ color: '#14181f', roughness: 0.85 });
    const rimMat = new THREE.MeshStandardMaterial({
      color: '#6ce5ff',
      emissive: '#0d4e78',
      emissiveIntensity: 0.7,
      metalness: 0.88,
      roughness: 0.18,
    });

    const wheelCoords: [number, number, boolean][] = [
      [-1.38, -1.52, true],
      [1.38, -1.52, true],
      [-1.38, 1.52, false],
      [1.38, 1.52, false],
    ];

    for (const [wx, wz, isFront] of wheelCoords) {
      const strut = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.72, 8), this.accentMat);
      strut.rotation.z = wx < 0 ? -0.48 : 0.48;
      strut.position.set(wx < 0 ? wx + 0.3 : wx - 0.3, 0.92, wz);
      this.chassis.add(strut);

      const steerPivot = new THREE.Group();
      steerPivot.position.set(wx, 0.66, wz);

      const spinGroup = new THREE.Group();
      const tire = new THREE.Mesh(wheelGeo, tireMat);
      tire.castShadow = true;
      spinGroup.add(tire);

      const rim = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.58, 14), rimMat);
      rim.rotation.z = Math.PI / 2;
      spinGroup.add(rim);

      steerPivot.add(spinGroup);
      this.group.add(steerPivot);
      this.wheels.push(spinGroup);
      if (isFront) this.frontSteerPivots.push(steerPivot);
    }
  }

  public getForwardVector(out = new THREE.Vector3()): THREE.Vector3 {
    return out.set(0, 0, -1).applyQuaternion(this.orientation).normalize();
  }

  public getRightVector(out = new THREE.Vector3()): THREE.Vector3 {
    return out.set(1, 0, 0).applyQuaternion(this.orientation).normalize();
  }

  public getUpVector(out = new THREE.Vector3()): THREE.Vector3 {
    return out.copy(this.position).sub(this.activePlanet.center).normalize();
  }

  public launchJumpPad(): void {
    const up = this.getUpVector();
    const fwd = projectOntoTangent(this.getForwardVector(), up).normalize();
    this.radialVel = 21.0;
    this.grounded = false;
    this.velocity.copy(fwd).multiplyScalar(Math.max(this.velocity.length() + 22, 58));
    this.suspVel = -5;
    this.position.addScaledVector(up, 0.45);
  }

  public update(
    dt: number,
    input: RoverInput,
    isOccupied: boolean,
    physics: PhysicsWorld,
    speedMult = 1.0,
    shieldActive = false,
    aimWorldPoint?: THREE.Vector3,
    onTreeCrash?: (col: StaticCollider, impactDir: THREE.Vector3, speed: number) => boolean
  ): void {
    const pCenter = this.activePlanet.center;
    const localPos = this.position.clone().sub(pCenter);
    const up = localPos.clone().normalize();
    parallelTransport(this.orientation, this.prevUp, up);
    projectOntoTangent(this.velocity, up, this.velocity);
    this.prevUp.copy(up);

    this.shieldDome.visible = isOccupied && shieldActive;
    if (this.shieldDome.visible) this.shieldDome.rotation.y += dt * 1.4;

    const spec = VEHICLES[this.vehicleId];
    const boosting = isOccupied && input.boost && this.boostEnergy > 1 && input.throttle > 0.05;
    if (boosting) this.boostEnergy = Math.max(0, this.boostEnergy - 18 * dt);
    else this.boostEnergy = Math.min(100, this.boostEnergy + 28 * dt);

    for (const f of this.thrusterFlames) {
      f.visible = boosting;
      if (boosting) f.scale.set(1, 0.85 + Math.random() * 0.55, 1);
    }

    // Use TANGENT-PROJECTED forward & right vectors so steep mountain pitch NEVER robs drive thrust or locks steering!
    const rawFwd = this.getForwardVector();
    const fwd = projectOntoTangent(rawFwd, up).normalize();
    if (fwd.lengthSq() < 0.001) fwd.set(0, 0, -1);
    const right = new THREE.Vector3().crossVectors(fwd, up).normalize();

    const maxSpeed = (boosting ? spec.boostSpeed : spec.maxSpeed) * speedMult;
    const accel = (boosting ? spec.accel * 1.55 : spec.accel) * speedMult;
    const reverseMax = 20 * speedMult;

    const targetSteerAngle = isOccupied ? input.steer * 0.46 : 0;
    this.currentSteerAngle = THREE.MathUtils.lerp(this.currentSteerAngle, targetSteerAngle, Math.min(1, dt * 14));
    for (const sp of this.frontSteerPivots) sp.rotation.y = this.currentSteerAngle;

    const preFwd = this.velocity.dot(fwd);
    const speedMag = this.velocity.length();
    const speedRatio = Math.min(1, speedMag / 2.2);
    const turnDir = preFwd >= -0.3 ? 1 : -1;
    const preDrift = isOccupied && input.brake && Math.abs(preFwd) > 7 && this.grounded;
    const baseSteerRate = THREE.MathUtils.lerp(2.1, 1.35, Math.min(1, speedMag / 34));
    const steerRate = preDrift ? 2.3 : baseSteerRate;
    const yawDelta = input.steer * steerRate * speedRatio * turnDir * dt;
    if (isOccupied && Math.abs(yawDelta) > 0.00001) {
      const yawQuat = new THREE.Quaternion().setFromAxisAngle(up, yawDelta);
      this.orientation.premultiply(yawQuat).normalize();
    }

    projectOntoTangent(this.getForwardVector(), up, fwd).normalize();
    right.crossVectors(fwd, up).normalize();

    let vFwd = this.velocity.dot(fwd);
    let vLat = this.velocity.dot(right);
    this.isDrifting = isOccupied && input.brake && Math.abs(vFwd) > 7 && this.grounded;

    if (isOccupied) {
      if (input.throttle > 0) {
        if (vFwd < maxSpeed) {
          vFwd = Math.min(maxSpeed, vFwd + accel * input.throttle * dt);
        } else {
          vFwd *= Math.exp(-0.9 * dt);
        }
      } else if (input.throttle < 0) {
        const brakeMult = vFwd > 2 ? 2.6 : 1.15;
        vFwd = Math.max(-reverseMax, vFwd + accel * brakeMult * input.throttle * dt);
      } else {
        vFwd *= Math.exp(-2.1 * dt);
      }

      if (input.brake) {
        vFwd *= Math.exp(-2.4 * dt);
      }
    } else {
      vFwd *= Math.exp(-5.0 * dt);
    }

    // Amphibious hydro-glide in shallow crater water (no sluggish stalling!)
    const terrainHHere = getPlanetTerrainHeight(up, this.activePlanet.id);
    const inWater = terrainHHere < this.activePlanet.seaLevel + 0.05;
    this.inLava = this.activePlanet.id === 'pyros' && inWater;
    if (inWater) vFwd *= Math.exp(-0.18 * dt);

    const lateralGrip = this.grounded ? (this.isDrifting ? 2.6 : 10.5) : 0.45;
    vLat *= Math.exp(-lateralGrip * dt);

    this.velocity.copy(fwd).multiplyScalar(vFwd).addScaledVector(right, vLat);
    this.forwardSpeed = vFwd;

    // Move & resolve collisions — smashing trees at speed >= 6 m/s tears them right down!
    this.position.addScaledVector(this.velocity, dt);
    this.lastImpactSpeed = physics.resolveCollisions(
      this.position,
      this.velocity,
      1.85,
      this.activePlanet,
      (col, impSpd, impDir) => {
        if (impSpd >= 5.5 || boosting) {
          return onTreeCrash ? onTreeCrash(col, impDir, impSpd) : false;
        }
        return false;
      }
    );
    if (this.lastImpactSpeed > 10) {
      this.suspVel -= Math.min(3.5, this.lastImpactSpeed * 0.14);
    }

    // 4-Wheel Footprint Averaged Height + Smooth Hill-Climbing Snap (NO hill stalling!)
    const newLocal = this.position.clone().sub(pCenter);
    const newUp = newLocal.clone().normalize();
    const currentR = newLocal.length();
    const cInfo = this.activePlanet.id === 'aetheria' ? evaluateCaveAtDir(newUp) : null;
    const onExteriorCaveRoof = cInfo !== null && cInfo.inCorridor && cInfo.localZ < -1.5 && currentR >= cInfo.ceilingR - 1.5;

    const wheelOffsets: [number, number][] = [
      [-1.38, 1.52],
      [1.38, 1.52],
      [-1.38, -1.52],
      [1.38, -1.52],
    ];
    const wPts: THREE.Vector3[] = [];
    let avgH = 0;
    for (let i = 0; i < 4; i++) {
      const [wx, wz] = wheelOffsets[i];
      const wDir = newLocal.clone().addScaledVector(right, wx).addScaledVector(fwd, wz).normalize();
      let wh = getPlanetTerrainHeight(wDir, this.activePlanet.id);
      if (onExteriorCaveRoof) {
        const wC = evaluateCaveAtDir(wDir);
        if (wC && wC.inCorridor) wh = Math.max(wh, wC.exteriorR);
      }
      wh = Math.max(this.activePlanet.seaLevel + 0.05, wh);
      avgH += wh;
      wPts.push(wDir.multiplyScalar(wh));
    }
    avgH *= 0.25;

    let centerH = getPlanetTerrainHeight(newUp, this.activePlanet.id);
    if (onExteriorCaveRoof && cInfo) centerH = Math.max(centerH, cInfo.exteriorR);
    const groundR = Math.max(this.activePlanet.seaLevel + 0.05, Math.max(centerH, avgH * 0.92 + centerH * 0.08));
    const wasAirborne = !this.grounded;

    // Gentle hill-hug up to 0.34m so crests launch realistically, while hills never stall!
    if (this.grounded && this.radialVel <= 0 && currentR <= groundR + 0.34) {
      this.position.copy(newUp).multiplyScalar(groundR).add(pCenter);
      this.radialVel = 0;
      this.grounded = true;
    } else if (currentR <= groundR + 0.2 && this.radialVel <= 0) {
      if (wasAirborne && this.radialVel < -5) this.suspVel += this.radialVel * 0.28;
      this.position.copy(newUp).multiplyScalar(groundR).add(pCenter);
      this.radialVel = 0;
      this.grounded = true;
    } else {
      this.radialVel -= this.activePlanet.gravity * 1.25 * dt;
      let nextR = Math.max(groundR, currentR + this.radialVel * dt);
      if (cInfo && cInfo.inCorridor && cInfo.localZ < -1.5 && currentR < cInfo.ceilingR - 1.0) {
        const maxRoof = cInfo.ceilingR - 1.8;
        if (nextR > maxRoof) {
          nextR = maxRoof;
          this.radialVel = Math.min(0, this.radialVel);
        }
      }
      this.position.copy(newUp).multiplyScalar(nextR).add(pCenter);
      this.grounded = nextR <= groundR + 0.25;
      if (this.grounded) {
        if (wasAirborne && this.radialVel < -5) this.suspVel += this.radialVel * 0.28;
        this.radialVel = 0;
      }
    }

    // Smooth Tire-Plane + Terrain Normal alignment for silky hill-climbing orientation
    const nextInWater = centerH < this.activePlanet.seaLevel + 0.05;
    let alignNormal = newUp;
    if (!nextInWater) {
      const tNorm = getTerrainNormal(newUp, new THREE.Vector3(), this.activePlanet.id);
      const diagA = wPts[1].clone().sub(wPts[2]);
      const diagB = wPts[0].clone().sub(wPts[3]);
      const wheelNorm = new THREE.Vector3().crossVectors(diagB, diagA).normalize();
      if (wheelNorm.dot(newUp) < 0) wheelNorm.negate();
      alignNormal = wheelNorm.lerp(tNorm, 0.35).normalize();
    }

    if (this.grounded) {
      const projectedFwd = fwd.clone().addScaledVector(alignNormal, -fwd.dot(alignNormal));
      if (projectedFwd.lengthSq() > 0.001) {
        projectedFwd.normalize();
        const projectedRight = new THREE.Vector3().crossVectors(projectedFwd, alignNormal).normalize();
        const targetMat = new THREE.Matrix4().makeBasis(projectedRight, alignNormal, projectedFwd.clone().negate());
        const targetQuat = new THREE.Quaternion().setFromRotationMatrix(targetMat);
        this.orientation.slerp(targetQuat, Math.min(1, dt * 11));
      }
    }

    this.suspVel += (-this.suspBounce * 85 - this.suspVel * 11) * dt;
    this.suspBounce = THREE.MathUtils.clamp(this.suspBounce + this.suspVel * dt, -0.28, 0.25);

    const targetRoll = isOccupied ? -input.steer * Math.min(1, Math.abs(vFwd) / 26) * 0.09 : 0;
    const targetPitch = boosting ? 0.05 : isOccupied && input.throttle < 0 ? -0.045 : 0;
    this.bodyRoll = THREE.MathUtils.lerp(this.bodyRoll, targetRoll, Math.min(1, dt * 10));
    this.bodyPitch = THREE.MathUtils.lerp(this.bodyPitch, targetPitch, Math.min(1, dt * 8));
    this.chassis.position.y = this.suspBounce;
    this.chassis.rotation.z = this.bodyRoll;
    this.chassis.rotation.x = this.bodyPitch;

    for (let i = 0; i < this.wheels.length; i++) {
      const delta = THREE.MathUtils.clamp((wPts[i].length() - groundR) * 0.22, -0.16, 0.18);
      this.wheels[i].parent!.position.y = 0.66 + delta;
    }

    this.wheelSpin -= (vFwd * dt) / 0.66;
    for (const w of this.wheels) w.rotation.x = this.wheelSpin;

    this.syncTransform();
    this.group.updateMatrixWorld(true);

    if (isOccupied && aimWorldPoint) {
      const localTarget = this.chassis.worldToLocal(aimWorldPoint.clone());
      const dx = localTarget.x - this.turretPivot.position.x;
      const dz = localTarget.z - this.turretPivot.position.z;
      this.turretPivot.rotation.y = Math.atan2(-dx, -dz);
    }
  }

  public getDriverExitPosition(physics?: PhysicsWorld, out = new THREE.Vector3()): THREE.Vector3 {
    const right = this.getRightVector();
    const fwd = this.getForwardVector();
    const pCenter = this.activePlanet.center;
    const candidates = [
      this.position.clone().addScaledVector(right, -3.0),
      this.position.clone().addScaledVector(right, 3.0),
      this.position.clone().addScaledVector(fwd, -3.4),
    ];
    for (const c of candidates) {
      const dir = c.sub(pCenter).normalize();
      const pos = getPlanetSurfacePosition(this.activePlanet, dir, 0.1);
      if (!physics) return out.copy(pos);
      const tmpVel = new THREE.Vector3();
      const testPos = pos.clone();
      physics.resolveCollisions(testPos, tmpVel, 0.7, this.activePlanet);
      if (testPos.distanceTo(pos) < 0.8) return out.copy(testPos);
    }
    const dir = candidates[0].sub(pCenter).normalize();
    return out.copy(getPlanetSurfacePosition(this.activePlanet, dir, 0.1));
  }

  public getCameraAnchor(out = new THREE.Vector3()): THREE.Vector3 {
    const up = this.getUpVector();
    return out.copy(this.position).addScaledVector(up, 2.2);
  }

  public getBarrelWorldPos(out = new THREE.Vector3()): THREE.Vector3 {
    this.group.updateMatrixWorld(true);
    return this.barrelTip.getWorldPosition(out);
  }

  public isNear(point: THREE.Vector3, maxDist = 5.8): boolean {
    return this.position.distanceTo(point) <= maxDist;
  }

  private syncTransform(): void {
    this.group.position.copy(this.position);
    this.group.quaternion.copy(this.orientation);
  }
}
