    spearTip.rotation.x = -Math.PI / 2;
    spearTip.position.set(0, -0.44, -2.0);
    this.spearGroup.add(spearTip);
    this.spearGroup.visible = false;
    this.rightArm.add(this.spearGroup);

    this.dualBladesGroup = new THREE.Group();
    const dbMat = new THREE.MeshStandardMaterial({ color: '#cc55ff', emissive: '#9933cc', emissiveIntensity: 2.0, roughness: 0.1, metalness: 0.8 });
