    const pickHandle = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 1.1, 8), underMat);
    pickHandle.rotation.x = Math.PI / 2;
    pickHandle.position.set(0, -0.44, -0.45);
    this.pickaxeGroup.add(pickHandle);
    const pickHead = new THREE.Mesh(
      new THREE.BoxGeometry(0.06, 0.06, 0.65),
      new THREE.MeshStandardMaterial({ color: '#55ccff', emissive: '#2299dd', emissiveIntensity: 1.5, roughness: 0.2, metalness: 0.85 })
    );
    pickHead.position.set(0, -0.44, -1.1);
