import * as THREE from 'three';
import {
  PLANETS,
  PlanetConfig,
  getNearestPlanet,
  getPlanetSurfacePosition,
  getPlanetTerrainHeight,
} from '../math/spherical';
import { getProceduralTextures } from '../rendering/textures';

export interface JetInput {
  throttle: number; // +1 forward, -1 airbrake
  bank: number; // A/D roll & yaw turn
  hoverUp: boolean; // Spacebar VTOL lift
  afterburner: boolean; // Shift supersonic Mach drive
  firing: boolean;
}

/**
 * Valkyrie F-22X Air Force Strike Fighter Jet —
 * Full planetary VTOL & Interplanetary Space Flight across Aetheria, Aurelia, Pyros & Glacies!
 */
export class AirForceJet {
  public readonly group = new THREE.Group();
  public readonly fuselage = new THREE.Group();
  public readonly muzzleLeft = new THREE.Object3D();
  public readonly muzzleRight = new THREE.Object3D();

  public position = new THREE.Vector3();
  public orientation = new THREE.Quaternion();
  public velocity = new THREE.Vector3();
  public speed = 0;
  public hp = 260;
  public maxHp = 260;
  public landed = true;
  public activePlanet: PlanetConfig = PLANETS[0];

  private flames: THREE.Mesh[] = [];
  private machRing!: THREE.Mesh;
  public navUp = new THREE.Vector3(0, 1, 0);
  private prevFwd = new THREE.Vector3(0, 0, -1);

  constructor(parkPos: THREE.Vector3) {
    this.buildFighterMesh();
    this.placeAt(parkPos, PLANETS[0]);
  }

  public placeAt(pos: THREE.Vector3, planet: PlanetConfig): void {
    this.activePlanet = planet;
    this.position.copy(pos);
    const up = pos.clone().sub(planet.center).normalize();
    const ref = Math.abs(up.y) < 0.9 ? new THREE.Vector3(0, 1, 0) : new THREE.Vector3(1, 0, 0);
    const fwd = new THREE.Vector3().crossVectors(ref, up).normalize();
    const right = new THREE.Vector3().crossVectors(fwd, up).normalize();
    this.orientation.setFromRotationMatrix(new THREE.Matrix4().makeBasis(right, up, fwd.clone().negate()));
    this.navUp.copy(up);
    this.prevFwd.copy(fwd);
    this.velocity.set(0, 0, 0);
    this.speed = 0;
    this.landed = true;
    this.syncTransform();
  }

  private buildFighterMesh(): void {
    this.group.add(this.fuselage);
    const tex = getProceduralTextures();

    const hullMat = new THREE.MeshPhysicalMaterial({
      color: '#253142',
      map: tex.metalAlbedo,
      normalMap: tex.metalNormal,
      roughness: 0.28,
      metalness: 0.78,
      clearcoat: 0.65,
    });
    const wingMat = new THREE.MeshPhysicalMaterial({
      color: '#192230',
      roughness: 0.34,
      metalness: 0.72,
      clearcoat: 0.5,
    });
    const trimMat = new THREE.MeshStandardMaterial({
      color: '#38e8ff',
      emissive: '#0c9ee0',
      emissiveIntensity: 1.8,
    });
    const canopyMat = new THREE.MeshPhysicalMaterial({
      color: '#ffd982',
      emissive: '#332200',
      emissiveIntensity: 0.25,
      roughness: 0.05,
      metalness: 0.9,
      clearcoat: 1.0,
    });

    // Sleek Chined Stealth Fuselage
    const fuseGeo = new THREE.CylinderGeometry(0.42, 0.78, 7.6, 8);
    fuseGeo.rotateX(Math.PI / 2);
    const fuseMesh = new THREE.Mesh(fuseGeo, hullMat);
    fuseMesh.scale.set(1.35, 0.58, 1);
    fuseMesh.position.y = 0.85;
    fuseMesh.castShadow = true;
    this.fuselage.add(fuseMesh);

    // Sharp Fighter Nose Cone (-Z forward)
    const nose = new THREE.Mesh(new THREE.ConeGeometry(0.55, 2.8, 8), hullMat);
    nose.rotation.x = -Math.PI / 2;
    nose.scale.set(1.25, 1.0, 0.6);
    nose.position.set(0, 0.82, -4.9);
    nose.castShadow = true;
    this.fuselage.add(nose);

    // Golden-Tinted Bubble Fighter Canopy
    const canopy = new THREE.Mesh(new THREE.SphereGeometry(0.65, 16, 12), canopyMat);
    canopy.scale.set(0.78, 0.62, 2.35);
    canopy.position.set(0, 1.24, -1.9);
    this.fuselage.add(canopy);

    // Swept Delta Main Wings (ExtrudeGeometry)
    const wingShape = new THREE.Shape();
    wingShape.moveTo(0.55, -1.3);
    wingShape.lineTo(4.6, 1.85);
    wingShape.lineTo(4.6, 2.65);
    wingShape.lineTo(0.65, 2.25);
    wingShape.closePath();
    const wGeo = new THREE.ExtrudeGeometry(wingShape, { depth: 0.09, bevelEnabled: true, bevelThickness: 0.03, bevelSize: 0.04 });
    wGeo.rotateX(Math.PI / 2);

    const rightWing = new THREE.Mesh(wGeo, wingMat);
    rightWing.position.set(0, 0.88, 0.2);
    rightWing.castShadow = true;
    this.fuselage.add(rightWing);

    const leftWing = rightWing.clone();
    leftWing.scale.x = -1;
    this.fuselage.add(leftWing);

    // Wingtip Laser Pods & Nav Lights
    for (const sx of [-4.55, 4.55]) {
      const missile = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 1.7, 8), hullMat);
      missile.rotation.x = Math.PI / 2;
      missile.position.set(sx, 0.82, 2.2);
      this.fuselage.add(missile);

      const nav = new THREE.Mesh(
        new THREE.SphereGeometry(0.11, 8, 8),
        new THREE.MeshBasicMaterial({ color: sx < 0 ? '#ff3855' : '#38ff99' })
      );
      nav.position.set(sx, 0.86, 1.3);
      this.fuselage.add(nav);
    }

    // Twin Canted Vertical Stabilizer Fins
    for (const sx of [-1, 1]) {
      const fin = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.55, 1.85), wingMat);
      fin.position.set(sx * 1.15, 1.55, 2.65);
      fin.rotation.z = sx * -0.35;
      fin.rotation.x = 0.25;
      fin.castShadow = true;
      this.fuselage.add(fin);

      const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 1.4), trimMat);
      stripe.position.set(sx * 1.28, 1.95, 2.75);
      stripe.rotation.z = sx * -0.35;
      this.fuselage.add(stripe);
    }

    // Twin Jet Afterburners & Mach Shockwave Ring
    const flameMat = new THREE.MeshBasicMaterial({
      color: new THREE.Color(0.5, 2.3, 3.2),
      transparent: true,
      opacity: 0.92,
      blending: THREE.AdditiveBlending,
    });
    for (const nx of [-0.55, 0.55]) {
      const nozzle = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.36, 0.8, 12), wingMat);
      nozzle.rotation.x = Math.PI / 2;
      nozzle.position.set(nx, 0.82, 3.65);
      this.fuselage.add(nozzle);

      const flame = new THREE.Mesh(new THREE.ConeGeometry(0.28, 2.6, 12), flameMat);
      flame.rotation.x = Math.PI / 2;
      flame.position.set(nx, 0.82, 5.2);
      flame.visible = false;
      this.fuselage.add(flame);
      this.flames.push(flame);
    }

    this.machRing = new THREE.Mesh(
      new THREE.TorusGeometry(2.6, 0.08, 8, 36),
      new THREE.MeshBasicMaterial({
        color: '#8ef5ff',
        transparent: true,
        opacity: 0.35,
        blending: THREE.AdditiveBlending,
      })
    );
    this.machRing.position.set(0, 0.85, 0.8);
    this.machRing.visible = false;
    this.fuselage.add(this.machRing);

    // Under-wing Rotary Vulcan Muzzles
    this.muzzleLeft.position.set(-1.5, 0.72, -1.6);
    this.muzzleRight.position.set(1.5, 0.72, -1.6);
    this.fuselage.add(this.muzzleLeft, this.muzzleRight);
  }

  public getForwardVector(out = new THREE.Vector3()): THREE.Vector3 {
    return out.set(0, 0, -1).applyQuaternion(this.orientation).normalize();
  }

  public getUpVector(out = new THREE.Vector3()): THREE.Vector3 {
    return out.set(0, 1, 0).applyQuaternion(this.orientation).normalize();
  }

  public getRightVector(out = new THREE.Vector3()): THREE.Vector3 {
    return out.set(1, 0, 0).applyQuaternion(this.orientation).normalize();
  }

  public getCameraAnchor(out = new THREE.Vector3()): THREE.Vector3 {
    const up = this.getUpVector();
    return out.copy(this.position).addScaledVector(up, 1.5);
  }

  public getMuzzlesWorldPos(): [THREE.Vector3, THREE.Vector3] {
    this.group.updateMatrixWorld(true);
    return [this.muzzleLeft.getWorldPosition(new THREE.Vector3()), this.muzzleRight.getWorldPosition(new THREE.Vector3())];
  }

  public isNear(pt: THREE.Vector3, maxDist = 7.5): boolean {
    return this.position.distanceTo(pt) <= maxDist;
  }

  public update(dt: number, input: JetInput, isOccupied: boolean, desiredAimDir: THREE.Vector3, speedMult = 1.0): void {
    const nearest = getNearestPlanet(this.position);
    this.activePlanet = nearest.planet;
    const localPos = this.position.clone().sub(this.activePlanet.center);
    const planetUp = localPos.clone().normalize();
    const groundR = Math.max(this.activePlanet.seaLevel + 0.25, getPlanetTerrainHeight(planetUp, this.activePlanet.id));
    const currentR = localPos.length();
    const altAboveSurface = currentR - groundR;

    if (!isOccupied) {
      // Parked smoothly on surface
      if (altAboveSurface > 0.25) {
        this.velocity.addScaledVector(planetUp, -18 * dt);
        this.position.addScaledVector(this.velocity, dt);
        const nL = this.position.clone().sub(this.activePlanet.center);
        const nUp = nL.clone().normalize();
        const gR = Math.max(this.activePlanet.seaLevel + 0.25, getPlanetTerrainHeight(nUp, this.activePlanet.id));
        if (nL.length() <= gR + 0.25) {
          this.position.copy(getPlanetSurfacePosition(this.activePlanet, nUp, 0.25));
          this.velocity.set(0, 0, 0);
          this.landed = true;
        }
      } else {
        this.velocity.set(0, 0, 0);
        this.landed = true;
      }
      for (const f of this.flames) f.visible = false;
      this.machRing.visible = false;
      this.speed = this.velocity.length();
      this.syncTransform();
      return;
    }

    // Active Flight Control!
    const targetMaxSpd = (input.afterburner ? 138 : 72) * speedMult;
    const fwd = this.getForwardVector();

    // Smooth gimbal-lock-free reference Up: tracks flight pitch in deep space & gently aligns to planet gravity near surfaces!
    const steerDir = desiredAimDir.clone().normalize();
    if (altAboveSurface < 2.0 && steerDir.dot(planetUp) < 0) {
      steerDir.addScaledVector(planetUp, -steerDir.dot(planetUp) + 0.15).normalize();
    }

    if (this.prevFwd.dot(steerDir) < 0.999999) {
      const dQ = new THREE.Quaternion().setFromUnitVectors(this.prevFwd, steerDir);
      this.navUp.applyQuaternion(dQ).normalize();
    }
    this.prevFwd.copy(steerDir);

    // Near planet atmosphere (< 85m), softly pull navUp toward planetUp (unless flying nearly vertically where cross is tiny!)
    const nearPlanetBlend = 1 - Math.max(0, Math.min(1, (altAboveSurface - 30) / 55));
    if (nearPlanetBlend > 0.01 && Math.abs(steerDir.dot(planetUp)) < 0.9) {
      this.navUp.lerp(planetUp, nearPlanetBlend * Math.min(1, dt * 4.5)).normalize();
    }
    // Keep navUp orthogonal to steerDir
    this.navUp.addScaledVector(steerDir, -this.navUp.dot(steerDir));
    if (this.navUp.lengthSq() < 0.001) this.navUp.copy(this.getUpVector());
    this.navUp.normalize();

    const right = new THREE.Vector3().crossVectors(steerDir, this.navUp).normalize();
    const desiredUp = new THREE.Vector3().crossVectors(right, steerDir).normalize();

    // Wing bank visual roll (strictly on the jet model, NEVER flipping horizon camera!)
    const turnSide = steerDir.dot(this.getRightVector());
    const rollAngle = THREE.MathUtils.clamp(-turnSide * 1.1 - input.bank * 0.8, -1.05, 1.05);
    const bankQuat = new THREE.Quaternion().setFromAxisAngle(steerDir, rollAngle);
    desiredUp.applyQuaternion(bankQuat);

    const targetMat = new THREE.Matrix4().makeBasis(
      new THREE.Vector3().crossVectors(steerDir, desiredUp).normalize(),
      desiredUp,
      steerDir.clone().negate()
    );
    const targetQuat = new THREE.Quaternion().setFromRotationMatrix(targetMat);
    this.orientation.slerp(targetQuat, Math.min(1, dt * (this.landed ? 3.5 : 5.5)));

    // VTOL Lift & Throttle
    this.getForwardVector(fwd);
    let targetSpeed = 0;
    if (input.afterburner) {
      targetSpeed = targetMaxSpd;
      this.landed = false;
    } else if (input.throttle > 0) {
      targetSpeed = 68 * speedMult;
      this.landed = false;
    } else if (input.throttle < 0) {
      targetSpeed = 14;
    } else {
      targetSpeed = this.landed ? 0 : 42 * speedMult;
    }

    const curForwardSpd = this.velocity.dot(fwd);
    const nextForwardSpd = THREE.MathUtils.lerp(curForwardSpd, targetSpeed, Math.min(1, dt * 3.2));
    this.velocity.lerp(fwd.clone().multiplyScalar(nextForwardSpd), Math.min(1, dt * 5.0));

    // VTOL Vertical Ascent [Space]
    if (input.hoverUp) {
      this.landed = false;
      this.velocity.addScaledVector(planetUp, 36 * dt);
    } else if (altAboveSurface < 1.2 && nextForwardSpd < 18) {
      this.landed = true;
    }

    // Also allow banking turn impulse from A/D directly
    if (Math.abs(input.bank) > 0.01 && !this.landed) {
      const jetUp = this.getUpVector();
      const bankTurn = new THREE.Quaternion().setFromAxisAngle(jetUp, input.bank * 1.6 * dt);
      this.orientation.premultiply(bankTurn).normalize();
    }

    this.position.addScaledVector(this.velocity, dt);
    this.speed = this.velocity.length();

    // Prevent tunneling underground on any planet!
    const postNearest = getNearestPlanet(this.position);
    this.activePlanet = postNearest.planet;
    const pLocal = this.position.clone().sub(this.activePlanet.center);
    const pUp = pLocal.clone().normalize();
    const minAlt = Math.max(this.activePlanet.seaLevel + 0.35, getPlanetTerrainHeight(pUp, this.activePlanet.id)) + 0.4;
    if (pLocal.length() < minAlt) {
      this.position.copy(pUp).multiplyScalar(minAlt).add(this.activePlanet.center);
      const vn = this.velocity.dot(pUp);
      if (vn < 0) this.velocity.addScaledVector(pUp, -vn * 1.05);
      if (this.speed < 22 && !input.hoverUp) this.landed = true;
    }

    // Visual jet flames & Mach shockwave
    const showFlame = isOccupied && (input.throttle > 0 || input.afterburner || input.hoverUp || this.speed > 20);
    for (const f of this.flames) {
      f.visible = showFlame;
      if (showFlame) {
        const len = input.afterburner ? 1.7 + Math.random() * 0.5 : 0.75 + Math.random() * 0.25;
        f.scale.set(input.afterburner ? 1.35 : 0.9, len, input.afterburner ? 1.35 : 0.9);
      }
    }
    this.machRing.visible = input.afterburner && this.speed > 85;
    if (this.machRing.visible) this.machRing.rotation.z += dt * 8;

    this.syncTransform();
  }

  private syncTransform(): void {
    this.group.position.copy(this.position);
    this.group.quaternion.copy(this.orientation);
  }
}
