import * as THREE from 'three';
import {
  PLANETS,
  PlanetConfig,
  PlanetId,
  getPlanetSurfacePosition,
  getPlanetTerrainHeight,
} from '../math/spherical';
import { getProceduralTextures } from '../rendering/textures';
import { WeaponId } from '../game/progression';

export interface OffworldCitadel {
  planet: PlanetConfig;
  center: THREE.Vector3;
  coreMesh: THREE.Mesh;
  coreRing: THREE.Mesh;
  hp: number;
  maxHp: number;
  cleared: boolean;
  waveSpawned: boolean;
}

export interface OffworldChest {
  id: string;
  planetId: PlanetId;
  pos: THREE.Vector3;
  lidPivot: THREE.Group;
  light: THREE.PointLight;
  opened: boolean;
  rewardWeapon?: WeaponId;
  shards: number;
  label: string;
}

export interface OffworldCrystal {
  planetId: PlanetId;
  pos: THREE.Vector3;
  mesh: THREE.Mesh;
  hp: number;
  destroyed: boolean;
}

export interface MultiPlanetSystem {
  group: THREE.Group;
  citadels: OffworldCitadel[];
  chests: OffworldChest[];
  crystals: OffworldCrystal[];
  update(time: number, sunDir: THREE.Vector3): void;
}

function buildDisplacedPlanetMesh(
  planet: PlanetConfig,
  colorFn: (h: number, dir: THREE.Vector3, out: THREE.Color) => void,
  matProps: THREE.MeshStandardMaterialParameters
): THREE.Mesh {
  const geo = new THREE.IcosahedronGeometry(planet.radius, 5);
  const pos = geo.attributes.position as THREE.BufferAttribute;
  const colArr = new Float32Array(pos.count * 3);
  const dir = new THREE.Vector3();
  const c = new THREE.Color();

  for (let i = 0; i < pos.count; i++) {
    dir.fromBufferAttribute(pos, i).normalize();
    const h = getPlanetTerrainHeight(dir, planet.id);
    pos.setXYZ(i, dir.x * h, dir.y * h, dir.z * h);
    colorFn(h, dir, c);
    colArr[i * 3] = c.r;
    colArr[i * 3 + 1] = c.g;
    colArr[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colArr, 3));
  geo.computeVertexNormals();

  const mesh = new THREE.Mesh(
    geo,
    new THREE.MeshStandardMaterial({
      vertexColors: true,
      ...matProps,
    })
  );
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

export function createOffworldPlanets(sunDir: THREE.Vector3): MultiPlanetSystem {
  const group = new THREE.Group();
  const tex = getProceduralTextures();
  const upRef = new THREE.Vector3(0, 1, 0);
  const sunUniform = { value: sunDir.clone().normalize() };

  const citadels: OffworldCitadel[] = [];
  const chests: OffworldChest[] = [];
  const crystals: OffworldCrystal[] = [];

  // Shared chest materials
  const chestMat = new THREE.MeshPhysicalMaterial({
    color: '#202b3d',
    map: tex.metalAlbedo,
    normalMap: tex.metalNormal,
    roughness: 0.28,
    metalness: 0.78,
    clearcoat: 0.6,
  });
  const goldTrimMat = new THREE.MeshStandardMaterial({
    color: '#ffd666',
    emissive: '#a66f0c',
    emissiveIntensity: 1.2,
    metalness: 0.9,
    roughness: 0.2,
  });

  const addChestOnPlanet = (
    id: string,
    planet: PlanetConfig,
    dir: THREE.Vector3,
    rewardWeapon: WeaponId | undefined,
    shards: number,
    label: string
  ) => {
    const pos = getPlanetSurfacePosition(planet, dir, 0);
    const holder = new THREE.Group();
    holder.position.copy(pos);
    holder.quaternion.setFromUnitVectors(upRef, dir.clone().normalize());

    const base = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.95, 1.35), chestMat);
    base.position.y = 0.48;
    holder.add(base);
    const band = new THREE.Mesh(new THREE.BoxGeometry(2.08, 0.16, 1.42), goldTrimMat);
    band.position.y = 0.86;
    holder.add(band);

    const lidPivot = new THREE.Group();
    lidPivot.position.set(0, 0.95, -0.65);
    const lid = new THREE.Mesh(new THREE.CylinderGeometry(0.68, 0.68, 2.02, 12, 1, false, 0, Math.PI), chestMat);
    lid.rotation.z = Math.PI / 2;
    lid.position.set(0, 0, 0.65);
    lidPivot.add(lid);
    holder.add(lidPivot);

    const light = new THREE.PointLight('#ffd666', 10, 22);
    light.position.y = 1.8;
    holder.add(light);

    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.16, 0.42, 14, 10, 1, true),
      new THREE.MeshBasicMaterial({
        color: '#ffd666',
        transparent: true,
        opacity: 0.32,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      })
    );
    beam.position.y = 7.2;
    holder.add(beam);

    group.add(holder);
    chests.push({ id, planetId: planet.id, pos, lidPivot, light, opened: false, rewardWeapon, shards, label });
  };

  // ============================================================================
  // 1. AURELIA RINGWORLD — Explorable Amber Dunes & Golden Floating Ring System
  // ============================================================================
  const aurelia = PLANETS[1];
  const aureliaGroup = new THREE.Group();
  aureliaGroup.position.copy(aurelia.center);
  aureliaGroup.add(
    buildDisplacedPlanetMesh(
      aurelia,
      (h, _d, out) => {
        const t = THREE.MathUtils.clamp((h - aurelia.radius) / 10, -0.3, 1);
        out.setRGB(0.75 + t * 0.2, 0.56 + t * 0.22, 0.34 + t * 0.15);
      },
      { map: tex.sandAlbedo, normalMap: tex.rockNormal, roughness: 0.72, metalness: 0.08 }
    )
  );
  // Liquid gold basin sea
  aureliaGroup.add(
    new THREE.Mesh(
      new THREE.SphereGeometry(aurelia.seaLevel, 32, 24),
      new THREE.MeshPhysicalMaterial({
        color: '#c98828',
        emissive: '#3b2104',
        roughness: 0.12,
        metalness: 0.65,
        clearcoat: 1.0,
      })
    )
  );
  // Dramatic Banded Rings (stationary with respect to planet rotation axis!)
  const auRingGeo = new THREE.RingGeometry(110, 178, 96, 1);
  const auRingMat = new THREE.ShaderMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
    uniforms: { uInner: { value: 110 }, uOuter: { value: 178 }, uSunDir: sunUniform },
    vertexShader: `
      varying vec3 vL;
      void main() {
        vL = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vL;
      uniform float uInner;
      uniform float uOuter;
      void main() {
        float r = length(vL.xy);
        float t = clamp((r - uInner) / (uOuter - uInner), 0.0, 1.0);
        float bands = sin(t * 42.0) * 0.35 + sin(t * 14.0) * 0.35 + 0.5;
        float gap = smoothstep(0.02, 0.06, abs(t - 0.56));
        float fade = smoothstep(0.0, 0.12, t) * (1.0 - smoothstep(0.84, 1.0, t));
        vec3 col = mix(vec3(0.95, 0.78, 0.48), vec3(0.45, 0.82, 1.0), t);
        gl_FragColor = vec4(col, clamp(bands * gap * fade * 0.68, 0.0, 0.75));
      }
    `,
  });
  const auRing = new THREE.Mesh(auRingGeo, auRingMat);
  auRing.rotation.set(Math.PI * 0.42, 0.25, -0.35);
  aureliaGroup.add(auRing);
  group.add(aureliaGroup);

  // ============================================================================
  // 2. PYROS MAGMA FORGE — Basalt Plates + Glowing Molten Lava Sea!
  // ============================================================================
  const pyros = PLANETS[2];
  const pyrosGroup = new THREE.Group();
  pyrosGroup.position.copy(pyros.center);
  pyrosGroup.add(
    buildDisplacedPlanetMesh(
      pyros,
      (h, _d, out) => {
        const t = THREE.MathUtils.clamp((h - pyros.radius) / 7, -0.5, 1);
        out.setRGB(0.18 + Math.max(0, -t) * 0.2, 0.13, 0.14);
      },
      { map: tex.rockAlbedo, normalMap: tex.rockNormal, roughness: 0.84, metalness: 0.22 }
    )
  );
  const lavaMat = new THREE.MeshStandardMaterial({
    color: '#ff521b',
    emissive: '#ff3608',
    emissiveIntensity: 2.3,
    roughness: 0.25,
  });
  pyrosGroup.add(new THREE.Mesh(new THREE.SphereGeometry(pyros.seaLevel, 32, 24), lavaMat));
  group.add(pyrosGroup);

  // ============================================================================
  // 3. GLACIES CRYO MOON — Crystalline Ice & Glowing Glacial Shards
  // ============================================================================
  const glacies = PLANETS[3];
  const glaciesGroup = new THREE.Group();
  glaciesGroup.position.copy(glacies.center);
  glaciesGroup.add(
    buildDisplacedPlanetMesh(
      glacies,
      (h, _d, out) => {
        const t = THREE.MathUtils.clamp((h - glacies.radius) / 5, -0.3, 1);
        out.setRGB(0.65 + t * 0.3, 0.85 + t * 0.14, 0.96);
      },
      { map: tex.rockAlbedo, normalMap: tex.rockNormal, roughness: 0.28, metalness: 0.15 }
    )
  );
  glaciesGroup.add(
    new THREE.Mesh(
      new THREE.SphereGeometry(glacies.seaLevel, 32, 24),
      new THREE.MeshPhysicalMaterial({
        color: '#6ce2ff',
        emissive: '#0c3a54',
        roughness: 0.08,
        metalness: 0.2,
        clearcoat: 1.0,
      })
    )
  );
  group.add(glaciesGroup);

  // ============================================================================
  // POPULATE ALL 3 OFF-WORLD PLANETS WITH CITADELS, CHESTS & CRYSTALS!
  // ============================================================================
  const spireMat = new THREE.MeshPhysicalMaterial({ color: '#1b2638', roughness: 0.3, metalness: 0.8 });
  const offPlanets: { planet: PlanetConfig; chestWeapon: WeaponId; chestLabel: string; crystalCol: string }[] = [
    { planet: aurelia, chestWeapon: 'bfg', chestLabel: 'Aether Obliterator (BFG)!', crystalCol: '#ffd666' },
    { planet: pyros, chestWeapon: 'warhammer', chestLabel: 'Titan Warhammer (Volcanic Forged)!', crystalCol: '#ff6e38' },
    { planet: glacies, chestWeapon: 'minigun', chestLabel: 'Vulcan Rotary Cannon!', crystalCol: '#6cf2ff' },
  ];

  offPlanets.forEach((op, idx) => {
    const { planet } = op;
    // Citadel on sun-lit hemisphere facing Aetheria Prime for awesome dramatic approach!
    const citDir = PLANETS[0].center.clone().sub(planet.center).normalize();
    citDir.y += 0.35;
    citDir.normalize();

    const citPos = getPlanetSurfacePosition(planet, citDir, 0);
    const citHolder = new THREE.Group();
    citHolder.position.copy(citPos);
    citHolder.quaternion.setFromUnitVectors(upRef, citDir);

    const base = new THREE.Mesh(new THREE.CylinderGeometry(4.2, 5.4, 1.4, 12), spireMat);
    base.position.y = 0.7;
    citHolder.add(base);

    const coreMat = new THREE.MeshStandardMaterial({
      color: planet.accentColor,
      emissive: planet.accentColor,
      emissiveIntensity: 2.3,
      roughness: 0.15,
    });
    const coreMesh = new THREE.Mesh(new THREE.OctahedronGeometry(1.9, 1), coreMat);
    coreMesh.position.y = 4.6;
    citHolder.add(coreMesh);

    const coreRing = new THREE.Mesh(
      new THREE.TorusGeometry(3.1, 0.22, 10, 32),
      new THREE.MeshBasicMaterial({ color: planet.accentColor })
    );
    coreRing.position.y = 4.6;
    citHolder.add(coreRing);

    const light = new THREE.PointLight(planet.accentColor, 18, 48);
    light.position.y = 6.0;
    citHolder.add(light);

    group.add(citHolder);
    citadels.push({
      planet,
      center: citPos,
      coreMesh,
      coreRing,
      hp: 380,
      maxHp: 380,
      cleared: false,
      waveSpawned: false,
    });

    // 2 Treasure Chests per Off-World Planet!
    const perp = new THREE.Vector3(1, 0, 0).cross(citDir).normalize();
    const chestDirA = citDir.clone().addScaledVector(perp, 0.28).normalize();
    const chestDirB = citDir.clone().addScaledVector(perp, -0.35).add(new THREE.Vector3(0, -0.25, 0)).normalize();
    addChestOnPlanet(`off-chest-${idx}-a`, planet, chestDirA, op.chestWeapon, 180, op.chestLabel);
    addChestOnPlanet(`off-chest-${idx}-b`, planet, chestDirB, undefined, 200, `+200 Shards (${planet.name} Vault)`);

    // 8 Breakable Crystal Clusters per Off-World Planet!
    const cMat = new THREE.MeshPhysicalMaterial({
      color: op.crystalCol,
      emissive: op.crystalCol,
      emissiveIntensity: 1.3,
      roughness: 0.15,
      clearcoat: 1.0,
    });
    for (let k = 0; k < 8; k++) {
      const ang = (k / 8) * Math.PI * 2;
      const cDir = new THREE.Vector3(Math.cos(ang), Math.sin(k * 1.9) * 0.65, Math.sin(ang)).normalize();
      const cPos = getPlanetSurfacePosition(planet, cDir, 0);
      const mesh = new THREE.Mesh(new THREE.OctahedronGeometry(1.15, 0), cMat);
      mesh.scale.set(0.8, 2.3, 0.8);
      mesh.position.copy(cPos).addScaledVector(cDir, 1.3);
      mesh.quaternion.setFromUnitVectors(upRef, cDir);
      group.add(mesh);
      crystals.push({ planetId: planet.id, pos: cPos, mesh, hp: 50, destroyed: false });
    }
  });

  return {
    group,
    citadels,
    chests,
    crystals,
    update(time: number, curSunDir: THREE.Vector3) {
      sunUniform.value.copy(curSunDir).normalize();
      auRing.rotation.z = time * 0.04;
      lavaMat.emissiveIntensity = 2.0 + Math.sin(time * 2.5) * 0.45;
      for (const c of citadels) {
        if (!c.cleared) {
          c.coreMesh.rotation.y = time * 1.8;
          c.coreRing.rotation.x = time * 2.0;
          c.coreRing.rotation.z = -time * 1.4;
        }
      }
      for (const cr of crystals) {
        if (!cr.destroyed) cr.mesh.rotation.y = time * 1.1;
      }
    },
  };
}
